diff --git a/be/src/pcap_watch.h b/be/src/pcap_watch.h
new file mode 100644
index 0000000..45b526a
--- /dev/null
+++ b/be/src/pcap_watch.h
@@ -0,0 +1,238 @@
+#ifndef PCAP_WATCH_H
+#define PCAP_WATCH_H
+
+#include <algorithm>
+#include <array>
+#include <deque>
+#include <filesystem>
+#include <functional>
+#include <iostream>
+#include <set>
+#include <string>
+#include <sys/inotify.h>
+#include <sys/wait.h>
+#include <unistd.h>
+#include <vector>
+
+class pcap_watch {
+public:
+	using callback_t = std::function<bool(const std::filesystem::path&)>;
+
+	enum class backlog_trend {
+		stable,
+		increasing,
+		decreasing,
+	};
+
+	struct config {
+		std::filesystem::path watch_dir;
+		std::string pcap_prefix{"cap_"};
+		std::size_t ring_file_count{5};
+		std::size_t backlog_trend_threshold{1};
+	};
+
+	explicit pcap_watch(config cfg)
+		: m_config(std::move(cfg)) {}
+
+	void set_callback(callback_t callback) {
+		m_callback = std::move(callback);
+	}
+
+	template<class T>
+	void set_callback(T& instance, bool (T::*method)(const std::filesystem::path&)) {
+		m_callback = [&instance, method](const std::filesystem::path& path) {
+			return (instance.*method)(path);
+		};
+	}
+
+	template<class T>
+	void set_callback(const T& instance, bool (T::*method)(const std::filesystem::path&) const) {
+		m_callback = [&instance, method](const std::filesystem::path& path) {
+			return (instance.*method)(path);
+		};
+	}
+
+	int run() {
+		if(!m_callback) {
+			std::cerr << "[ERROR] callback is not set" << std::endl;
+			return 1;
+		}
+
+		int fd = inotify_init();
+		if(fd < 0) {
+			perror("inotify_init");
+			return 1;
+		}
+
+		int wd = inotify_add_watch(fd, m_config.watch_dir.c_str(), IN_CLOSE_WRITE);
+		if(wd < 0) {
+			perror("inotify_add_watch");
+			close(fd);
+			return 1;
+		}
+
+		std::cout << "[START] Monitoring " << m_config.watch_dir << "..." << std::endl;
+		rescan_pcaps();
+
+		std::array<char, 16 * 1024> event_buf{};
+		while(true) {
+			ssize_t len = read(fd, event_buf.data(), event_buf.size());
+			if(len < 0) {
+				break;
+			}
+
+			for(ssize_t offset = 0; offset < len;) {
+				auto* event = reinterpret_cast<struct inotify_event*>(event_buf.data() + offset);
+				offset += sizeof(struct inotify_event) + event->len;
+
+				if(event->mask & IN_Q_OVERFLOW) {
+					std::cerr << "[WARN] inotify queue overflow, rescanning directory" << std::endl;
+					rescan_pcaps();
+					continue;
+				}
+
+				if(event->len > 0) {
+					std::string filename = event->name;
+					if(is_target_pcap(filename) && !m_processed_files.contains(filename)) {
+						enqueue_pending(filename);
+						process_pending_pcaps();
+					}
+				}
+			}
+		}
+
+		inotify_rm_watch(fd, wd);
+		close(fd);
+
+		return 0;
+	}
+
+private:
+	bool is_target_pcap(const std::string& filename) const {
+		return filename.find(m_config.pcap_prefix) != std::string::npos &&
+		       filename.find(".pcap") != std::string::npos;
+	}
+
+	void remember_processed(const std::string& filename) {
+		if(!m_processed_files.insert(filename).second) {
+			return;
+		}
+
+		m_processed_order.push_back(filename);
+		while(m_processed_order.size() > m_config.ring_file_count) {
+			m_processed_files.erase(m_processed_order.front());
+			m_processed_order.pop_front();
+		}
+	}
+
+	void report_pending_count(std::size_t pending_count) {
+		if(!m_has_last_pending_count) {
+			std::cout << "[BACKLOG] pending=" << pending_count << std::endl;
+			m_has_last_pending_count = true;
+			m_last_pending_count = pending_count;
+			return;
+		}
+
+		if(pending_count > m_last_pending_count) {
+			++m_increase_streak;
+			m_decrease_streak = 0;
+			if(m_increase_streak >= m_config.backlog_trend_threshold &&
+			   (m_backlog_trend != backlog_trend::increasing ||
+			    (m_increase_streak % m_config.backlog_trend_threshold) == 0)) {
+				std::cout << "[BACKLOG] pending=" << pending_count
+				          << " (+" << (pending_count - m_last_pending_count) << ", increasing)"
+				          << std::endl;
+				m_backlog_trend = backlog_trend::increasing;
+			}
+		}
+		else if(pending_count < m_last_pending_count) {
+			++m_decrease_streak;
+			m_increase_streak = 0;
+			if(m_decrease_streak >= m_config.backlog_trend_threshold &&
+			   (m_backlog_trend != backlog_trend::decreasing ||
+			    (m_decrease_streak % m_config.backlog_trend_threshold) == 0)) {
+				std::cout << "[BACKLOG] pending=" << pending_count
+				          << " (-" << (m_last_pending_count - pending_count) << ", decreasing)"
+				          << std::endl;
+				m_backlog_trend = backlog_trend::decreasing;
+			}
+		}
+		else {
+			m_increase_streak = 0;
+			m_decrease_streak = 0;
+			if(m_backlog_trend != backlog_trend::stable) {
+				std::cout << "[BACKLOG] pending=" << pending_count << " (stable)" << std::endl;
+				m_backlog_trend = backlog_trend::stable;
+			}
+		}
+
+		m_last_pending_count = pending_count;
+	}
+
+	void enqueue_pending(const std::string& filename) {
+		if(m_processed_files.contains(filename) || !m_pending_files.insert(filename).second) {
+			return;
+		}
+
+		m_pending_order.push_back(filename);
+	}
+
+	void process_pending_pcaps() {
+		report_pending_count(m_pending_order.size());
+
+		while(!m_pending_order.empty()) {
+			const std::string& filename = m_pending_order.front();
+			if(m_callback(m_config.watch_dir / filename)) {
+				remember_processed(filename);
+				m_pending_files.erase(filename);
+				m_pending_order.pop_front();
+			}
+			else {
+				break;
+			}
+
+			report_pending_count(m_pending_order.size());
+		}
+	}
+
+	void rescan_pcaps() {
+		std::vector<std::string> filenames;
+
+		for(const auto& entry : std::filesystem::directory_iterator(m_config.watch_dir)) {
+			if(!entry.is_regular_file()) {
+				continue;
+			}
+
+			std::string filename = entry.path().filename().string();
+			if(is_target_pcap(filename) &&
+			   !m_processed_files.contains(filename) &&
+			   !m_pending_files.contains(filename)) {
+				filenames.push_back(std::move(filename));
+			}
+		}
+
+		std::sort(filenames.begin(), filenames.end());
+		if(!filenames.empty()) {
+			filenames.pop_back();
+		}
+		for(const auto& filename : filenames) {
+			enqueue_pending(filename);
+		}
+
+		process_pending_pcaps();
+	}
+
+	config m_config;
+	callback_t m_callback;
+	std::set<std::string> m_processed_files;
+	std::deque<std::string> m_processed_order;
+	std::set<std::string> m_pending_files;
+	std::deque<std::string> m_pending_order;
+	bool m_has_last_pending_count{false};
+	std::size_t m_last_pending_count{0};
+	backlog_trend m_backlog_trend{backlog_trend::stable};
+	std::size_t m_increase_streak{0};
+	std::size_t m_decrease_streak{0};
+};
+
+#endif /* PCAP_WATCH_H */
diff --git a/be/src/tshark_command.h b/be/src/tshark_command.h
new file mode 100644
index 0000000..9bd66cb
--- /dev/null
+++ b/be/src/tshark_command.h
@@ -0,0 +1,187 @@
+#ifndef TSHARK_COMMAND_H
+#define TSHARK_COMMAND_H
+
+#include <filesystem>
+#include <string>
+#include <string_view>
+#include <vector>
+
+namespace tshark {
+
+inline std::string shell_quote(std::string_view value) {
+	std::string quoted;
+	quoted.reserve(value.size() + 2);
+	quoted.push_back('\'');
+	for(char ch : value) {
+		if(ch == '\'') {
+			quoted += "'\\''";
+		}
+		else {
+			quoted.push_back(ch);
+		}
+	}
+	quoted.push_back('\'');
+	return quoted;
+}
+
+class command_builder {
+public:
+	explicit command_builder(std::string program = "tshark")
+		: m_program(std::move(program)) {
+	}
+
+	command_builder& arg(std::string value) {
+		m_args.push_back(std::move(value));
+		return *this;
+	}
+
+	command_builder& flag(std::string name) {
+		m_args.push_back(std::move(name));
+		return *this;
+	}
+
+	command_builder& option(std::string name, std::string value) {
+		m_args.push_back(std::move(name));
+		m_args.push_back(std::move(value));
+		return *this;
+	}
+
+	command_builder& read_file(const std::filesystem::path& path) {
+		return option("-r", path.string());
+	}
+
+	command_builder& no_name_resolution() {
+		return flag("-n");
+	}
+
+	command_builder& quiet() {
+		return flag("-q");
+	}
+
+	command_builder& fields_output() {
+		return option("-T", "fields");
+	}
+
+	command_builder& header(bool enabled) {
+		return option("-E", enabled ? "header=y" : "header=n");
+	}
+
+	command_builder& tab_separator() {
+		return option("-E", "separator=\t");
+	}
+
+	command_builder& field(std::string name) {
+		m_args.push_back("-e");
+		m_args.push_back(std::move(name));
+		return *this;
+	}
+
+	command_builder& decode_as(std::string spec) {
+		return option("-d", std::move(spec));
+	}
+
+	command_builder& disable_protocol(std::string proto) {
+		return option("--disable-protocol", std::move(proto));
+	}
+
+	command_builder& redirect_stderr_to_devnull() {
+		m_redirect_stderr = true;
+		return *this;
+	}
+
+	std::string build() const {
+		std::string command = shell_quote(m_program);
+		for(const auto& arg : m_args) {
+			command.push_back(' ');
+			command += shell_quote(arg);
+		}
+		if(m_redirect_stderr) {
+			command += " 2>/dev/null";
+		}
+		return command;
+	}
+
+private:
+	std::string m_program;
+	std::vector<std::string> m_args;
+	bool m_redirect_stderr{false};
+};
+
+inline void append_default_decode_rules(command_builder& cmd) {
+	for(int port : {4201, 4202, 4203, 4204, 4205}) {
+		cmd.decode_as("udp.port==" + std::to_string(port) + ",srt");
+	}
+	for(int port : {5000, 5002, 5004,
+	                5100, 5102, 5104,
+	                5200, 5202, 5204,
+	                5300, 5302, 5304,
+	                5400, 5402, 5404}) {
+		cmd.decode_as("udp.port==" + std::to_string(port) + ",rtp");
+	}
+}
+
+inline void append_default_fields(command_builder& cmd) {
+	for(const char* field : {
+		    "frame.interface_id",
+		    "frame.interface_name",
+		    "frame.number",
+		    "frame.time_epoch",
+		    "frame.len",
+		    "_ws.col.protocol",
+		    "ip.proto",
+		    "ipv6.nxt",
+		    "ip.src",
+		    "ipv6.src",
+		    "udp.srcport",
+		    "ip.dst",
+		    "ipv6.dst",
+		    "udp.dstport",
+		    "ip.len",
+		    "rtp.ssrc",
+		    "rtp.seq",
+		    "rtp.timestamp",
+		    "rtp.p_type",
+		    "srt.iscontrol",
+		    "srt.type",
+		    "srt.seqno",
+		    "srt.msg.rexmit",
+		    "srt.msg.order",
+		    "srt.nak_seqno",
+		    "srt.rtt",
+		    "srt.rttvar",
+		    "srt.rate",
+		    "srt.rcvrate",
+		    "srt.bw",
+		    "srt.timestamp",
+		    "srt.hs.sid",
+		    "_ws.col.info",
+	    }) {
+		cmd.field(field);
+	}
+}
+
+inline std::string build_default_read_command(const std::filesystem::path& path) {
+	command_builder cmd;
+
+	cmd.read_file(path)
+	   .no_name_resolution()
+	   .quiet()
+	   .fields_output()
+	   .header(true)
+	   .tab_separator();
+
+	append_default_decode_rules(cmd);
+
+	cmd.disable_protocol("h264")
+	   .disable_protocol("mp2t");
+
+	append_default_fields(cmd);
+
+	cmd.redirect_stderr_to_devnull();
+
+	return cmd.build();
+}
+
+} // namespace tshark
+
+#endif /* TSHARK_COMMAND_H */
