#include "tsv.h"

class monitor {
public:
	using input_mode = pcap_input::mode;
	using input_config = pcap_input::config;

	using log_config = log_pipeline::config;

	struct config {
		log_config log;
		input_config input;
		tshark::read_config tshark;
		std::string protocol_map_file;
		std::string alert_config_file;
		double reorder_holdback_sec{0.5};
	};

	monitor();
	explicit monitor(config cfg);
	virtual ~monitor();

	int init();
	int run();

private:
	config m_cfg;
	int m_init_status{0};
	std::unique_ptr<log_pipeline> m_logs;
	std::unique_ptr<alert_evaluator> m_alerts;
	std::unique_ptr<pcap_input::source> m_pcap_source;
	std::unique_ptr<stream_registry> m_streams;
	std::unique_ptr<netif::interfaces> m_interfaces;
	protocol_map m_protocol_map;
	metrics::second_boundary m_second_boundary;
	packet_reorder_buffer m_reorder;
	std::optional<tsv::ctx> m_reorder_tsv_ctx;

	bool process_pcap(const std::filesystem::path&);
	int process_tsv(FILE* pipe);
	int process_ordered_line(tsv::ctx &tc, std::string_view line);
	void flush_reorder_ready();
	void flush_reorder_all();
	void update_second_boundary_state(double now);
	json build_metrics_root(double now, const packet_context &packet);
	void evaluate_alerts(double now, const json &metrics_root);
	void write_second_boundary_outputs(double now, const packet_context &packet);
};

#endif /* MONITOR_H */
/* -*- coding: utf-8 -*- */

#include "app.h"

#include <unistd.h>

#include <cstdint>
#include <cstdio>
#include <functional>
#include <string>

#include "app_config.h"
#include "cmdline.h"
#include "json.h"
#include "pcap_watch.h"
#include "task.h"
#include "trace.h"
#include "util.h"

static const char VERSION_STR[] = "0.0";



//--------------------------------------------------------------------------------
app::app() {
	m_abort = false;
}

//--------------------------------------------------------------------------------
app::~app() {
}

//--------------------------------------------------------------------------------
int app::run(int argc, char *argv[]) {
	if(parse_options(argc, argv, &m_param) != 0) {
		return -1;
	}

    task reporter(std::bind(&app::report, this), 1000);
    reporter.start();

    m_monitor = std::make_unique<monitor>(monitor::config{
		    .log = {
			    .dir = m_param.log_dir,
			    .event_journal_dir = m_param.event_journal_dir,
			    .metrics_journal_dir = m_param.metrics_journal_dir,
			    .journal_part_size_bytes = m_param.journal_part_size_bytes,
			    .journal_retention_hours = m_param.journal_retention_hours,
		    },
		    .input = {
			    .input_mode = m_param.input_mode,
			    .watch_dir = m_param.input_watch_dir,
			    .file = m_param.input_file,
			    .dir = m_param.input_dir,
			    .pcap_prefix = m_param.pcap_prefix,
			    .ring_file_count = m_param.pcap_ring_files,
			    .backlog_trend_threshold = m_param.pcap_backlog_trend_threshold,
		    },
		    .tshark = m_param.tshark,
		    .protocol_map_file = m_param.protocol_map_file,
		    .alert_config_file = m_param.alert_config_file,
	    });

	int rc = 0;
	if(!m_abort) {
		rc = m_monitor->run();
	}

    reporter.stop();

	return rc;
}

//--------------------------------------------------------------------------------
int app::stop() {
	m_abort = true;

	return 0;
}

//--------------------------------------------------------------------------------
std::string app::status() {
	std::string s;

