#ifndef STREAM_HLS_H
#define STREAM_HLS_H

#include <cstdint>
#include <deque>
#include <memory>
#include <string>
#include <unordered_map>
#include <utility>
#include <vector>

#include "endpoint.h"
#include "event.h"
#include "metrics_common.h"
#include "streams.h"
#include "tsv.h"

namespace hls {

struct timeout_config {
	double flow_idle_sec{10.0};
	double stream_idle_sec{30.0};
	double playlist_stall_sec{15.0};
	double error_recovery_sec{5.0};
	double fallback_grace_sec{0.1};
	double response_timeout_sec{3.0};
};

struct config {
	timeout_config timeout;
};

struct info {
	std::uint32_t interface_id{0};
	std::string interface_name;
	tsv::vlan_info vlan;
	ip_endpoint src{};
	ip_endpoint dst{};
	double time_epoch{0.0};
	std::uint32_t frame_len{0};
	std::uint32_t tcp_stream{0};
	bool has_tcp_stream{false};
	std::uint32_t tcp_len{0};
	bool has_tcp_payload{false};
	bool is_request{false};
	bool is_response{false};
	bool payload_seen{false};
	std::string method;
	std::string host;
	std::uint16_t port{0};
	std::string path;
	std::string role{"other"};
	std::uint16_t status_code{0};
	std::uint16_t effective_status_code{0};
	bool inferred_success{false};
	std::string status_source{"none"};
	std::uint64_t content_length{0};
	bool has_content_length{false};
	double request_time{0.0};
	bool has_request_time{false};
};

struct stream_id {
	std::uint32_t interface_id{0};
	std::string host;
	std::uint16_t port{0};
	std::string playlist_path;
	tsv::vlan_info vlan;

	static stream_id from_playlist(std::uint32_t interface_id,
	                               std::string_view host,
	                               std::uint16_t port,
	                               std::string_view playlist_path,
	                               tsv::vlan_info vlan = {});
	std::string to_stream_key() const;
	bool operator==(const stream_id&) const = default;
};

struct stream_id_hash {
	std::size_t operator()(const stream_id& v) const noexcept;
};

struct flow_id {
	std::uint32_t interface_id{0};
	std::string host;
	std::uint16_t port{0};
	std::string path;
	std::string role;
	tsv::vlan_info vlan;

	static flow_id from_request(std::uint32_t interface_id,
	                            std::string_view host,
	                            std::uint16_t port,
	                            std::string_view path,
	                            std::string_view role,
	                            tsv::vlan_info vlan = {});
	std::string to_flow_key(const stream_id& sid) const;
