class hls_dispatch_state {
public:
	struct config {
		double ttl_sec{300.0};
		double fallback_delay_sec{2.0};
	};

	hls_dispatch_state();
	explicit hls_dispatch_state(config cfg);

	bool known(const std::string &conn_key) const;
	bool tcp_fallback_ready(const std::string &conn_key, double now) const;
	void remember_candidate(const std::string &conn_key, double now);
	void remember_detailed(const std::string &conn_key, double now);
	void prune(double now);

private:
