   918	int streams::flush_deferred(double now) {
   919		int rc = 0;
   920		for(auto it = m_deferred_by_connection.begin(); it != m_deferred_by_connection.end(); ) {
   921			if((now - it->second.response.time_epoch) < m_cfg.timeout.fallback_grace_sec) {
   922				++it;
   923				continue;
   924			}
   925	
   926			auto deferred = std::move(it->second);
   927			it = m_deferred_by_connection.erase(it);
   928			if(!pop_connection_pending(deferred.conn_key, deferred.req)) {
   929				continue;
   930			}
   931			erase_tcp_pending(deferred.req);
   932			trace(3, "hls: deferred tcp fallback expired role=%s path=%s conn=%s grace=%.3f bytes=%llu",
   933			      deferred.req.fid.role.c_str(),
   934			      deferred.req.fid.path.c_str(),
   935			      deferred.conn_key.c_str(),
   936			      m_cfg.timeout.fallback_grace_sec,
   937			      static_cast<unsigned long long>(deferred.response.content_length));
   938			rc |= process_response(std::move(deferred.response), deferred.req, "tcp_fallback_timeout", 1, deferred.conn_key);
   939		}
   940		return rc;
   941	}
   942	
   943	int streams::flush_pending_timeouts(double now) {
   944		if(m_cfg.timeout.response_timeout_sec <= 0.0) {
   945			return 0;
   946		}
   947	
   948		int rc = 0;
   949		for(auto it = m_pending_by_connection.begin(); it != m_pending_by_connection.end(); ) {
   950			if(m_deferred_by_connection.find(it->first) != m_deferred_by_connection.end()) {
   951				++it;
   952				continue;
   953			}
   954	
   955			auto &queue = it->second;
   956			while(!queue.empty() && (now - queue.front().request_time) >= m_cfg.timeout.response_timeout_sec) {
   957				auto req = queue.front();
   958				const std::size_t conn_pending = queue.size();
   959				queue.pop_front();
   960				erase_tcp_pending(req);
   961	
   962				info response;
   963				response.interface_id = req.sid.interface_id;
   964				response.vlan = req.sid.vlan;
   965				response.time_epoch = now;
   966				response.is_response = true;
   967	
   968				const auto payload = m_last_payload_by_connection.find(it->first);
   969				const bool connection_payload_seen = payload != m_last_payload_by_connection.end() &&
   970				                                     payload->second >= req.request_time;
   971				if(req.fid.role == "playlist" && connection_payload_seen) {
   972					response.payload_seen = true;
   973					response.status_source = "connection_payload_fallback";
   974					trace(3, "hls: pending playlist treated as payload fallback role=%s path=%s conn=%s timeout=%.3f",
   975					      req.fid.role.c_str(),
   976					      req.fid.path.c_str(),
   977					      it->first.c_str(),
   978					      m_cfg.timeout.response_timeout_sec);
   979					rc |= process_response(std::move(response), req, "connection_payload_fallback", conn_pending, it->first);
   980				}
   981				else {
   982					response.status_code = 504;
   983					response.effective_status_code = 504;
   984					response.status_source = "timeout";
   985					trace(3, "hls: pending request timed out role=%s path=%s conn=%s timeout=%.3f",
   986					      req.fid.role.c_str(),
   987					      req.fid.path.c_str(),
   988					      it->first.c_str(),
   989					      m_cfg.timeout.response_timeout_sec);
   990					rc |= process_response(std::move(response), req, "response_timeout", conn_pending, it->first);
   991				}
   992			}
   993	
   994			if(queue.empty()) {
   995				m_last_payload_by_connection.erase(it->first);
   996				it = m_pending_by_connection.erase(it);
   997			}
   998			else {
   999				++it;
  1000			}
  1001		}
  1002		return rc;
  1003	}
