  1009	int streams::process(tsv::ctx &c, const tsv::row_t &row, const std::vector<std::string> &target_ids, const std::string &stream_name) {
  1010		info i;
  1011		if(parse_row(c, row, i) != 0) {
  1012			return 0;
  1013		}
  1014	
  1015		int rc = 0;
  1016		if(i.is_response || (!i.is_request && i.has_tcp_payload)) {
  1017			const bool is_tcp_fallback = !i.is_response && i.has_tcp_payload;
  1018			bool matched = false;
  1019			const char *matched_by = "none";
  1020			pending_request req{};
  1021			const std::string conn_key = connection_key(i);
  1022			if(i.has_tcp_payload) {
  1023				m_last_payload_by_connection[conn_key] = i.time_epoch;
  1024			}
  1025			auto conn = m_pending_by_connection.find(conn_key);
  1026			const std::size_t conn_pending = conn == m_pending_by_connection.end() ? 0U : conn->second.size();
  1027			if(conn != m_pending_by_connection.end() && !conn->second.empty()) {
  1028				const auto candidate = conn->second.front();
  1029				if(is_tcp_fallback && !is_server_to_client_payload(candidate.fid, i)) {
  1030					trace(4, "hls: tcp payload ignored direction role=%s path=%s src=%s dst=%s server_port=%u",
  1031					      candidate.fid.role.c_str(),
  1032					      candidate.fid.path.c_str(),
  1033					      endpoint_key(i.src).c_str(),
  1034					      endpoint_key(i.dst).c_str(),
  1035					      static_cast<unsigned>(candidate.fid.port));
  1036					rc |= flush_deferred(i.time_epoch);
  1037					rc |= flush_pending_timeouts(i.time_epoch);
  1038					return rc;
  1039				}
  1040				req = candidate;
  1041				matched = true;
  1042				matched_by = "connection";
  1043			}
  1044			else if(i.has_tcp_stream) {
  1045				auto pending = m_pending_by_tcp_stream.find(i.tcp_stream);
  1046				if(pending != m_pending_by_tcp_stream.end()) {
  1047					const auto candidate = pending->second;
  1048					if(is_tcp_fallback && !is_server_to_client_payload(candidate.fid, i)) {
  1049						trace(4, "hls: tcp payload ignored direction role=%s path=%s src=%s dst=%s server_port=%u",
  1050						      candidate.fid.role.c_str(),
  1051						      candidate.fid.path.c_str(),
  1052						      endpoint_key(i.src).c_str(),
  1053						      endpoint_key(i.dst).c_str(),
  1054						      static_cast<unsigned>(candidate.fid.port));
  1055						rc |= flush_deferred(i.time_epoch);
  1056						rc |= flush_pending_timeouts(i.time_epoch);
  1057						return rc;
  1058					}
  1059					req = candidate;
  1060					matched = true;
  1061					matched_by = "tcp_stream";
  1062				}
  1063			}
  1064			if(!matched) {
  1065				if(is_tcp_fallback) {
  1066					rc |= observe_connection_payload(conn_key, i);
  1067				}
  1068				trace(4, "hls: response unmatched status=%u tcp_payload=%d tcp_len=%u conn=%s conn_pending=%zu has_tcp_stream=%d tcp_stream=%u src=%s dst=%s",
  1069				      static_cast<unsigned>(i.status_code),
  1070				      i.has_tcp_payload ? 1 : 0,
  1071				      static_cast<unsigned>(i.tcp_len),
  1072				      conn_key.c_str(),
  1073				      conn_pending,
  1074				      i.has_tcp_stream ? 1 : 0,
  1075				      static_cast<unsigned>(i.tcp_stream),
  1076				      endpoint_key(i.src).c_str(),
  1077				      endpoint_key(i.dst).c_str());
  1078				rc |= flush_deferred(i.time_epoch);
  1079				rc |= flush_pending_timeouts(i.time_epoch);
  1080				return rc;
  1081			}
  1082	
  1083			if(is_tcp_fallback) {
  1084				auto deferred = m_deferred_by_connection.find(conn_key);
  1085				if(deferred == m_deferred_by_connection.end()) {
  1086					i.payload_seen = true;
  1087					if(!i.has_content_length) {
  1088						i.content_length = i.tcp_len;
  1089						i.has_content_length = true;
  1090					}
  1091					m_deferred_by_connection.emplace(conn_key, deferred_response{req, i, conn_key});
  1092					trace(3, "hls: tcp fallback deferred role=%s path=%s conn=%s grace=%.3f tcp_len=%u bytes=%llu",
  1093					      req.fid.role.c_str(),
  1094					      req.fid.path.c_str(),
  1095					      conn_key.c_str(),
  1096					      m_cfg.timeout.fallback_grace_sec,
  1097					      static_cast<unsigned>(i.tcp_len),
  1098					      static_cast<unsigned long long>(i.content_length));
  1099				}
  1100				else if(same_request(deferred->second.req, req)) {
  1101					auto &response = deferred->second.response;
  1102					const std::uint64_t payload_bytes = i.has_content_length ? i.content_length : i.tcp_len;
  1103					response.payload_seen = true;
  1104					response.has_tcp_payload = response.has_tcp_payload || i.has_tcp_payload;
  1105					response.has_content_length = true;
  1106					response.content_length += payload_bytes;
  1107					response.tcp_len = i.tcp_len;
  1108					response.time_epoch = i.time_epoch;
  1109					trace(4, "hls: tcp fallback accumulated conn=%s tcp_len=%u total_bytes=%llu",
  1110					      conn_key.c_str(),
  1111					      static_cast<unsigned>(i.tcp_len),
  1112					      static_cast<unsigned long long>(response.content_length));
  1113				}
  1114				else {
  1115					trace(4, "hls: extra tcp fallback ignored for different request conn=%s tcp_len=%u",
  1116					      conn_key.c_str(),
  1117					      static_cast<unsigned>(i.tcp_len));
  1118				}
  1119				rc |= flush_deferred(i.time_epoch);
  1120				rc |= flush_pending_timeouts(i.time_epoch);
  1121				return rc;
  1122			}
  1123	
  1124			auto deferred = m_deferred_by_connection.find(conn_key);
  1125			if(deferred != m_deferred_by_connection.end() && same_request(deferred->second.req, req)) {
  1126				const auto &fallback = deferred->second.response;
  1127				if(fallback.payload_seen && fallback.content_length > i.content_length) {
  1128					i.payload_seen = true;
  1129					i.has_tcp_payload = i.has_tcp_payload || fallback.has_tcp_payload;
  1130					i.has_content_length = true;
  1131					i.content_length = fallback.content_length;
  1132					trace(3, "hls: http status kept fallback bytes status=%u role=%s path=%s conn=%s bytes=%llu",
  1133					      static_cast<unsigned>(i.status_code),
  1134					      req.fid.role.c_str(),
  1135					      req.fid.path.c_str(),
  1136					      conn_key.c_str(),
  1137					      static_cast<unsigned long long>(i.content_length));
  1138				}
  1139			}
  1140			m_deferred_by_connection.erase(conn_key);
  1141			pop_connection_pending(conn_key, req);
  1142			erase_tcp_pending(req);
  1143			rc |= process_response(std::move(i), req, matched_by, conn_pending, conn_key);
  1144			rc |= flush_deferred(i.time_epoch);
  1145			rc |= flush_pending_timeouts(i.time_epoch);
  1146			return rc;
  1147		}
  1148	
  1149		const auto hk = host_key(i.interface_id, i.host, i.port, i.vlan);
  1150		const bool has_known_playlist = m_playlists_by_host.find(hk) != m_playlists_by_host.end();
  1151		if(i.role == "other" && !has_known_playlist) {
  1152			trace(4, "hls: ignore other request without playlist host=%s port=%u path=%s",
  1153			      i.host.c_str(), static_cast<unsigned>(i.port), i.path.c_str());
  1154			rc |= flush_deferred(i.time_epoch);
  1155			rc |= flush_pending_timeouts(i.time_epoch);
  1156			return rc;
  1157		}
  1158		const auto sid = resolve_stream_id(i);
  1159		merge_monitoring_target_ids(m_monitoring_target_ids[sid], target_ids);
  1160		if(!stream_name.empty()) {
  1161			m_stream_display_names[sid] = stream_name;
  1162			m_events.set_stream_display_name(sid.to_stream_key(), stream_name);
  1163		}
  1164		const auto fid = flow_id::from_request(i.interface_id, i.host, i.port, i.path, i.role, i.vlan);
  1165		if(i.role == "playlist") {
  1166			auto &playlists = m_playlists_by_host[hk];
  1167			if(std::find(playlists.begin(), playlists.end(), i.path) == playlists.end()) {
  1168				playlists.push_back(i.path);
  1169				std::sort(playlists.begin(), playlists.end(), [](const auto &lhs, const auto &rhs) {
  1170					return path_dir(lhs).size() > path_dir(rhs).size();
  1171				});
  1172			}
  1173		}
  1174		pending_request req{sid, fid, i.time_epoch};
  1175		const std::string conn_key = connection_key(i);
  1176		auto &queue = m_pending_by_connection[conn_key];
  1177		queue.push_back(req);
  1178		remember_connection_activity(conn_key, sid, fid);
  1179		if(i.has_tcp_stream) {
  1180			m_pending_by_tcp_stream[i.tcp_stream] = req;
  1181		}
  1182		trace(3, "hls: request registered method=%s role=%s path=%s conn=%s conn_pending=%zu has_tcp_stream=%d tcp_stream=%u stream=%s flow=%s",
  1183		      i.method.c_str(),
  1184		      i.role.c_str(),
  1185		      i.path.c_str(),
