 977			if((now - last_activity) >= m_cfg.timeout.response_idle_sec) {
 978				++it;
 979				rc |= complete_deferred(conn_key, "payload_idle_timeout");
 980				continue;
 981			}
 982			++it;
 983		}
 984		return rc;
