 987	int streams::flush_pending_timeouts(double now) {
 988		if(m_cfg.timeout.response_timeout_sec <= 0.0) {
 989			return 0;
 990		}
 991	
 992		int rc = 0;
 993		for(auto it = m_pending_by_connection.begin(); it != m_pending_by_connection.end(); ) {
 994			if(m_deferred_by_connection.find(it->first) != m_deferred_by_connection.end()) {
 995				++it;
 996				continue;
 997			}
 998	
 999			auto &queue = it->second;
1000			while(!queue.empty() && (now - queue.front().request_time) >= m_cfg.timeout.response_timeout_sec) {
1001				auto req = queue.front();
1002				const std::size_t conn_pending = queue.size();
1003				queue.pop_front();
1004				erase_tcp_pending(req);
1005	
1006				info response;
1007				response.interface_id = req.sid.interface_id;
1008				response.vlan = req.sid.vlan;
1009				response.time_epoch = now;
1010				response.is_response = true;
1011	
1012				const auto payload = m_last_payload_by_connection.find(it->first);
1013				const bool connection_payload_seen = payload != m_last_payload_by_connection.end() &&
1014				                                     payload->second >= req.request_time;
1015				if(req.fid.role == "playlist" && connection_payload_seen) {
1016					response.payload_seen = true;
1017					response.status_source = "connection_payload_fallback";
1018					trace(3, "hls: pending playlist treated as payload fallback role=%s path=%s conn=%s timeout=%.3f",
1019					      req.fid.role.c_str(),
1020					      req.fid.path.c_str(),
1021					      it->first.c_str(),
1022					      m_cfg.timeout.response_timeout_sec);
1023					rc |= process_response(std::move(response), req, "connection_payload_fallback", conn_pending, it->first);
1024				}
1025				else {
1026					response.status_code = 504;
1027					response.effective_status_code = 504;
1028					response.status_source = "timeout";
1029					trace(3, "hls: pending request timed out role=%s path=%s conn=%s timeout=%.3f",
1030					      req.fid.role.c_str(),
1031					      req.fid.path.c_str(),
1032					      it->first.c_str(),
1033					      m_cfg.timeout.response_timeout_sec);
1034					rc |= process_response(std::move(response), req, "response_timeout", conn_pending, it->first);
1035				}
1036			}
1037	
1038			if(queue.empty()) {
1039				m_last_payload_by_connection.erase(it->first);
1040				it = m_pending_by_connection.erase(it);
1041			}
1042			else {
1043				++it;
1044			}
1045		}
1046		return rc;
1047	}
