1067				m_last_payload_by_connection[conn_key] = i.time_epoch;
1068			}
1069			auto conn = m_pending_by_connection.find(conn_key);
1070			const std::size_t conn_pending = conn == m_pending_by_connection.end() ? 0U : conn->second.size();
1071			if(conn != m_pending_by_connection.end() && !conn->second.empty()) {
1072				const auto candidate = conn->second.front();
1073				if(is_tcp_fallback && !is_server_to_client_payload(candidate.fid, i)) {
1074					trace(4, "hls: tcp payload ignored direction role=%s path=%s src=%s dst=%s server_port=%u",
1075					      candidate.fid.role.c_str(),
1076					      candidate.fid.path.c_str(),
1077					      endpoint_key(i.src).c_str(),
1078					      endpoint_key(i.dst).c_str(),
1079					      static_cast<unsigned>(candidate.fid.port));
1080					rc |= flush_deferred(i.time_epoch);
1081					rc |= flush_pending_timeouts(i.time_epoch);
1082					return rc;
1083				}
1084				req = candidate;
1085				matched = true;
1086				matched_by = "connection";
1087			}
1088			else if(i.has_tcp_stream) {
1089				auto pending = m_pending_by_tcp_stream.find(i.tcp_stream);
1090				if(pending != m_pending_by_tcp_stream.end()) {
1091					const auto candidate = pending->second;
1092					if(is_tcp_fallback && !is_server_to_client_payload(candidate.fid, i)) {
1093						trace(4, "hls: tcp payload ignored direction role=%s path=%s src=%s dst=%s server_port=%u",
1094						      candidate.fid.role.c_str(),
1095						      candidate.fid.path.c_str(),
1096						      endpoint_key(i.src).c_str(),
