1099						rc |= flush_deferred(i.time_epoch);
1100						rc |= flush_pending_timeouts(i.time_epoch);
1101						return rc;
1102					}
1103					req = candidate;
1104					matched = true;
1105					matched_by = "tcp_stream";
1106				}
1107			}
1108			if(!matched) {
1109				if(is_tcp_fallback) {
1110					rc |= observe_connection_payload(conn_key, i);
1111				}
1112				trace(4, "hls: response unmatched status=%u tcp_payload=%d tcp_len=%u conn=%s conn_pending=%zu has_tcp_stream=%d tcp_stream=%u src=%s dst=%s",
1113				      static_cast<unsigned>(i.status_code),
1114				      i.has_tcp_payload ? 1 : 0,
1115				      static_cast<unsigned>(i.tcp_len),
1116				      conn_key.c_str(),
1117				      conn_pending,
1118				      i.has_tcp_stream ? 1 : 0,
1119				      static_cast<unsigned>(i.tcp_stream),
1120				      endpoint_key(i.src).c_str(),
1121				      endpoint_key(i.dst).c_str());
1122				rc |= flush_deferred(i.time_epoch);
1123				rc |= flush_pending_timeouts(i.time_epoch);
1124				return rc;
1125			}
1126	
1127			if(is_tcp_fallback) {
1128				auto deferred = m_deferred_by_connection.find(conn_key);
1129				if(deferred == m_deferred_by_connection.end()) {
1130					i.payload_seen = true;
1131					if(!i.has_content_length) {
1132						i.content_length = i.tcp_len;
1133						i.has_content_length = true;
1134					}
