1136					trace(3, "hls: tcp fallback deferred role=%s path=%s conn=%s grace=%.3f tcp_len=%u bytes=%llu",
1137					      req.fid.role.c_str(),
1138					      req.fid.path.c_str(),
1139					      conn_key.c_str(),
1140					      m_cfg.timeout.fallback_grace_sec,
1141					      static_cast<unsigned>(i.tcp_len),
1142					      static_cast<unsigned long long>(i.content_length));
1143				}
1144				else if(same_request(deferred->second.req, req)) {
