1179					      req.fid.path.c_str(),
1180					      conn_key.c_str(),
1181					      static_cast<unsigned long long>(i.content_length));
1182				}
1183			}
1184			m_deferred_by_connection.erase(conn_key);
1185			pop_connection_pending(conn_key, req);
1186			erase_tcp_pending(req);
1187			rc |= process_response(std::move(i), req, matched_by, conn_pending, conn_key);
1188			rc |= flush_deferred(i.time_epoch);
1189			rc |= flush_pending_timeouts(i.time_epoch);
1190			return rc;
1191		}
1192	
1193		const auto hk = host_key(i.interface_id, i.host, i.port, i.vlan);
1194		const bool has_known_playlist = m_playlists_by_host.find(hk) != m_playlists_by_host.end();
