1197			      i.host.c_str(), static_cast<unsigned>(i.port), i.path.c_str());
1198			rc |= flush_deferred(i.time_epoch);
1199			rc |= flush_pending_timeouts(i.time_epoch);
1200			return rc;
1201		}
1202		const auto sid = resolve_stream_id(i);
1203		merge_monitoring_target_ids(m_monitoring_target_ids[sid], target_ids);
1204		if(!stream_name.empty()) {
1205			m_stream_display_names[sid] = stream_name;
