1216			}
1217		}
1218		pending_request req{sid, fid, i.time_epoch};
1219		const std::string conn_key = connection_key(i);
1220		auto &queue = m_pending_by_connection[conn_key];
1221		queue.push_back(req);
1222		remember_connection_activity(conn_key, sid, fid);
