1227		      i.method.c_str(),
1228		      i.role.c_str(),
1229		      i.path.c_str(),
1230		      conn_key.c_str(),
1231		      queue.size(),
1232		      i.has_tcp_stream ? 1 : 0,
1233		      static_cast<unsigned>(i.tcp_stream),
1234		      sid.to_stream_key().c_str(),
1235		      fid.to_flow_key(sid).c_str());
1236	
1237		rc |= process_resolved(sid, fid, i);
1238		rc |= flush_deferred(i.time_epoch);
