 941		response.has_tcp_payload = response.has_tcp_payload || deferred.payload_bytes > 0;
 942		if(deferred.has_expected_payload_bytes && deferred_content_complete(deferred)) {
 943			response.content_length = deferred.expected_payload_bytes;
 944			response.has_content_length = true;
 945		}
 946		else if(response.payload_seen) {
 947			response.content_length = deferred.payload_bytes;
 948			response.has_content_length = true;
 949		}
