 954		      deferred.req.fid.path.c_str(),
 955		      conn_key.c_str(),
 956		      static_cast<unsigned long long>(deferred.payload_bytes),
 957		      static_cast<unsigned long long>(deferred.expected_payload_bytes),
 958		      deferred_content_complete(deferred) ? 1 : 0);
 959		return process_response(std::move(response), deferred.req, matched_by, conn_pending, conn_key);
