1020					      req.fid.path.c_str(),
1021					      it->first.c_str(),
1022					      m_cfg.timeout.response_timeout_sec);
1023					rc |= process_response(std::move(response), req, "connection_payload_fallback", conn_pending, it->first);
1024				}
1025				else {
1026					response.status_code = 504;
1027					response.effective_status_code = 504;
1028					response.status_source = "timeout";
1029					trace(3, "hls: pending request timed out role=%s path=%s conn=%s timeout=%.3f",
1030					      req.fid.role.c_str(),
1031					      req.fid.path.c_str(),
1032					      it->first.c_str(),
