 926			return 0;
 927		}
 928	
 929		auto deferred = std::move(it->second);
 930		m_deferred_by_connection.erase(it);
 931	
 932		auto pending = m_pending_by_connection.find(conn_key);
 933		const std::size_t conn_pending = pending == m_pending_by_connection.end() ? 0U : pending->second.size();
