 962	int streams::flush_deferred(double now) {
 963		if(m_cfg.timeout.response_idle_sec <= 0.0) {
 964			return 0;
 965		}
 966	
 967		int rc = 0;
 968		for(auto it = m_deferred_by_connection.begin(); it != m_deferred_by_connection.end(); ) {
 969			const std::string conn_key = it->first;
 970			const bool content_complete = deferred_content_complete(it->second);
 971			const double last_activity = it->second.last_activity_time;
 972			if(content_complete) {
 973				++it;
 974				rc |= complete_deferred(conn_key, "content_length");
 975				continue;
 976			}
 977			if((now - last_activity) >= m_cfg.timeout.response_idle_sec) {
 978				++it;
 979				rc |= complete_deferred(conn_key, "payload_idle_timeout");
 980				continue;
 981			}
 982			++it;
 983		}
 984		return rc;
 985	}
