 987	int streams::flush_pending_timeouts(double now) {
 988		if(m_cfg.timeout.response_timeout_sec <= 0.0) {
 989			return 0;
 990		}
 991	
 992		int rc = 0;
 993		for(auto it = m_pending_by_connection.begin(); it != m_pending_by_connection.end(); ) {
 994			if(m_deferred_by_connection.find(it->first) != m_deferred_by_connection.end()) {
 995				++it;
 996				continue;
 997			}
 998	
 999			auto &queue = it->second;
1000			while(!queue.empty() && (now - queue.front().request_time) >= m_cfg.timeout.response_timeout_sec) {
1001				auto req = queue.front();
1002				const std::size_t conn_pending = queue.size();
1003				queue.pop_front();
1004				erase_tcp_pending(req);
1005	
1006				info response;
1007				response.interface_id = req.sid.interface_id;
1008				response.vlan = req.sid.vlan;
1009				response.time_epoch = now;
1010				response.is_response = true;
1011	
1012				const auto payload = m_last_payload_by_connection.find(it->first);
1013				const bool connection_payload_seen = payload != m_last_payload_by_connection.end() &&
1014				                                     payload->second >= req.request_time;
