int stream::process(const info &i) {
	touch(i.time_epoch);
	m_metrics.lifetime.update(i.time_epoch);
	if(i.role == "playlist" && i.is_request) {
		m_has_playlist = true;
		m_playlist_last_seen = i.time_epoch;
	}
	if(i.is_request) {
		m_metrics.request_count.inc();
		m_metrics.request_interval.update(i.time_epoch);
	}
	if(i.is_response) {
		m_metrics.response_count.inc();
		m_metrics.status.update(i.effective_status_code);
		if(i.effective_status_code >= 400) {
			m_metrics.error_count.inc();
		}
		if(i.has_content_length) {
			m_metrics.download_bytes.add(i.content_length);
			m_metrics.bitrate.update(i.time_epoch, i.content_length);
		}
		if(i.has_request_time && i.time_epoch >= i.request_time) {
			m_metrics.download_time.add(i.time_epoch - i.request_time);
		}
	}

	const auto fid = resolve_flow_id(i);
	auto it = m_flows.find(fid);
	if(it == m_flows.end()) {
		it = m_flows.emplace(fid, std::make_unique<flow>(m_sid, fid, i.interface_name, m_cfg.timeout.error_recovery_sec, m_events)).first;
		it->second->emit_detected(i.time_epoch);
	}
	return it->second->process(i);
}

int stream::observe_transport(const flow_id &fid, const info &i) {
	touch(i.time_epoch);
	m_metrics.lifetime.update(i.time_epoch);
	const std::uint64_t bytes = i.tcp_len > 0 ? i.tcp_len : i.frame_len;
	if(bytes > 0) {
		m_metrics.download_bytes.add(bytes);
		m_metrics.bitrate.update(i.time_epoch, bytes);
	}

	if(m_has_playlist) {
		m_playlist_last_seen = i.time_epoch;
	}

	auto it = m_flows.find(fid);
	if(it == m_flows.end()) {
		it = m_flows.emplace(fid, std::make_unique<flow>(m_sid, fid, i.interface_name, m_cfg.timeout.error_recovery_sec, m_events)).first;
		it->second->emit_detected(i.time_epoch);
	}
	return it->second->observe_transport(i);
}

