flow::flow(const stream_id &sid, const flow_id fid, std::string interface_name, double error_recovery_sec, event_sink &events)
	: m_fid(std::move(fid))
	, m_stream_key(sid.to_stream_key())
	, m_flow_key(m_fid.to_flow_key(sid))
	, m_interface_name(std::move(interface_name))
	, m_error_state(error_recovery_sec)
	, m_event_source(stream_json::make_flow_event_source(proto_name,
	                                                    m_fid.interface_id,
	                                                    m_interface_name,
	                                                    m_stream_key,
	                                                    m_flow_key,
	                                                    m_fid.vlan))
	, m_events(events) {
}

int flow::process(const info &i) {
	touch(i.time_epoch);
	m_metrics.lifetime.update(i.time_epoch);
	if(!i.path.empty()) {
		m_last_path = i.path;
	}
	if(i.is_request) {
		m_metrics.request_count.inc();
		m_metrics.request_interval.update(i.time_epoch);
		if(i.role == "segment") {
			emit_segment_request(i);
		}
	}
	if(i.is_response) {
		m_metrics.response_count.inc();
		m_metrics.status.update(i.effective_status_code);
		m_last_status_code = i.status_code;
		m_last_effective_status_code = i.effective_status_code;
		m_last_inferred_success = i.inferred_success;
		m_last_status_source = i.status_source;
		if(i.effective_status_code >= 400) {
			m_metrics.error_count.inc();
			++m_error_window;
		}
		if(i.has_content_length) {
			m_metrics.download_bytes.add(i.content_length);
			m_metrics.bitrate.update(i.time_epoch, i.content_length);
		}
		double response_time = 0.0;
		if(i.has_request_time && i.time_epoch >= i.request_time) {
			response_time = i.time_epoch - i.request_time;
			m_last_response_time = response_time;
			m_metrics.download_time.add(response_time);
		}
		if(i.role == "segment") {
			emit_segment_response(i, response_time);
		}
	}
	return 0;
}

int flow::observe_transport(const info &i) {
	touch(i.time_epoch);
	m_metrics.lifetime.update(i.time_epoch);
	const std::uint64_t bytes = i.tcp_len > 0 ? i.tcp_len : i.frame_len;
	if(bytes > 0) {
		m_metrics.download_bytes.add(bytes);
		m_metrics.bitrate.update(i.time_epoch, bytes);
	}
	return 0;
}

event_record flow::make_event(double now, std::string type, json detail) const {
	return event_record{
		.time_epoch = now,
		.type = std::move(type),
		.source = m_event_source,
		.detail = std::move(detail),
	};
}

void flow::emit_detected(double now) {
	m_events.emit(make_event(now, "flow_detected", json{
		{"role", m_fid.role},
		{"endpoint", {
			{"host", m_fid.host},
			{"port", m_fid.port},
		}},
	}));
}

void flow::emit_lost(double now) {
	m_events.emit(make_event(now, "flow_lost", json{
		{"role", m_fid.role},
		{"endpoint", {
			{"host", m_fid.host},
			{"port", m_fid.port},
		}},
		{"last_path", m_last_path},
		{"last_seen", last_seen()},
	}));
}

void flow::emit_segment_request(const info &i) {
	m_events.emit(make_event(i.time_epoch, "segment_request", json{
		{"role", i.role},
		{"method", i.method},
		{"path", i.path},
		{"endpoint", {
			{"host", i.host},
			{"port", i.port},
			{"path", i.path},
		}},
	}));
}

void flow::emit_segment_response(const info &i, double response_time) {
	json detail{
		{"role", i.role},
		{"path", i.path},
		{"status_code", i.status_code},
		{"effective_status_code", i.effective_status_code},
		{"status_source", i.status_source},
		{"payload_seen", i.payload_seen},
		{"inferred_success", i.inferred_success},
		{"response_time_sec", response_time},
		{"endpoint", {
			{"host", i.host},
			{"port", i.port},
			{"path", i.path},
		}},
	};
	if(i.has_content_length) {
		detail["download_bytes"] = i.content_length;
	}
	if(i.has_request_time) {
		detail["request_time"] = i.request_time;
	}
	detail["severity"] = i.effective_status_code >= 400 ? "warning" : "info";
	trace(3, "hls: segment_response emitted status=%u effective_status=%u source=%s inferred=%d path=%s response_time=%.6f bytes=%llu",
	      static_cast<unsigned>(i.status_code),
	      static_cast<unsigned>(i.effective_status_code),
	      i.status_source.c_str(),
	      i.inferred_success ? 1 : 0,
	      i.path.c_str(),
	      response_time,
	      static_cast<unsigned long long>(i.content_length));
	m_events.emit(make_event(i.time_epoch, "segment_response", std::move(detail)));
}

int flow::append_metrics(double now, json::array_t &out) {
	const auto bitrate = m_metrics.bitrate.snapshot_at(now);
	json j = stream_json::make_flow_metrics_base(proto_name,
	                                             m_fid.interface_id,
	                                             m_interface_name,
	                                             m_stream_key,
	                                             m_flow_key,
	                                             m_fid.vlan);
	j["role"] = m_fid.role;
	j["endpoint"] = {
		{"host", m_fid.host},
		{"port", m_fid.port},
	};
	j["last_path"] = m_last_path;
	j["last_status_code"] = m_last_status_code;
	j["last_effective_status_code"] = m_last_effective_status_code;
	j["last_status_source"] = m_last_status_source;
	j["last_inferred_success"] = m_last_inferred_success;
	j["last_response_time_sec"] = m_last_response_time;
	j.update(json{
		{"request_count", { {"window", m_metrics.request_count.count()}, {"total", m_metrics.request_count.total()} }},
		{"response_count", { {"window", m_metrics.response_count.count()}, {"total", m_metrics.response_count.total()} }},
		{"error_count", { {"window", m_metrics.error_count.count()}, {"total", m_metrics.error_count.total()} }},
		{"download_bytes", { {"window", m_metrics.download_bytes.count()}, {"total", m_metrics.download_bytes.total()} }},
		{"bitrate", {
			{"bps", bitrate.bps},
			{"count", bitrate.stats.count},
			{"min", bitrate.stats.min},
			{"max", bitrate.stats.max},
			{"avg", bitrate.stats.avg()},
		}},
		{"request_interval", {
			{"seconds", m_metrics.request_interval.value()},
			{"count", m_metrics.request_interval.stats().count},
			{"min", m_metrics.request_interval.stats().min},
			{"max", m_metrics.request_interval.stats().max},
			{"max", m_metrics.request_interval.stats().max},
			{"avg", m_metrics.request_interval.stats().avg()},
		}},
		{"download_time", stats_json(m_metrics.download_time)},
		{"status", status_json(m_metrics.status)},
		{"duration", {
			{"seconds", m_metrics.lifetime.duration_sec()},
			{"first_seen", m_metrics.lifetime.first_seen()},
			{"last_seen", m_metrics.lifetime.last_seen()},
		}},
	});

	if (!bitrate.available) {
		for (const char *key : {"bps", "min", "max", "avg"}) {
			j["bitrate"][key] = nullptr;
		}
	}

	out.push_back(std::move(j));
	m_metrics_emitted = true;
	m_metrics.request_count.reset();
	m_metrics.response_count.reset();
	m_metrics.error_count.reset();
	m_metrics.download_bytes.reset();
	m_metrics.bitrate.clear_stats();
	m_metrics.request_interval.clear_stats();
	m_metrics.download_time.clear();
	m_metrics.status.reset_window();
	return 0;
}

