  1056						rc |= flush_pending_timeouts(i.time_epoch);
  1057						return rc;
  1058					}
  1059					req = candidate;
  1060					matched = true;
  1061					matched_by = "tcp_stream";
  1062				}
  1063			}
  1064			if(!matched) {
