bool streams::deferred_content_complete(const deferred_response &deferred) const {
	return deferred.has_expected_payload_bytes &&
	       deferred.payload_bytes >= deferred.expected_payload_bytes;
}

int streams::complete_deferred(const std::string &conn_key, const char *matched_by) {
	auto it = m_deferred_by_connection.find(conn_key);
	if(it == m_deferred_by_connection.end()) {
		return 0;
	}

	auto deferred = std::move(it->second);
	m_deferred_by_connection.erase(it);

	auto pending = m_pending_by_connection.find(conn_key);
	const std::size_t conn_pending = pending == m_pending_by_connection.end() ? 0U : pending->second.size();
	if(!pop_connection_pending(conn_key, deferred.req)) {
		return 0;
	}
	erase_tcp_pending(deferred.req);

	auto &response = deferred.response;
	response.payload_seen = response.payload_seen || deferred.payload_bytes > 0;
	response.has_tcp_payload = response.has_tcp_payload || deferred.payload_bytes > 0;
	if(deferred.has_expected_payload_bytes && deferred_content_complete(deferred)) {
		response.content_length = deferred.expected_payload_bytes;
		response.has_content_length = true;
	}
	else if(response.payload_seen) {
		response.content_length = deferred.payload_bytes;
		response.has_content_length = true;
	}

	trace(3, "hls: response completed by=%s role=%s path=%s conn=%s payload_bytes=%llu expected_bytes=%llu expected_complete=%d",
	      matched_by,
	      deferred.req.fid.role.c_str(),
	      deferred.req.fid.path.c_str(),
	      conn_key.c_str(),
	      static_cast<unsigned long long>(deferred.payload_bytes),
	      static_cast<unsigned long long>(deferred.expected_payload_bytes),
	      deferred_content_complete(deferred) ? 1 : 0);
	return process_response(std::move(response), deferred.req, matched_by, conn_pending, conn_key);
}

int streams::flush_deferred(double now) {
	if(m_cfg.timeout.response_idle_sec <= 0.0) {
		return 0;
	}

	int rc = 0;
	for(auto it = m_deferred_by_connection.begin(); it != m_deferred_by_connection.end(); ) {
		const std::string conn_key = it->first;
		const bool content_complete = deferred_content_complete(it->second);
		const double last_activity = it->second.last_activity_time;
		if(content_complete) {
			++it;
			rc |= complete_deferred(conn_key, "content_length");
			continue;
		}
		if((now - last_activity) >= m_cfg.timeout.response_idle_sec) {
			++it;
			rc |= complete_deferred(conn_key, "payload_idle_timeout");
			continue;
		}
		++it;
	}
	return rc;
}

int streams::flush_pending_timeouts(double now) {
	if(m_cfg.timeout.response_timeout_sec <= 0.0) {
		return 0;
	}

	int rc = 0;
	for(auto it = m_pending_by_connection.begin(); it != m_pending_by_connection.end(); ) {
		if(m_deferred_by_connection.find(it->first) != m_deferred_by_connection.end()) {
			++it;
			continue;
		}

		auto &queue = it->second;
		while(!queue.empty() && (now - queue.front().request_time) >= m_cfg.timeout.response_timeout_sec) {
			auto req = queue.front();
			const std::size_t conn_pending = queue.size();
			queue.pop_front();
			erase_tcp_pending(req);

			info response;
			response.interface_id = req.sid.interface_id;
			response.vlan = req.sid.vlan;
			response.time_epoch = now;
			response.is_response = true;

			const auto payload = m_last_payload_by_connection.find(it->first);
			const bool connection_payload_seen = payload != m_last_payload_by_connection.end() &&
			                                     payload->second >= req.request_time;
			if(req.fid.role == "playlist" && connection_payload_seen) {
				response.payload_seen = true;
				response.status_source = "connection_payload_fallback";
				trace(3, "hls: pending playlist treated as payload fallback role=%s path=%s conn=%s timeout=%.3f",
				      req.fid.role.c_str(),
				      req.fid.path.c_str(),
				      it->first.c_str(),
				      m_cfg.timeout.response_timeout_sec);
				rc |= process_response(std::move(response), req, "connection_payload_fallback", conn_pending, it->first);
			}
			else {
				response.status_code = 504;
				response.effective_status_code = 504;
				response.status_source = "timeout";
				trace(3, "hls: pending request timed out role=%s path=%s conn=%s timeout=%.3f",
				      req.fid.role.c_str(),
				      req.fid.path.c_str(),
				      it->first.c_str(),
				      m_cfg.timeout.response_timeout_sec);
				rc |= process_response(std::move(response), req, "response_timeout", conn_pending, it->first);
			}
		}

		if(queue.empty()) {
			m_last_payload_by_connection.erase(it->first);
			it = m_pending_by_connection.erase(it);
		}
		else {
			++it;
		}
	}
	return rc;
}

int streams::process(tsv::ctx &c, const tsv::row_t &row) { return process(c, row, {}); }

int streams::process(tsv::ctx &c, const tsv::row_t &row, const std::vector<std::string> &target_ids) { return process(c, row, target_ids, {}); }

int streams::process(tsv::ctx &c, const tsv::row_t &row, const std::vector<std::string> &target_ids, const std::string &stream_name) {
	info i;
	if(parse_row(c, row, i) != 0) {
		return 0;
	}

	int rc = 0;
	if(i.is_response || (!i.is_request && (i.has_tcp_payload || i.tcp_fin))) {
		const bool is_tcp_transport = !i.is_response && (i.has_tcp_payload || i.tcp_fin);
		bool matched = false;
		pending_request req{};
		const std::string conn_key = connection_key(i);
		if(i.has_tcp_payload) {
			m_last_payload_by_connection[conn_key] = i.time_epoch;
		}
		auto conn = m_pending_by_connection.find(conn_key);
		const std::size_t conn_pending = conn == m_pending_by_connection.end() ? 0U : conn->second.size();
		if(conn != m_pending_by_connection.end() && !conn->second.empty()) {
			const auto candidate = conn->second.front();
			if(is_tcp_transport && !is_server_to_client_transport(candidate.fid, i)) {
				trace(4, "hls: tcp transport ignored direction role=%s path=%s src=%s dst=%s server_port=%u",
				      candidate.fid.role.c_str(),
				      candidate.fid.path.c_str(),
				      endpoint_key(i.src).c_str(),
				      endpoint_key(i.dst).c_str(),
				      static_cast<unsigned>(candidate.fid.port));
				rc |= flush_deferred(i.time_epoch);
				rc |= flush_pending_timeouts(i.time_epoch);
				return rc;
			}
			req = candidate;
			matched = true;
		}
		else if(i.has_tcp_stream) {
			auto pending = m_pending_by_tcp_stream.find(i.tcp_stream);
			if(pending != m_pending_by_tcp_stream.end()) {
				const auto candidate = pending->second;
				if(is_tcp_transport && !is_server_to_client_transport(candidate.fid, i)) {
					trace(4, "hls: tcp transport ignored direction role=%s path=%s src=%s dst=%s server_port=%u",
					      candidate.fid.role.c_str(),
					      candidate.fid.path.c_str(),
					      endpoint_key(i.src).c_str(),
					      endpoint_key(i.dst).c_str(),
					      static_cast<unsigned>(candidate.fid.port));
					rc |= flush_deferred(i.time_epoch);
					rc |= flush_pending_timeouts(i.time_epoch);
					return rc;
				}
				req = candidate;
				matched = true;
			}
		}
		if(!matched) {
			if(is_tcp_transport && i.has_tcp_payload) {
				rc |= observe_connection_payload(conn_key, i);
			}
			trace(4, "hls: response unmatched status=%u tcp_payload=%d tcp_fin=%d tcp_len=%u conn=%s conn_pending=%zu has_tcp_stream=%d tcp_stream=%u src=%s dst=%s",
			      static_cast<unsigned>(i.status_code),
			      i.has_tcp_payload ? 1 : 0,
			      i.tcp_fin ? 1 : 0,
			      static_cast<unsigned>(i.tcp_len),
			      conn_key.c_str(),
			      conn_pending,
			      i.has_tcp_stream ? 1 : 0,
			      static_cast<unsigned>(i.tcp_stream),
			      endpoint_key(i.src).c_str(),
			      endpoint_key(i.dst).c_str());
			rc |= flush_deferred(i.time_epoch);
			rc |= flush_pending_timeouts(i.time_epoch);
			return rc;
		}

		auto deferred = m_deferred_by_connection.find(conn_key);
		if(i.is_response) {
			if(deferred == m_deferred_by_connection.end()) {
				deferred = m_deferred_by_connection.emplace(conn_key, deferred_response{req, i, conn_key}).first;
			}
			else if(!same_request(deferred->second.req, req)) {
				rc |= complete_deferred(conn_key, "next_response");
				deferred = m_deferred_by_connection.emplace(conn_key, deferred_response{req, i, conn_key}).first;
			}
			else {
				auto &response = deferred->second.response;
				const std::uint64_t payload_bytes = deferred->second.payload_bytes;
				response = i;
				response.payload_seen = response.payload_seen || payload_bytes > 0;
				response.has_tcp_payload = response.has_tcp_payload || payload_bytes > 0;
			}

			auto &state = deferred->second;
			if(i.has_tcp_payload) {
				state.payload_bytes += i.tcp_len;
			}
			state.last_activity_time = i.time_epoch;
			state.response.time_epoch = i.time_epoch;
			if(i.has_http_content_length) {
				state.expected_payload_bytes = i.http_content_length;
				state.has_expected_payload_bytes = true;
			}
			trace(3, "hls: http response deferred role=%s path=%s conn=%s status=%u payload_bytes=%llu expected_bytes=%llu",
			      req.fid.role.c_str(),
			      req.fid.path.c_str(),
			      conn_key.c_str(),
			      static_cast<unsigned>(i.status_code),
			      static_cast<unsigned long long>(state.payload_bytes),
			      static_cast<unsigned long long>(state.expected_payload_bytes));
			if(i.tcp_fin) {
				rc |= complete_deferred(conn_key, "tcp_fin");
			}
			else if(deferred_content_complete(state)) {
				rc |= complete_deferred(conn_key, "content_length");
			}
			rc |= flush_deferred(i.time_epoch);
			rc |= flush_pending_timeouts(i.time_epoch);
			return rc;
		}

		if(deferred == m_deferred_by_connection.end()) {
			i.payload_seen = i.has_tcp_payload;
			deferred = m_deferred_by_connection.emplace(conn_key, deferred_response{req, i, conn_key}).first;
		}
		if(!same_request(deferred->second.req, req)) {
			trace(4, "hls: tcp transport ignored for different request conn=%s tcp_len=%u fin=%d",
			      conn_key.c_str(), static_cast<unsigned>(i.tcp_len), i.tcp_fin ? 1 : 0);
			rc |= flush_deferred(i.time_epoch);
			rc |= flush_pending_timeouts(i.time_epoch);
			return rc;
		}

		auto &state = deferred->second;
		state.payload_bytes += i.tcp_len;
		state.response.payload_seen = state.response.payload_seen || i.has_tcp_payload;
		state.response.has_tcp_payload = state.response.has_tcp_payload || i.has_tcp_payload;
		state.response.tcp_len = i.tcp_len;
		state.response.tcp_fin = i.tcp_fin;
		state.response.time_epoch = i.time_epoch;
		state.last_activity_time = i.time_epoch;
		trace(4, "hls: tcp transport accumulated conn=%s tcp_len=%u fin=%d total_bytes=%llu",
		      conn_key.c_str(),
		      static_cast<unsigned>(i.tcp_len),
		      i.tcp_fin ? 1 : 0,
		      static_cast<unsigned long long>(state.payload_bytes));
		if(i.tcp_fin) {
			if(!state.response.payload_seen && state.response.status_code == 0) {
				state.response.status_code = 504;
				state.response.effective_status_code = 504;
				state.response.status_source = "tcp_fin_without_response";
			}
			rc |= complete_deferred(conn_key, "tcp_fin");
		}
		else if(deferred_content_complete(state)) {
			rc |= complete_deferred(conn_key, "content_length");
		}
		rc |= flush_deferred(i.time_epoch);
		rc |= flush_pending_timeouts(i.time_epoch);
		return rc;
	}

	const auto hk = host_key(i.interface_id, i.host, i.port, i.vlan);
	const bool has_known_playlist = m_playlists_by_host.find(hk) != m_playlists_by_host.end();
	if(i.role == "other" && !has_known_playlist) {
		trace(4, "hls: ignore other request without playlist host=%s port=%u path=%s",
		      i.host.c_str(), static_cast<unsigned>(i.port), i.path.c_str());
		rc |= flush_deferred(i.time_epoch);
		rc |= flush_pending_timeouts(i.time_epoch);
		return rc;
	}
	const auto sid = resolve_stream_id(i);
	merge_monitoring_target_ids(m_monitoring_target_ids[sid], target_ids);
	if(!stream_name.empty()) {
		m_stream_display_names[sid] = stream_name;
		m_events.set_stream_display_name(sid.to_stream_key(), stream_name);
	}
	const auto fid = flow_id::from_request(i.interface_id, i.host, i.port, i.path, i.role, i.vlan);
	if(i.role == "playlist") {
		auto &playlists = m_playlists_by_host[hk];
		if(std::find(playlists.begin(), playlists.end(), i.path) == playlists.end()) {
			playlists.push_back(i.path);
			std::sort(playlists.begin(), playlists.end(), [](const auto &lhs, const auto &rhs) {
				return path_dir(lhs).size() > path_dir(rhs).size();
			});
		}
	}
	pending_request req{sid, fid, i.time_epoch};
	const std::string conn_key = connection_key(i);
	if(m_deferred_by_connection.find(conn_key) != m_deferred_by_connection.end()) {
		rc |= complete_deferred(conn_key, "next_request");
	}
	auto &queue = m_pending_by_connection[conn_key];
	queue.push_back(req);
	remember_connection_activity(conn_key, sid, fid);
	if(i.has_tcp_stream) {
		m_pending_by_tcp_stream[i.tcp_stream] = req;
	}
	trace(3, "hls: request registered method=%s role=%s path=%s conn=%s conn_pending=%zu has_tcp_stream=%d tcp_stream=%u stream=%s flow=%s",
	      i.method.c_str(),
	      i.role.c_str(),
	      i.path.c_str(),
	      conn_key.c_str(),
	      queue.size(),
	      i.has_tcp_stream ? 1 : 0,
	      static_cast<unsigned>(i.tcp_stream),
	      sid.to_stream_key().c_str(),
	      fid.to_flow_key(sid).c_str());

	rc |= process_resolved(sid, fid, i);
	rc |= flush_deferred(i.time_epoch);
	rc |= flush_pending_timeouts(i.time_epoch);
	return rc;
}

int streams::append_metrics(double now, json::array_t &out) {
	flush_deferred(now);
	flush_pending_timeouts(now);
	for(auto& [sid, stream] : m_streams) {
		const auto first = out.size();
		const auto first = out.size();
		stream->append_list(now, out);
		append_monitoring_target_ids(out, first, m_monitoring_target_ids[sid]);
		append_stream_display_name(out, first, m_stream_display_names[sid]);
	}
	return 0;
}

int streams::parse_row(tsv::ctx &c, const tsv::row_t &row, info &i) {
	tsv::to_number(row[c.i.com.time_epoch], i.time_epoch);
	tsv::to_number(row[c.i.com.interface_id], i.interface_id);
	tsv::to_string(row[c.i.com.interface_name], i.interface_name);
	i.frame_len = c.r.com.frame_len;
	tsv::to_number(row[c.i.com.frame_len], i.frame_len);
	i.vlan = tsv::vlan_info{
		.id = std::string(tsv::field_or_empty(row, c.i.com.vlan_id)),
		.priority = std::string(tsv::field_or_empty(row, c.i.com.vlan_priority)),
		.dei = std::string(tsv::field_or_empty(row, c.i.com.vlan_dei)),
	};

	parse_ip(tsv::field_or_empty(row, c.i.com.ip_src), tsv::field_or_empty(row, c.i.com.ipv6_src), i.src.addr);
	parse_ip(tsv::field_or_empty(row, c.i.com.ip_dst), tsv::field_or_empty(row, c.i.com.ipv6_dst), i.dst.addr);
	std::uint32_t port = 0;
	if(tsv::to_number(tsv::field_or_empty(row, c.i.com.tcp_srcport), port) && port <= 65535U) {
		i.src.port = static_cast<std::uint16_t>(port);
	}
	port = 0;
	if(tsv::to_number(tsv::field_or_empty(row, c.i.com.tcp_dstport), port) && port <= 65535U) {
		i.dst.port = static_cast<std::uint16_t>(port);
	}
	if(tsv::to_number(tsv::field_or_empty(row, c.i.com.tcp_stream), i.tcp_stream)) {
		i.has_tcp_stream = true;
	}
	if(tsv::to_number(tsv::field_or_empty(row, c.i.com.tcp_len), i.tcp_len) && i.tcp_len > 0) {
		i.has_tcp_payload = true;
		i.payload_seen = true;
	}
	std::uint32_t tcp_fin = 0;
	i.tcp_fin =
		tsv::to_number(tsv::field_or_empty(row, c.i.com.tcp_flags_fin), tcp_fin) &&
		tcp_fin != 0;

	i.method = std::string(tsv::field_or_empty(row, c.i.http.method));
	i.path = std::string(tsv::field_or_empty(row, c.i.http.uri));
	i.host = std::string(tsv::field_or_empty(row, c.i.http.host));
	i.is_request = !i.method.empty() && !i.path.empty();

	std::uint32_t status = 0;
	if(tsv::to_number(tsv::field_or_empty(row, c.i.http.status_code), status) && status <= 999U) {
		i.status_code = static_cast<std::uint16_t>(status);
		i.is_response = i.status_code > 0;
		if(i.is_response) {
			i.effective_status_code = i.status_code;
			i.status_source = "http_header";
		}
	}

	std::uint64_t len = 0;
	if(tsv::to_number(tsv::field_or_empty(row, c.i.http.content_length), len)) {
		i.http_content_length = len;
		i.has_http_content_length = true;
		if(i.is_response) {
			i.content_length = len;
			i.has_content_length = true;
		}
	}
	else if(i.has_tcp_payload) {
		i.content_length = i.tcp_len;
		i.has_content_length = true;
	}

	if(!i.is_request && !i.is_response && !i.has_tcp_payload && !i.tcp_fin) {
		return -1;
	}
	if(i.is_response || (!i.is_request && (i.has_tcp_payload || i.tcp_fin))) {
		return 0;
	}

	i.port = endpoint_port(i.dst, 80);
	parse_absolute_uri(i.host, i.port, i.path);
	if(i.host.empty()) {
		i.host = to_string(i.dst.addr);
	}
	split_host_port(i.host, i.port);
	i.role = classify_role(i.path);
	return 0;
}

void streams::expire_streams(double now) {
	for(auto it = m_streams.begin(); it != m_streams.end(); ) {
		it->second->expire_flows(now, m_cfg.timeout.flow_idle_sec);
		if(it->second->empty() && it->second->expired(now, m_cfg.timeout.stream_idle_sec)) {
			it->second->emit_lost(now);
			m_monitoring_target_ids.erase(it->first);
			m_stream_display_names.erase(it->first);
			it = m_streams.erase(it);
