int flow::update_events(double now) {
	const auto update = m_error_state.update(now, m_error_window);
	if(update.occurred) {
		m_events.emit(make_event(now, m_fid.role + "_error_occurred", json{
			{"role", m_fid.role},
			{"window_count", update.window_count},
			{"endpoint", { {"host", m_fid.host}, {"port", m_fid.port} }},
			{"last_path", m_last_path},
			{"last_status_code", m_last_status_code},
			{"last_effective_status_code", m_last_effective_status_code},
			{"last_status_source", m_last_status_source},
			{"last_inferred_success", m_last_inferred_success},
			{"severity", "warning"},
		}));
	}
	if(update.recovered) {
		m_events.emit(make_event(now, m_fid.role + "_error_recovered", json{
			{"role", m_fid.role},
			{"active_total", update.active_total},
			{"endpoint", { {"host", m_fid.host}, {"port", m_fid.port} }},
			{"last_path", m_last_path},
			{"severity", "info"},
		}));
	}
	m_error_window = 0;
	return 0;
}

