stream_id streams::resolve_stream_id(const info &i) const {
	std::string playlist = i.role == "playlist" ? i.path : std::string{};
	if(playlist.empty()) {
		const auto it = m_playlists_by_host.find(host_key(i.interface_id, i.host, i.port, i.vlan));
		std::size_t best_len = 0;
		if(it != m_playlists_by_host.end()) {
			for(const auto &candidate : it->second) {
				const auto dir = path_dir(candidate);
				if(!dir.empty() &&
				   i.path.rfind(dir, 0) == 0 &&
				   dir.size() > best_len) {
					playlist = candidate;
					best_len = dir.size();
				}
			}
			if(playlist.empty() && !it->second.empty()) {
				playlist = it->second.front();
			}
		}
		if(playlist.empty()) {
			playlist = unknown_playlist;
		}
	}
	return stream_id::from_playlist(i.interface_id, i.host, i.port, playlist, i.vlan);
}

bool streams::same_request(const pending_request &lhs, const pending_request &rhs) const {
	return lhs.sid == rhs.sid &&
	       lhs.fid == rhs.fid &&
	       lhs.request_time == rhs.request_time;
}

bool streams::pop_connection_pending(const std::string &conn_key, const pending_request &req) {
	auto conn = m_pending_by_connection.find(conn_key);
	if(conn == m_pending_by_connection.end() || conn->second.empty()) {
		return false;
	}
	if(!same_request(conn->second.front(), req)) {
		return false;
	}
	conn->second.pop_front();
	if(conn->second.empty()) {
		m_pending_by_connection.erase(conn);
	}
	return true;
}

void streams::erase_tcp_pending(const pending_request &req) {
	for(auto it = m_pending_by_tcp_stream.begin(); it != m_pending_by_tcp_stream.end(); ) {
		if(same_request(it->second, req)) {
			it = m_pending_by_tcp_stream.erase(it);
		}
		else {
			++it;
		}
	}
}

int streams::process_resolved(const stream_id &sid, const flow_id &fid, const info &i) {
	auto it = m_streams.find(sid);
	if(it == m_streams.end()) {
		it = m_streams.emplace(sid, std::make_unique<stream>(sid, i.interface_name, m_cfg, m_events)).first;
		it->second->emit_detected(i.time_epoch);
	}

	const int rc = it->second->process(i);
	expire_streams(i.time_epoch);
	return rc;
}

void streams::remember_connection_activity(const std::string &conn_key, const stream_id &sid, const flow_id &fid) {
	auto &targets = m_activity_by_connection[conn_key];
	const auto exists = std::find_if(targets.begin(), targets.end(), [&](const activity_target &target) {
		return target.sid == sid && target.fid == fid;
	});
	if(exists == targets.end()) {
		targets.push_back(activity_target{sid, fid});
	}
}

int streams::observe_connection_payload(const std::string &conn_key, const info &i) {
	const auto it = m_activity_by_connection.find(conn_key);
	if(it == m_activity_by_connection.end()) {
		return 0;
	}

	int rc = 0;
	for(const auto &target : it->second) {
		auto stream_it = m_streams.find(target.sid);
		if(stream_it == m_streams.end()) {
			stream_it = m_streams.emplace(target.sid, std::make_unique<stream>(target.sid, i.interface_name, m_cfg, m_events)).first;
			stream_it->second->emit_detected(i.time_epoch);
		}
		rc |= stream_it->second->observe_transport(target.fid, i);
	}
	expire_streams(i.time_epoch);
	return rc;
}

int streams::process_response(info i, const pending_request &req, const char *matched_by, std::size_t conn_pending, const std::string &conn_key) {
	i.host = req.fid.host;
	i.port = req.fid.port;
	i.path = req.fid.path;
	i.role = req.fid.role;
	i.is_response = true;
	i.request_time = req.request_time;
	i.has_request_time = true;
	i.payload_seen = i.payload_seen || i.has_tcp_payload;
	if(i.status_source == "timeout") {
		i.status_code = i.status_code == 0 ? 504 : i.status_code;
		i.effective_status_code = i.status_code;
		i.inferred_success = false;
	}
	else if(i.status_code > 0) {
		i.effective_status_code = i.status_code;
		i.inferred_success = false;
		i.status_source = "http_header";
	}
	else if((i.role == "playlist" || i.role == "segment" || i.role == "key") &&
	        i.payload_seen) {
		i.effective_status_code = 200;
		i.inferred_success = true;
		if(i.status_source == "none" || i.status_source.empty()) {
			i.status_source = "payload_fallback";
		}
	}
	else {
		i.effective_status_code = 0;
		i.inferred_success = false;
		i.status_source = i.payload_seen ? "payload_fallback" : "unknown";
	}
	trace(3, "hls: response matched by=%s status=%u effective_status=%u source=%s inferred=%d tcp_payload=%d tcp_len=%u bytes=%llu role=%s path=%s conn=%s conn_pending_before=%zu response_time=%.6f",
	      matched_by,
	      static_cast<unsigned>(i.status_code),
	      static_cast<unsigned>(i.effective_status_code),
	      i.status_source.c_str(),
	      i.inferred_success ? 1 : 0,
	      i.has_tcp_payload ? 1 : 0,
	      static_cast<unsigned>(i.tcp_len),
	      static_cast<unsigned long long>(i.content_length),
	      i.role.c_str(),
	      i.path.c_str(),
	      conn_key.c_str(),
	      conn_pending,
	      i.time_epoch >= i.request_time ? (i.time_epoch - i.request_time) : -1.0);
	return process_resolved(req.sid, req.fid, i);
}

