    monitoringTargetIds: stringArray(raw.monitoring_target_ids),
    protocolDetails: protocolDetailsForFlow(proto, raw),
    metrics: {}
  };
}

function alertSummary(value: unknown): import("./types").StreamAlertSummary | undefined {
  const entries = value && typeof value === "object" && !Array.isArray(value) ? Object.values(value as AnyRecord).filter(isRecord) : [];
function recentAlertSummary(value: unknown) {
  return alertSummary(value);
}

function severityRank(value: string) { return value === "critical" ? 3 : value === "error" ? 2 : 1; }
function normalizeAlertSeverity(value: string): "warning" | "error" | "critical" { return value === "critical" || value === "error" ? value : "warning"; }

function stringValue(value: unknown) {
  return typeof value === "string" && value.length > 0 ? value : undefined;
}

function endpointSource(endpoint: unknown) {
  return stringValue(isRecord(endpoint) ? endpoint.src : undefined);
}

function endpointDestination(endpoint: unknown) {
  if (!isRecord(endpoint)) return undefined;
  const observed = stringValue(endpoint.dst) ?? stringValue(endpoint.b);
  const host = stringValue(endpoint.host);
  const port = Number(endpoint.port);
  if (!host) return observed;
  const authorityHost = host.includes(":") && !host.startsWith("[") ? `[]` : host;
  const authority = Number.isInteger(port) && port > 0 && port <= 65535 ? `:` : authorityHost;
  return observed && observed !== authority ? ` ()` : authority;
}

function flowLabel(role: string, endpointSrc: string | undefined, endpointDst: string | undefined) {
  if (endpointSrc && endpointDst) return `:  → `;
  if (endpointDst) return `: `;
  if (endpointSrc) return `: `;
  return role;
}

function protocolDetailsForStream(proto: string, raw: AnyRecord, streamKey: string) {
  if (proto === "SRT") {
    const streamId = srtResourceId(stringValue(raw.streamid) ?? endpointFromKey(streamKey, "streamid"));
    return streamId ? [{ label: "SID", value: streamId }] : undefined;
  }
  if (proto === "HLS") {
    const playlist = safeIdentifier(stringValue(raw.endpoint?.playlist), 48);
    return playlist && playlist !== "<unknown>" ? [{ label: "playlist", value: playlist }] : undefined;
  }
  if (proto === "OTHER") {
    const transport = stringValue(raw.transport);
    const delivery = stringValue(raw.delivery);
    return transport || delivery ? [{ value: [transport, delivery].filter(Boolean).join(" · ") }] : undefined;
  }
  return undefined;
}

function protocolDetailsForFlow(proto: string, flow: AnyRecord) {
  if (proto !== "RTP") return undefined;
  const details: Array<{ label: string; value: string }> = [];
  const flowKey = String(flow.flow_key ?? "");
  const ssrc = Number(flow.ssrc ?? endpointFromKey(flowKey, "ssrc"));
  if (Number.isInteger(ssrc) && ssrc >= 0 && ssrc <= 0xffffffff) {
    details.push({ label: "SSRC", value: "0x" + ssrc.toString(16).toUpperCase().padStart(8, "0") });
  }
  const payloadType = Number(flow.payload_type ?? endpointFromKey(flowKey, "pt") ?? endpointFromKey(flowKey, "payload_type"));
  if (Number.isInteger(payloadType) && payloadType >= 0 && payloadType <= 127) {
    details.push({ label: "PT", value: String(payloadType) });
  }
  return details.length > 0 ? details : undefined;
}

function srtResourceId(value: string | undefined) {
  if (!isRecord(value)) return undefined;
  const id = scopeText(value.id);
  const priority = scopeText(value.priority);
  const dei = scopeText(value.dei);
  if (!id && !priority && !dei) return undefined;
  return { kind: "vlan", id, priority, dei };
}

function normalizeVxlanLayer(value: unknown): Extract<ScopeLayer, { kind: "vxlan" }> | undefined {
  if (!isRecord(value)) return undefined;
  const vni = scopeText(value.vni);
  return vni ? { kind: "vxlan", vni } : undefined;
}

function unknownScope(interfaceId?: number, interfaceName?: string): NetworkScope {
  return { interfaceId, interfaceName, known: false, layers: [] };
}

function isRecord(value: unknown): value is AnyRecord {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function scopeText(value: unknown) {
  return typeof value === "string" || typeof value === "number" ? String(value) : undefined;
}

function timelineLabel(proto: string, endpoint: AnyRecord | undefined, streamKey: string) {
  const sessionDst = typeof endpoint?.session_dst === "string" ? endpoint.session_dst : undefined;
  if (proto === "RTP" && sessionDst) return `${proto} ${sessionDst}`;

  const service = typeof endpoint?.service === "string" ? endpoint.service : undefined;
