import type { FlowListItem, StreamAlertSummary, StreamListItem } from "../types/api";
import { formatFlowEndpoints } from "./format";

export type AlertSeverity = "warning" | "error" | "critical";
export type AlertCounts = { active: number; recent: number; severity: AlertSeverity | null };
export type AlertTarget = {
  key: string;
  streamKey: string;
  flowKey?: string;
  type: "stream" | "flow";
}

function durationScale(unit: string | undefined, magnitude: number): MetricDisplayScale {
  const sourceSeconds = unit === "ms" ? 1e-3 : unit === "us" || unit === "µs" ? 1e-6 : unit === "ns" ? 1e-9 : 1;
  const magnitudeSeconds = magnitude * sourceSeconds;
  const target = magnitudeSeconds >= 1 ? { seconds: 1, unit: "s" } : magnitudeSeconds >= 1e-3 ? { seconds: 1e-3, unit: "ms" } : magnitudeSeconds >= 1e-6 ? { seconds: 1e-6, unit: "µs" } : { seconds: 1e-9, unit: "ns" };
  return { kind: "duration", divisor: target.seconds / sourceSeconds, unit: target.unit, prefix: "", includeZero: false };
}

export function formatBitrate(value?: number) {
  if (value === undefined || !Number.isFinite(value)) return "-";
  const units = ["bps", "Kbps", "Mbps", "Gbps"];
  let current = value;
  let unit = 0;
  while (current >= 1000 && unit < units.length - 1) {
    current /= 1000;
    unit += 1;
  }
  return `${current >= 100 ? current.toFixed(0) : current.toFixed(1)} ${units[unit]}`;
}

export function formatFlowEndpoints(endpointSrc?: string, endpointDst?: string, fallback = "Unknown endpoint") {
  if (endpointSrc && endpointDst) return endpointSrc + " → " + endpointDst;
  return endpointDst ?? endpointSrc ?? fallback;
}

export function formatNumber(value?: number) {
  if (value === undefined || !Number.isFinite(value)) return "-";
  if (Math.abs(value) >= 1000) return value.toLocaleString(activeLocale, { maximumFractionDigits: 1 });
  const fixed = value.toFixed(3).replace(/0+(?![\s\S])/, "");
  return fixed.replace(/[.](?![\s\S])/, "");
  if (!isRecord(value)) return undefined;
  const id = scopeText(value.id);
  const priority = scopeText(value.priority);
  const dei = scopeText(value.dei);
  if (!id && !priority && !dei) return undefined;
  return { kind: "vlan", id, priority, dei };
}

function normalizeVxlanLayer(value: unknown): Extract<ScopeLayer, { kind: "vxlan" }> | undefined {
  if (!isRecord(value)) return undefined;
  const vni = scopeText(value.vni);
  return vni ? { kind: "vxlan", vni } : undefined;
}

function unknownScope(interfaceId?: number, interfaceName?: string): NetworkScope {
  return { interfaceId, interfaceName, known: false, layers: [] };
}

function isRecord(value: unknown): value is AnyRecord {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function scopeText(value: unknown) {
  return typeof value === "string" || typeof value === "number" ? String(value) : undefined;
}

function timelineLabel(proto: string, endpoint: AnyRecord | undefined, streamKey: string) {
  const sessionDst = typeof endpoint?.session_dst === "string" ? endpoint.session_dst : undefined;
  if (proto === "RTP" && sessionDst) return `${proto} ${sessionDst}`;

  const service = typeof endpoint?.service === "string" ? endpoint.service : undefined;

