#define PROTOCOL_DISPATCH_ADAPTER_H

#include <memory>
#include <string>

#include "packet_context.h"
#include "tsv.h"

class protocol_map;
namespace other { class streams; }

struct dispatch_adapter_context {
	const protocol_map &protocols;
	other::streams &other_fallback;
};

struct protocol_dispatch_decision {
	std::string tracking_key;
	bool matched{false};
	bool tracked{false};
	bool observe_stream{false};
	bool suppress_other{false};
};

class protocol_dispatch_adapter {
public:
	virtual ~protocol_dispatch_adapter() = default;

	virtual protocol_dispatch_decision prepare(const packet_context &packet) = 0;
	virtual void after_stream_dispatch(tsv::ctx &tc,
	                                   const tsv::row_t &row,
	                                   const packet_context &packet,
	                                   const protocol_dispatch_decision &decision,
	                                   bool dispatched_to_stream) = 0;
	virtual void after_packet(tsv::ctx &tc,
	                          const tsv::row_t &row,
	                          const packet_context &packet,
	                          const protocol_dispatch_decision &decision) = 0;
	virtual void prune(double now) = 0;
};

#endif /* PROTOCOL_DISPATCH_ADAPTER_H */
#include "stream_registry.h"

#include <utility>

#include "event.h"

stream_registry::protocol_configs stream_registry::make_protocol_configs(const protocol_map &protocols) {
	protocol_configs cfg{};
	cfg.rtp.fec_base_endpoints = protocols.rtp_fec_base_endpoints();
	return cfg;
}

stream_registry::stream_registry(const protocol_map &protocols, event_sink &events)
	: m_protocols(protocols) {
	auto cfg = make_protocol_configs(protocols);

	m_srt = std::make_unique<srt::streams>(cfg.srt, events);
	m_rtp = std::make_unique<rtp::streams>(cfg.rtp, events);
	m_rtmp = std::make_unique<rtmp::streams>(cfg.rtmp, events);
	m_hls = std::make_unique<hls::streams>(cfg.hls, events);
	m_other = std::make_unique<other::streams>(cfg.other, events);

	m_all_streams = { m_srt.get(), m_rtp.get(), m_rtmp.get(), m_hls.get(), m_other.get() };
	// Preserve the existing monitor output order. RTMP dispatch exists, but metrics/list output was not emitted before this refactor.
	m_output_streams = { m_srt.get(), m_rtp.get(), m_hls.get(), m_other.get() };

	dispatch_adapter_context dispatch_ctx{
		.protocols = m_protocols,
		.other_fallback = *m_other,
	};
	for(auto *stream : m_all_streams) {
		register_stream(*stream);
		if(auto adapter = stream->make_dispatch_adapter(dispatch_ctx)) {
			m_dispatch_adapters.emplace_back(std::move(adapter));
		}
	}
}

void stream_registry::register_stream(::streams &stream) {
	for(auto proto : stream.dispatch_protocols()) {
		m_dispatcher.emplace(proto, &stream);
	}
}

::streams* stream_registry::dispatch_target(std::string_view proto) const {
	const auto it = m_dispatcher.find(proto);
	if(it == m_dispatcher.end()) {
		return nullptr;
	}
	return it->second;
}

int stream_registry::process_packet(tsv::ctx &tc, const tsv::row_t &row, const packet_context &packet) {
	std::vector<protocol_dispatch_decision> dispatch_decisions;
	dispatch_decisions.reserve(m_dispatch_adapters.size());
	bool adapter_observe_stream = false;
	bool adapter_suppress_other = false;
	for(auto &adapter : m_dispatch_adapters) {
		auto decision = adapter->prepare(packet);
		adapter_observe_stream = adapter_observe_stream || decision.observe_stream;
		adapter_suppress_other = adapter_suppress_other || decision.suppress_other;
		dispatch_decisions.emplace_back(std::move(decision));
	}

	bool dispatched_to_stream = false;
	const bool observe_stream =
		m_protocols.should_observe(packet.dispatch_proto, packet.src, packet.dst, packet.vlan, packet.host) ||
		adapter_observe_stream;
	if(observe_stream) {
		if(auto *target = dispatch_target(packet.dispatch_proto)) {
			const auto target_ids = m_protocols.matching_target_ids(packet.dispatch_proto, packet.src, packet.dst, packet.vlan, packet.host);
			target->process(tc, row, target_ids, m_protocols.stream_display_name(target_ids));
			dispatched_to_stream = true;
		}
		else if(!adapter_suppress_other) {
			m_other->process(tc, row);
		}
	}

	for(std::size_t i = 0; i < m_dispatch_adapters.size(); ++i) {
		m_dispatch_adapters[i]->after_stream_dispatch(tc, row, packet, dispatch_decisions[i], dispatched_to_stream);
	}
	for(std::size_t i = 0; i < m_dispatch_adapters.size(); ++i) {
		m_dispatch_adapters[i]->after_packet(tc, row, packet, dispatch_decisions[i]);
	}

	return 0;
}

void stream_registry::update_events(double now) {
	for(auto &adapter : m_dispatch_adapters) {
		adapter->prune(now);
	}
	for(auto *stream : m_output_streams) {
		stream->update_events(now);
	}
}

void stream_registry::append_metrics(double now, json::array_t &out) {
	for(auto *stream : m_output_streams) {
		stream->append_metrics(now, out);
	}
}

void stream_registry::append_list(double now, json::array_t &out) {
	for(auto *stream : m_output_streams) {
		stream->append_list(now, out);
	}
}
}

flow_id streams::reverse_flow_id(const flow_id& fid) {
	return flow_id{
		.interface_id = fid.interface_id,
		.ip_proto = fid.ip_proto,
		.src = fid.dst,
		.dst = fid.src,
		.vlan = fid.vlan,
	};
}

bool streams::should_use_reverse_match(std::uint8_t ip_proto) {
	return ip_proto == 1 || ip_proto == 58;
}

int streams::process(tsv::ctx &c, const tsv::row_t &row) { return process(c, row, {}); }

int streams::process(tsv::ctx &c, const tsv::row_t &row, const std::vector<std::string> &target_ids) { return process(c, row, target_ids, {}); }

int streams::process(tsv::ctx &c, const tsv::row_t &row, const std::vector<std::string> &target_ids, const std::string &stream_name) {
	info i;
	if(parse_row(c, row, i) != 0) {
		return -1;
	}
	return process_info(std::move(i), target_ids, stream_name);
}

int streams::process_as(tsv::ctx &c, const tsv::row_t &row, std::string_view proto_override) {
	info i;
	if(parse_row(c, row, i) != 0) {
		return -1;
	}
	i.proto = std::string(proto_override);
	return process_info(std::move(i));
}

int streams::process_info(info i, const std::vector<std::string> &target_ids, const std::string &stream_name) {
    expire_streams(i.time_epoch);

	flow_id fid = make_flow_id(i.interface_id,
	                           i.ip_proto,
	                           i.src.addr, i.src.port,
	                           i.dst.addr, i.dst.port,
	                           i.vlan);

	stream_id sid = make_stream_id(i.interface_id,
	                               i.proto,
	                               i.ip_proto,
	                               i.src.addr, i.src.port,
	                               i.dst.addr, i.dst.port,
	                               i.vlan);

	if(should_use_reverse_match(i.ip_proto)) {
		auto reverse_it = m_reverse_stream_index.find(reverse_flow_id(fid));
		if(reverse_it != m_reverse_stream_index.end()) {
			sid = reverse_it->second;
		}
	}

	merge_monitoring_target_ids(m_monitoring_target_ids[sid], target_ids);
	if(!stream_name.empty()) {
		m_stream_display_names[sid] = stream_name;
		m_events.set_stream_display_name(make_stream_key(sid), stream_name);
	}

	auto it = m_streams.find(sid);
	if(it == m_streams.end()) {
		auto s = std::make_unique<stream>(sid, i.interface_name, m_events);
		s->emit_detected(i.time_epoch);
		int rc = s->process(i);
		m_streams.emplace(sid, std::move(s));
		m_reverse_stream_index[fid] = sid;
		return rc;
	}

	m_reverse_stream_index[fid] = sid;
	return it->second->process(i);
}

int streams::append_metrics(double now, json::array_t &out) {
	for(auto& [sid, stream] : m_streams) {
		const auto first = out.size();
		stream->append_metrics(now, out);
		append_monitoring_target_ids(out, first, m_monitoring_target_ids[sid]);
		append_stream_display_name(out, first, m_stream_display_names[sid]);
	}
	return 0;
}

int streams::update_events(double now) {
	expire_streams(now);
	for(auto& [sid, stream] : m_streams) {
		stream->update_events(now);
	}
	return 0;
}

int streams::append_list(double now, json::array_t &out) {
	for(auto& [sid, stream] : m_streams) {
		const auto first = out.size();
		stream->append_list(now, out);
		append_monitoring_target_ids(out, first, m_monitoring_target_ids[sid]);
		append_stream_display_name(out, first, m_stream_display_names[sid]);
	}
	return 0;
}

int streams::parse_row(tsv::ctx &c, const tsv::row_t &row, info &i) {
	tsv::to_number(row[c.i.com.interface_id], i.interface_id);
	tsv::to_string(row[c.i.com.interface_name], i.interface_name);
	tsv::to_string(row[c.i.com.proto], i.proto);
	if(!parse_ip(tsv::field_or_empty(row, c.i.com.ip_src),
	             tsv::field_or_empty(row, c.i.com.ipv6_src),
	             i.src.addr)) {
		return -1;
	}
	if(!parse_ip(tsv::field_or_empty(row, c.i.com.ip_dst),
	             tsv::field_or_empty(row, c.i.com.ipv6_dst),
	             i.dst.addr)) {
		return -1;
	}
	if(!tsv::to_number(tsv::field_or_empty(row, c.i.com.udp_srcport), i.src.port)) {
		tsv::to_number(tsv::field_or_empty(row, c.i.com.tcp_srcport), i.src.port);
	}
	if(!tsv::to_number(tsv::field_or_empty(row, c.i.com.udp_dstport), i.dst.port)) {
		tsv::to_number(tsv::field_or_empty(row, c.i.com.tcp_dstport), i.dst.port);
	}
	tsv::to_number(i.src.addr.is_v6 ?
	               row[c.i.com.ipv6_nxt] : row[c.i.com.ip_proto], i.ip_proto);
	tsv::to_number(row[c.i.com.time_epoch], i.time_epoch);
	tsv::to_number(row[c.i.com.frame_len],  i.frame_len);
	i.vlan.id = std::string(tsv::field_or_empty(row, c.i.com.vlan_id));
	i.vlan.priority = std::string(tsv::field_or_empty(row, c.i.com.vlan_priority));
	i.vlan.dei = std::string(tsv::field_or_empty(row, c.i.com.vlan_dei));

	return 0;
}

void streams::expire_streams(double now) {
	for(auto it = m_streams.begin(); it != m_streams.end(); ) {
		it->second->expire_flows(now, m_cfg.timeout.flow_idle_sec);

		if(it->second->empty() &&
		    it->second->expired(now, m_cfg.timeout.stream_idle_sec)) {
			for(auto idx = m_reverse_stream_index.begin(); idx != m_reverse_stream_index.end(); ) {
				if(idx->second == it->first) {
					idx = m_reverse_stream_index.erase(idx);
				}
				else {
					++idx;
				}
			}
			it->second->emit_lost(now);
			m_monitoring_target_ids.erase(it->first);
			m_stream_display_names.erase(it->first);
			it = m_streams.erase(it);
		}
		else {
			++it;
		}
	}
}

}

