#include "timeline.h"

#include <cmath>
#include <cstdio>
#include <ctime>
#include <algorithm>
#include <utility>

#include "writer.h"

namespace {
std::tm utc_tm(double now) {
	std::time_t tt = static_cast<std::time_t>(std::floor(now));
	std::tm tm{};
	gmtime_r(&tt, &tm);
	return tm;
}
}

timeline_sink::timeline_sink(config cfg)
	: m_writer(cfg.live_writer)
	, m_capture_id(std::move(cfg.capture_id))
	, m_history_root(std::move(cfg.history_root))
	, m_checkpoint_root(cfg.checkpoint_root.empty()
		? m_history_root / "checkpoint" : std::move(cfg.checkpoint_root)) {
	if(!m_history_root.empty()) {
		std::filesystem::create_directories(m_history_root);
		std::filesystem::create_directories(m_checkpoint_root);
	}
}

int timeline_sink::emit(const timeline_record &e) {
	update_active_rows(e);

	json j{
		{"capture_id", m_capture_id},
		{"seq", m_seq++},
		{"time", e.time_epoch},
		{"kind", e.kind},
		{"source", "pcap"},
		{"subject", e.subject},
	};

	if(e.detail.is_null() == false && e.detail.empty() == false) {
		j["detail"] = e.detail;
	}

	ensure_history_open(e.time_epoch);
	write_history_line(j);
	emit_checkpoint_if_needed(e.time_epoch);
	return m_writer.dump(j);
}

int timeline_sink::emit(double time_epoch, std::string kind, json subject, json detail) {
	return emit(timeline_record{
		.time_epoch = time_epoch,
		.kind = std::move(kind),
		.subject = std::move(subject),
		.detail = std::move(detail),
	});
}

timeline_sink::hourly_slot timeline_sink::slot_for(double now) {
	auto tm = utc_tm(now);
	return hourly_slot{
		.year = tm.tm_year + 1900,
		.month = tm.tm_mon + 1,
		.day = tm.tm_mday,
		.hour = tm.tm_hour,
	};
}

timeline_sink::minute_slot timeline_sink::minute_slot_for(double now) {
	auto tm = utc_tm(now);
	return minute_slot{
		.year = tm.tm_year + 1900,
		.month = tm.tm_mon + 1,
		.day = tm.tm_mday,
		.hour = tm.tm_hour,
		.minute = tm.tm_min,
	};
}

std::filesystem::path timeline_sink::build_history_path(const std::filesystem::path &root, const hourly_slot &slot) {
	char day[16];
	char hour[16];
	std::snprintf(day, sizeof(day), "%04d%02d%02d", slot.year, slot.month, slot.day);
	std::snprintf(hour, sizeof(hour), "%02d.ndjson", slot.hour);
	return root / day / hour;
}

std::filesystem::path timeline_sink::build_checkpoint_path(const std::filesystem::path &root, const minute_slot &slot) {
	char day[16];
	char minute_file[32];
	std::snprintf(day, sizeof(day), "%04d%02d%02d", slot.year, slot.month, slot.day);
	std::snprintf(minute_file, sizeof(minute_file), "%02d%02d.json", slot.hour, slot.minute);
	return root / day / minute_file;
}

void timeline_sink::ensure_history_open(double now) {
	if(m_history_root.empty()) {
		return;
	}

	const auto slot = slot_for(now);
	if(m_history_file.stream.is_open() && m_history_file.slot == slot) {
		return;
	}

	if(m_history_file.stream.is_open()) {
		m_history_file.stream.flush();
		m_history_file.stream.close();
	}

	m_history_file.slot = slot;
	m_history_file.path = build_history_path(m_history_root, slot);
	std::filesystem::create_directories(m_history_file.path.parent_path());
	m_history_file.stream.open(m_history_file.path, std::ios::app);
}

void timeline_sink::write_history_line(const json &line) {
	if(!m_history_file.stream.is_open()) {
		return;
	}

	m_history_file.stream << line.dump() << '\n';
	m_history_file.stream.flush();
}

void timeline_sink::update_active_rows(const timeline_record &e) {
	const auto kind = e.kind;
	const bool is_detect =
		kind == "stream_detected" || kind == "stream_recovered" ||
		kind == "flow_detected" || kind == "flow_recovered";
	const bool is_lost = kind == "stream_lost" || kind == "flow_lost";
	if(!is_detect && !is_lost) {
		return;
	}

	if(!e.subject.is_object()) {
		return;
	}

	const std::string subject_type = e.subject.value("type", "");
	const std::string stream_key = e.subject.value("stream_key", "");
	if(stream_key.empty()) {
		return;
	}

	std::string key = stream_key;
	if(subject_type == "flow") {
		const std::string flow_key = e.subject.value("flow_key", "");
		if(flow_key.empty()) {
			return;
		}
		key += "::" + flow_key;
	}

	if(is_lost) {
		m_active_rows.erase(key);
		return;
	}

	auto it = m_active_rows.find(key);
	if(it == m_active_rows.end()) {
		timeline_row_state created{};
		created.first_seen = e.time_epoch;
		created.last_seen = e.time_epoch;
		created.row = json{
			{"key", key},
			{"type", subject_type},
			{"stream_key", stream_key},
			{"flow_key", e.subject.value("flow_key", "")},
			{"parent_stream_key", subject_type == "flow" ? stream_key : ""},
			{"proto", e.subject.value("proto", "")},
			{"interface_id", e.subject.contains("interface_id") ? e.subject["interface_id"] : json(nullptr)},
			{"label", e.subject.value("label", "")},
			{"role", e.subject.value("role", "")},
			{"subject", e.subject},
		};
		m_active_rows.emplace(key, std::move(created));
		return;
	}

	it->second.last_seen = e.time_epoch;
	auto &row = it->second.row;
	row["proto"] = e.subject.value("proto", row.value("proto", ""));
	if(e.subject.contains("interface_id")) {
		row["interface_id"] = e.subject["interface_id"];
	}
	if(e.subject.contains("label")) {
		row["label"] = e.subject["label"];
	}
	if(e.subject.contains("role")) {
		row["role"] = e.subject["role"];
	}
	row["subject"] = e.subject;
}

void timeline_sink::emit_checkpoint_if_needed(double now) {
	if(m_checkpoint_root.empty()) {
		return;
	}

	const auto slot = minute_slot_for(now);
	if(!m_has_checkpoint_slot) {
		m_last_checkpoint_slot = slot;
		m_has_checkpoint_slot = true;
		return;
	}

	if(slot == m_last_checkpoint_slot) {
		return;
	}

	write_checkpoint(m_last_checkpoint_slot, now);
	m_last_checkpoint_slot = slot;
}

void timeline_sink::write_checkpoint(const minute_slot &slot, double now) {
	json rows = json::array();
	std::vector<const timeline_row_state*> ordered;
	ordered.reserve(m_active_rows.size());
	for(const auto &kv : m_active_rows) {
		ordered.push_back(&kv.second);
	}
	std::sort(ordered.begin(), ordered.end(), [](const timeline_row_state *a, const timeline_row_state *b) {
		return a->row.value("key", "") < b->row.value("key", "");
	});

	for(const auto *state : ordered) {
		json item = state->row;
		item["first_seen"] = state->first_seen;
		item["last_seen"] = state->last_seen;
		rows.push_back(std::move(item));
	}

	json doc{
		{"capture_id", m_capture_id},
		{"time", now},
		{"slot", json{
			{"year", slot.year},
			{"month", slot.month},
			{"day", slot.day},
			{"hour", slot.hour},
			{"minute", slot.minute},
		}},
		{"active_rows", std::move(rows)},
	};

	const auto path = build_checkpoint_path(m_checkpoint_root, slot);
	std::filesystem::create_directories(path.parent_path());
	std::ofstream ofs(path, std::ios::trunc);
	if(!ofs.is_open()) {
		return;
	}
	ofs << doc.dump() << '\n';
	ofs.flush();
	return 0;
}

void stm_projector::mark_topology_dirty(double time, const json &source) {
	m_topology_dirty = true;
	if(time >= m_pending_topology_time) {
		m_pending_topology_time = time;
		m_pending_topology_source = json{{"record_id", source.value("record_id", std::string{})}};
	}
}

bool stm_projector::flush_topology_if_due() {
	if(!m_topology_dirty) return false;
	const auto now = std::chrono::steady_clock::now();
	if(m_last_topology_publish.time_since_epoch().count() != 0 &&
	   now - m_last_topology_publish < m_cfg.topology_publish_interval) {
		return false;
	}
	const auto started_at = now;
	write_topology(m_pending_topology_time, m_pending_topology_source);
	m_topology_dirty = false;
	m_pending_topology_time = 0.0;
	m_pending_topology_source = json::object();
	m_last_topology_publish = std::chrono::steady_clock::now();
	const auto elapsed_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
		m_last_topology_publish - started_at).count();
	trace(2, "projector: topology publish elapsed_ms=%lld", static_cast<long long>(elapsed_ms));
	return true;
}

void stm_projector::write_topology(double time, const json &source_record) {
	if(!m_topology_writer || !m_topology_projector || !m_stream_state) return;
	json::array_t alerts;
	for(const auto &[_, alert] : m_active_alerts.items()) alerts.push_back(alert);
	const auto streams = m_stream_state->snapshot(time).value("streams", json::array_t{});
	const auto topology = m_topology_projector->build(time, streams, m_current_interfaces, m_current_metrics, alerts);
	m_topology_writer->dump(topology);
	if(m_topology_state) {
		json source{
			{"record_id", source_record.value("record_id", std::string{})},
			{"event_record_id", m_last_event_record_id},
			{"metrics_record_id", m_last_metrics_record_id},
		};
		m_topology_state->publish(time, topology, source);
	}
}

void stm_projector::write_topology_event(const json &event) {
	if(!m_topology_events_writer) return;
	const std::string type = event.value("type", std::string{});
	if(type != "flow_detected" && type != "flow_lost" && type != "flow_recovered") return;
	const auto source = event.value("source", json::object());
	json record{
		{"schema_version", 2},
		{"record_type", "topology_event"},
		{"record_id", event.value("record_id", std::string{}) + ":topology"},
		{"source_record_id", event.value("record_id", std::string{})},
		{"capture_id", event.value("capture_id", std::string{})},
		{"time", event.value("event_time", event.value("time", 0.0))},
		{"type", type == "flow_lost" ? "edge_lost" : (type == "flow_recovered" ? "edge_recovered" : "edge_detected")},
		{"identity", {
			{"stream_key", source.value("stream_key", std::string{})},
			{"flow_key", source.value("flow_key", std::string{})},
		}},
		{"proto", source.value("proto", std::string{})},
		{"scope", source.value("scope", json::object())},
		{"endpoint", event.value("detail", json::object()).value("endpoint", json::object())},
	};
	m_topology_events_writer->dump_at(record["time"].get<double>(), record);
}

