#include "stream_state_projector.h"

#include <algorithm>
#include <cmath>
#include <cstdio>
#include <ctime>
#include <fstream>
#include <map>
#include <utility>
#include <vector>

namespace {
bool lifecycle_type(const std::string &type, const char *subject) {
	return type == std::string(subject) + "_detected" ||
	       type == std::string(subject) + "_recovered" ||
	       type == std::string(subject) + "_lost";
}

bool is_detect(const std::string &type) {
	return type.ends_with("_detected") || type.ends_with("_recovered");
}

bool flow_state_update_type(const std::string &type) {
	return type == "flow_role_updated";
}

bool alert_state_update_type(const std::string &type) {
	return type == "alert_detected" || type == "alert_recovered" || type == "alert_data_unavailable" || type == "alert_data_available";
}

void update_alert_state(json &subject, const json &source, const json &detail, const std::string &type, double time) {
	json alert = source;
	if(detail.is_object()) {
		for(const auto &[key, value] : detail.items()) alert[key] = value;
	}
	const auto key = alert.value("state_key", alert.value("alert_id", std::string{}));
	if(key.empty()) return;
	alert["state_key"] = key;
	auto &active = subject["alerts"];
	if(!active.is_object()) active = json::object();
	auto &recent = subject["recent_alerts"];
	if(!recent.is_object()) recent = json::object();
	if(type == "alert_detected" || type == "alert_data_unavailable") {
		if(active.contains(key) && active[key].is_object() && active[key].contains("started_at")) alert["started_at"] = active[key]["started_at"];
		else alert["started_at"] = time;
		alert["state"] = "active";
		alert["updated_at"] = time;
		active[key] = std::move(alert);
		recent.erase(key);
	}
	else {
		if(active.contains(key) && active[key].is_object() && active[key].contains("started_at")) alert["started_at"] = active[key]["started_at"];
		else alert["started_at"] = time;
		alert["state"] = "recovered";
		alert["recovered_at"] = time;
		alert["updated_at"] = time;
		recent[key] = std::move(alert);
		active.erase(key);
	}
}

bool is_active(const json &value) {
	return value.is_object() && value.contains("active") &&
	       value["active"].is_boolean() && value["active"].get<bool>();
}

std::filesystem::path checkpoint_path(const std::filesystem::path &root, double time) {
	const auto seconds = static_cast<std::time_t>(std::floor(time));
	std::tm tm{};
	gmtime_r(&seconds, &tm);
	char day[16];
	char file[16];
	std::snprintf(day, sizeof(day), "%04d%02d%02d", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday);
	std::snprintf(file, sizeof(file), "%02d%02d.json", tm.tm_hour, tm.tm_min);
	return root / "checkpoint" / day / file;
}

void merge_source(json &target, const json &source) {
	for(const auto &key : {"name", "proto", "interface_id", "scope", "vlan"}) {
		if(source.contains(key)) target[key] = source[key];
	}
}
}

stream_state_projector::stream_state_projector(config cfg)
	: m_cfg(std::move(cfg)) {
	std::filesystem::create_directories(m_cfg.root_dir / "checkpoint");
	m_delta_writer = std::make_unique<time_rotating_writer>("STM_PROJECTOR_STREAM_STATE",
	                                                       m_cfg.root_dir / "delta",
	                                                       m_cfg.part_size_bytes,
	                                                       m_cfg.retention_hours);
}

bool stream_state_projector::apply_event(const json &event) {
	if(!event.is_object()) return false;
	const std::string type = event.value("type", std::string{});
	const json source = event.value("source", json::object());
	const json detail = event.value("detail", json::object());
	const double time = event.value("event_time", event.value("time", 0.0));
	if(!source.is_object() || time <= 0.0) return false;
	const std::string stream_key = source.value("stream_key", std::string{});
	if(stream_key.empty()) return false;

	const bool stream_event = lifecycle_type(type, "stream");
	const bool flow_event = lifecycle_type(type, "flow");
	const bool flow_state_update = flow_state_update_type(type);
	const bool alert_state_update = alert_state_update_type(type);
	if(!stream_event && !flow_event && !flow_state_update && !alert_state_update) return false;

	auto &stream = m_streams[stream_key];
	if(!stream.is_object()) {
		stream = json{{"stream_key", stream_key}, {"flows", json::object()}, {"first_seen", time}};
	}
	if(alert_state_update) {
		const std::string flow_key = source.value("flow_key", std::string{});
		if(flow_key.empty()) {
			update_alert_state(stream, source, detail, type, time);
		}
		else {
			auto &flow = stream["flows"][flow_key];
			if(!flow.is_object()) flow = json{{"flow_key", flow_key}, {"first_seen", time}};
			merge_source(flow, source);
			update_alert_state(flow, source, detail, type, time);
		}
		write_delta(event, "alert");
		checkpoint_if_needed(time);
		return true;
	}

	merge_source(stream, source);
	stream["last_seen"] = time;
	if(detail.contains("endpoint")) stream["endpoint"] = detail["endpoint"];
	if(stream_event) {
		stream["active"] = is_detect(type);
		if(!stream.contains("first_seen")) stream["first_seen"] = time;
		if(type == "stream_lost") {
			for(auto &[_, flow] : stream["flows"].items()) {
				flow["active"] = false;
				flow["last_seen"] = time;
			}
		}
		write_delta(event, is_detect(type) ? "upsert" : "lost");
		checkpoint_if_needed(time);
		return true;
	}

	const std::string flow_key = source.value("flow_key", std::string{});
	if(flow_key.empty()) return false;
	auto &flow = stream["flows"][flow_key];
	if(!flow.is_object()) {
		flow = json{{"flow_key", flow_key}, {"first_seen", time}};
	}
	merge_source(flow, source);
	flow["last_seen"] = time;
	if(detail.contains("endpoint")) flow["endpoint"] = detail["endpoint"];
	if(detail.contains("role")) flow["role"] = detail["role"];
	if(flow_event) {
		flow["active"] = is_detect(type);
		if(is_detect(type)) stream["active"] = true;
	}
	if(!stream.contains("first_seen")) stream["first_seen"] = time;
	write_delta(event, flow_event && !is_detect(type) ? "lost" : "upsert");
	checkpoint_if_needed(time);
	return true;
}

json stream_state_projector::snapshot(double time) const {
	json::array_t entries;
	std::vector<std::string> stream_keys;
	for(const auto &[key, value] : m_streams.items()) {
		if(is_active(value)) stream_keys.push_back(key);
	}
	std::sort(stream_keys.begin(), stream_keys.end());
	for(const auto &key : stream_keys) {
		const auto &source = m_streams.at(key);
		json stream = json::object();
		for(const auto &field : {"stream_key", "name", "interface_id", "scope", "vlan", "endpoint", "first_seen", "last_seen", "alerts", "recent_alerts"}) {
			if(source.contains(field)) stream[field] = source[field];
		}
		json::array_t flows;
		std::vector<std::string> flow_keys;
		const json flow_objects = source.contains("flows") && source["flows"].is_object()
			? source["flows"] : json::object();
		for(const auto &[flow_key, flow] : flow_objects.items()) {
			if(is_active(flow)) flow_keys.push_back(flow_key);
		}
		std::sort(flow_keys.begin(), flow_keys.end());
		for(const auto &flow_key : flow_keys) {
			const auto &source_flow = source["flows"].at(flow_key);
			json flow = json::object();
			for(const auto &field : {"flow_key", "interface_id", "scope", "vlan", "endpoint", "role", "first_seen", "last_seen", "alerts", "recent_alerts"}) {
				if(source_flow.contains(field)) flow[field] = source_flow[field];
			}
			flows.push_back(std::move(flow));
		}
		stream["flows"] = std::move(flows);
		entries.push_back(json{{"proto", source.value("proto", std::string{})}, {"stream", std::move(stream)}});
	}
	return json{{"time", time}, {"streams", std::move(entries)}};
}

json stream_state_projector::export_state() const {
	return json{{"streams", m_streams}, {"last_checkpoint_minute", m_last_checkpoint_minute}};
}

void stream_state_projector::import_state(const json &state) {
	if(!state.is_object()) return;
	if(state.contains("streams") && state["streams"].is_object()) m_streams = state["streams"];
	if(state.contains("last_checkpoint_minute") && state["last_checkpoint_minute"].is_number_integer()) {
		m_last_checkpoint_minute = state["last_checkpoint_minute"].get<std::int64_t>();
	}
}

void stream_state_projector::write_delta(const json &event, const char *action) {
	json delta{
		{"schema_version", 2},
		{"record_type", "stream_state_delta"},
		{"time", event.value("event_time", event.value("time", 0.0))},
		{"action", action},
		{"source_record_id", event.value("record_id", std::string{})},
		{"event", event},
	};
	m_delta_writer->dump_at(delta["time"].get<double>(), delta);
}

void stream_state_projector::checkpoint_if_needed(double time) {
	const auto minute = static_cast<std::int64_t>(std::floor(time / 60.0));
	if(m_last_checkpoint_minute == minute) return;
	write_checkpoint(time);
	m_last_checkpoint_minute = minute;
}

void stream_state_projector::write_checkpoint(double time) const {
	const auto path = checkpoint_path(m_cfg.root_dir, time);
	std::filesystem::create_directories(path.parent_path());
	const auto temporary = path.string() + ".tmp";
	std::ofstream output(temporary, std::ios::trunc);
	if(!output) return;
	json checkpoint = export_state();
	checkpoint["schema_version"] = 2;
	checkpoint["record_type"] = "stream_state_checkpoint";
	checkpoint["time"] = time;
	output << checkpoint.dump() << '\n';
	output.flush();
	std::error_code ec{};
	std::filesystem::rename(temporary, path, ec);
	if(ec) {
		std::filesystem::remove(path, ec);
		ec.clear();
		std::filesystem::rename(temporary, path, ec);
	}
}
