namespace {

const std::string detailed_flag = "detailed";

} // namespace

hls_dispatch_state::hls_dispatch_state()
	: hls_dispatch_state(config{}) {
}

hls_dispatch_state::hls_dispatch_state(config cfg)
	: m_cfg(cfg) {
}

bool hls_dispatch_state::known(const std::string &conn_key) const {
	return m_connections.known(conn_key);
}

bool hls_dispatch_state::tcp_fallback_ready(const std::string &conn_key, double now) const {
	const auto *entry = m_connections.find(conn_key);
	if(!entry || m_connections.has_flag(conn_key, detailed_flag)) {
		return false;
	}
	return (now - entry->first_seen) >= m_cfg.fallback_delay_sec;
}

void hls_dispatch_state::remember_candidate(const std::string &conn_key, double now) {
	m_connections.touch(conn_key, now);
}

void hls_dispatch_state::remember_detailed(const std::string &conn_key, double now) {
	remember_candidate(conn_key, now);
	m_connections.set_flag(conn_key, detailed_flag);
}

void hls_dispatch_state::prune(double now) {
	m_connections.prune(now, m_cfg.ttl_sec);
}
