  addTimelineEvent(input: NormalizedTimelineInput) {
    this.tick(input.time);
    this.latestTimelineTime = Math.max(this.latestTimelineTime ?? input.time, input.time);
    if (input.kind === "stream_reclassified" || input.kind === "flow_reclassified") {
      const timelineKey = input.subjectType === "flow" ? `${input.streamKey}::${input.flowKey ?? ""}` : input.streamKey;
      this.timeline.delete(timelineKey);
      this.emit("timeline:update");
      return;
    }
    const row = this.ensureTimelineRow(input);
    row.firstSeen = Math.min(row.firstSeen, input.time);
    row.lastSeen = Math.max(row.lastSeen, input.time);

    if (input.kind === "stream_detected" || input.kind === "stream_recovered" || input.kind === "flow_detected" || input.kind === "flow_recovered") {
      row.active = true;
      const current = row.segments[row.segments.length - 1];
      if (!current || current.end !== null) {
        row.segments.push({ start: input.time, end: null });
      }
    } else if (input.kind === "stream_lost" || input.kind === "flow_lost") {
      row.active = false;
      .reverse();
  }

  getSummary(): Summary {
    const byKind: Record<string, number> = {};
    let activeStreams = 0;
    for (const stream of this.streams.values()) {
      byKind[stream.kind] = (byKind[stream.kind] ?? 0) + 1;
      if (stream.active) activeStreams += 1;
    }
    return {
      totalStreams: this.streams.size,
      activeStreams,
      updatedAt: this.latestUpdate,
      byKind
    };
  }

  private applyTransportReclassification(event: EventLogItem) {
    if (event.type !== "transport_reclassified") return;
    const detail = asRecord(event.detail);
    const from = asRecord(detail?.from);
    if (!from) return;
    let changed = false;
    for (const entry of recordArray(from.flows)) {
      const source = asRecord(entry.source);
      const streamKey = stringRecordValue(source?.stream_key);
      const flowKey = stringRecordValue(source?.flow_key);
      if (!streamKey || !flowKey) continue;
      changed = this.removeReclassifiedFlow(streamKey, flowKey) || changed;
    }
    for (const entry of recordArray(from.streams)) {
      const source = asRecord(entry.source);
      const streamKey = stringRecordValue(source?.stream_key);
      if (!streamKey) continue;
      changed = this.removeReclassifiedStream(streamKey) || changed;
    }
    if (changed) this.emit("streams:update");
  }

  private removeReclassifiedFlow(streamKey: string, flowKey: string) {
    const stream = this.streams.get(streamKey);
    if (!stream) return false;
    const count = stream.flows.length;
    stream.flows = stream.flows.filter((flow) => flow.flowKey !== flowKey);
    if (stream.flows.length === count) return false;
    this.flowLostSinceWall.delete(flowKey);
    this.flowHistory.delete(flowKey);
    this.flowSparklines.delete(flowKey);
    if (stream.flows.length === 0) this.removeReclassifiedStream(streamKey);
    else {
    if (severity === "error" || severity === "critical") return "error";
    if (severity === "warning" || severity === "warn") return "warn";
  }
  if (/error|failed|failure/i.test(type)) return "error";
  if (/warn|stale|drop|loss|timeout/i.test(type)) return "warn";
  return "info";
}

function messageForType(type: string, detail?: AnyRecord) {
  if (type === "transport_reclassified") {
    const from = stringValue(recordValue(detail)?.from?.proto) ?? "transport";
    const to = stringValue(recordValue(detail)?.to?.proto) ?? "specialized protocol";
    return `${from} → ${to} reclassified`;
  }
  return type
    .split("_")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(" ");

