int stream::process(const info &i) {
	touch(i.time_epoch);
	m_metrics.lifetime.update(i.time_epoch);
	if(i.role == "playlist" && i.is_request) {
		m_has_playlist = true;
		m_playlist_last_seen = i.time_epoch;
	}
	if(i.is_request) {
		m_metrics.request_count.inc();
		m_metrics.request_interval.update(i.time_epoch);
	}
	if(i.is_response) {
		m_metrics.response_count.inc();
		m_metrics.status.update(i.effective_status_code);
		if(i.effective_status_code >= 400) {
			m_metrics.error_count.inc();
		}
		if(i.has_content_length) {
			m_metrics.download_bytes.add(i.content_length);
			m_metrics.bitrate.update(i.time_epoch, i.content_length);
		}
		if(i.has_request_time && i.time_epoch >= i.request_time) {
			m_metrics.download_time.add(i.time_epoch - i.request_time);
		}
	}

	const auto fid = resolve_flow_id(i);
	auto it = m_flows.find(fid);
	if(it == m_flows.end()) {
		it = m_flows.emplace(fid, std::make_unique<flow>(m_sid, fid, i.interface_name, m_cfg.timeout.error_recovery_sec, m_events, i)).first;
		it->second->emit_detected(i.time_epoch);
	}
	return it->second->process(i);
}

int stream::observe_transport(const flow_id &fid, const info &i) {
	touch(i.time_epoch);
	m_metrics.lifetime.update(i.time_epoch);
	const std::uint64_t bytes = i.tcp_len > 0 ? i.tcp_len : i.frame_len;
	if(bytes > 0) {
		m_metrics.download_bytes.add(bytes);
		m_metrics.bitrate.update(i.time_epoch, bytes);
	}

	if(m_has_playlist) {
		m_playlist_last_seen = i.time_epoch;
	}

	auto it = m_flows.find(fid);
	if(it == m_flows.end()) {
		it = m_flows.emplace(fid, std::make_unique<flow>(m_sid, fid, i.interface_name, m_cfg.timeout.error_recovery_sec, m_events, i)).first;
		it->second->emit_detected(i.time_epoch);
	}
	return it->second->observe_transport(i);
}

int stream::append_metrics(double now, json::array_t &out) {
	const auto bitrate = m_metrics.bitrate.snapshot_at(now);
	json j = stream_json::make_stream_metrics_base(proto_name,
	                                               m_sid.interface_id,
	                                               m_interface_name,
	                                               m_stream_key,
	                                               m_sid.vlan);
	j["endpoint"] = {
		{"host", m_sid.host},
		{"port", m_sid.port},
		{"playlist", m_sid.playlist_path},
	};
	j.update(json{
		{"request_count", { {"window", m_metrics.request_count.count()}, {"total", m_metrics.request_count.total()} }},
		{"response_count", { {"window", m_metrics.response_count.count()}, {"total", m_metrics.response_count.total()} }},
		{"error_count", { {"window", m_metrics.error_count.count()}, {"total", m_metrics.error_count.total()} }},
		{"download_bytes", { {"window", m_metrics.download_bytes.count()}, {"total", m_metrics.download_bytes.total()} }},
		{"bitrate", {
			{"bps", bitrate.bps},
			{"count", bitrate.stats.count},
			{"min", bitrate.stats.min},
			{"max", bitrate.stats.max},
			{"avg", bitrate.stats.avg()},
		}},
		{"request_interval", {
			{"seconds", m_metrics.request_interval.value()},
			{"count", m_metrics.request_interval.stats().count},
			{"min", m_metrics.request_interval.stats().min},
			{"max", m_metrics.request_interval.stats().max},
			{"avg", m_metrics.request_interval.stats().avg()},
		}},
		{"download_time", stats_json(m_metrics.download_time)},
		{"status", status_json(m_metrics.status)},
		{"duration", {
			{"seconds", m_metrics.lifetime.duration_sec()},
			{"first_seen", m_metrics.lifetime.first_seen()},
			{"last_seen", m_metrics.lifetime.last_seen()},
		}},
	});
	if (!bitrate.available) {
		for (const char *key : {"bps", "min", "max", "avg"}) {
			j["bitrate"][key] = nullptr;
		}
	}

	out.push_back(std::move(j));

	m_metrics.request_count.reset();
	m_metrics.response_count.reset();
	m_metrics.error_count.reset();
	m_metrics.download_bytes.reset();
	m_metrics.bitrate.clear_stats();
	m_metrics.request_interval.clear_stats();
	m_metrics.download_time.clear();
	m_metrics.status.reset_window();

	for(auto& [fid, flow] : m_flows) {
		flow->append_metrics(now, out);
	}
	return 0;
}

int stream::append_list(double now, json::array_t &out) {
	json::array_t flows;
	for(auto& [fid, flow] : m_flows) {
		flows.push_back(flow->to_list_json(now));
	}
	json stream_entry = stream_json::make_stream_list_base(m_sid.interface_id,
	                                                     m_interface_name,
	                                                     m_stream_key,
	                                                     m_sid.vlan);
	stream_entry["endpoint"] = {
		{"host", m_sid.host},
		{"port", m_sid.port},
		{"playlist", m_sid.playlist_path},
	};
	stream_entry["last_seen"] = last_seen();
	stream_entry["flow_count"] = m_flows.size();
	stream_entry["flows"] = std::move(flows);
	out.push_back(json{
		{"proto", proto_name},
		{"stream", std::move(stream_entry)},
	});
	return 0;
}

int stream::update_events(double now) {
	for(auto& [fid, flow] : m_flows) {
		flow->update_events(now);
	}
	if(m_has_playlist && (now - m_playlist_last_seen) >= m_cfg.timeout.playlist_stall_sec) {
		if(m_playlist_stall_state.occur(now)) {
			m_events.emit(make_event(now, "playlist_stalled_occurred", json{
				{"last_playlist_seen", m_playlist_last_seen},
				{"stall_seconds", now - m_playlist_last_seen},
				{"severity", "warning"},
			}));
		}
	}
	else if(m_playlist_stall_state.recover(now)) {
		m_events.emit(make_event(now, "playlist_stalled_recovered", json{
			{"last_playlist_seen", m_playlist_last_seen},
			{"severity", "info"},
		if(deferred == m_deferred_by_connection.end()) {
			i.payload_seen = i.has_tcp_payload;
			deferred = m_deferred_by_connection.emplace(conn_key, deferred_response{req, i, conn_key}).first;
		}
		if(!same_request(deferred->second.req, req)) {
			trace(4, "hls: tcp transport ignored for different request conn=%s tcp_len=%u fin=%d",
			      conn_key.c_str(), static_cast<unsigned>(i.tcp_len), i.tcp_fin ? 1 : 0);
			rc |= flush_deferred(i.time_epoch);
			rc |= flush_pending_timeouts(i.time_epoch);
			return rc;
		}

		auto &state = deferred->second;
		state.payload_bytes += i.tcp_len;
		state.response.payload_seen = state.response.payload_seen || i.has_tcp_payload;
		state.response.has_tcp_payload = state.response.has_tcp_payload || i.has_tcp_payload;
		state.response.tcp_len = i.tcp_len;
		state.response.tcp_fin = i.tcp_fin;
		state.response.time_epoch = i.time_epoch;
		state.last_activity_time = i.time_epoch;
		trace(4, "hls: tcp transport accumulated conn=%s tcp_len=%u fin=%d total_bytes=%llu",
		      conn_key.c_str(),
		      static_cast<unsigned>(i.tcp_len),
		      i.tcp_fin ? 1 : 0,
		      static_cast<unsigned long long>(state.payload_bytes));
		if(i.tcp_fin) {
			if(!state.response.payload_seen && state.response.status_code == 0) {
				state.response.status_code = 504;
				state.response.effective_status_code = 504;
				state.response.status_source = "timeout";
			}
			rc |= complete_deferred(conn_key, "tcp_fin");
		}
		else if(deferred_content_complete(state)) {
			rc |= complete_deferred(conn_key, "content_length");
		}
		rc |= flush_deferred(i.time_epoch);
		rc |= flush_pending_timeouts(i.time_epoch);
		return rc;
	}

	const auto hk = host_key(i.interface_id, i.host, i.port, i.vlan);
	const bool has_known_playlist = m_playlists_by_host.find(hk) != m_playlists_by_host.end();
	if(i.role == "other" && !has_known_playlist) {
		trace(4, "hls: ignore other request without playlist host=%s port=%u path=%s",
		      i.host.c_str(), static_cast<unsigned>(i.port), i.path.c_str());
		rc |= flush_deferred(i.time_epoch);
		rc |= flush_pending_timeouts(i.time_epoch);
		return rc;
	}
	const auto sid = resolve_stream_id(i);
	merge_monitoring_target_ids(m_monitoring_target_ids[sid], target_ids);
	if(!stream_name.empty()) {
		m_stream_display_names[sid] = stream_name;
		m_events.set_stream_display_name(sid.to_stream_key(), stream_name);
	}
	const auto fid = flow_id::from_request(i.interface_id, i.host, i.port, i.path, i.role, i.vlan);
	if(i.role == "playlist") {
		auto &playlists = m_playlists_by_host[hk];
		if(std::find(playlists.begin(), playlists.end(), i.path) == playlists.end()) {
			playlists.push_back(i.path);
			std::sort(playlists.begin(), playlists.end(), [](const auto &lhs, const auto &rhs) {
				return path_dir(lhs).size() > path_dir(rhs).size();
			});
		}
	}
	pending_request req{sid, fid, i.time_epoch};
	const std::string conn_key = connection_key(i);
	if(m_deferred_by_connection.find(conn_key) != m_deferred_by_connection.end()) {
		rc |= complete_deferred(conn_key, "next_request");
	}
	auto &queue = m_pending_by_connection[conn_key];
	queue.push_back(req);
	remember_connection_activity(conn_key, sid, fid);
	if(i.has_tcp_stream) {
		m_pending_by_tcp_stream[i.tcp_stream] = req;
	}
	trace(3, "hls: request registered method=%s role=%s path=%s conn=%s conn_pending=%zu has_tcp_stream=%d tcp_stream=%u stream=%s flow=%s",
	      i.method.c_str(),
	      i.role.c_str(),
	      i.path.c_str(),
	      conn_key.c_str(),
	      queue.size(),
	      i.has_tcp_stream ? 1 : 0,
	      static_cast<unsigned>(i.tcp_stream),
	      sid.to_stream_key().c_str(),
	      fid.to_flow_key(sid).c_str());

	rc |= process_resolved(sid, fid, i);
	rc |= flush_deferred(i.time_epoch);
	rc |= flush_pending_timeouts(i.time_epoch);
	return rc;
}

int streams::append_metrics(double now, json::array_t &out) {
	flush_deferred(now);
	flush_pending_timeouts(now);
	for(auto& [sid, stream] : m_streams) {
		const auto first = out.size();
		stream->append_metrics(now, out);
		append_monitoring_target_ids(out, first, m_monitoring_target_ids[sid]);
		append_stream_display_name(out, first, m_stream_display_names[sid]);
	}
	return 0;
}

