  value?: number;
  avg?: number;
  min?: number;
  max?: number;
  count?: number;
  interval?: boolean;
};

export type MetricPoint = NumericStat & {
  time: number;
};

export type TimelineSegment = {
  start: number;
  end: number | null;
};

export type TimelineWindow = {
  from: number;
  to: number;
};
export type TimelineDataGap = {
  from: number;
  to: number;
  reason: "monitor-unavailable";
};

export type LiveStatus = {
  observedAt: number | null;
};


export type ScopeLayer =
  | { kind: "vlan"; id?: string; priority?: string; dei?: string }
  | { kind: "vxlan"; vni?: string };

export type NetworkScope = {
  interfaceId?: number;
  interfaceName?: string;
  known: boolean;
  layers: ScopeLayer[];
};

export type TimelineRow = {
  rowType: "stream" | "flow";
  streamKey: string;
  flowKey?: string;
  parentStreamKey?: string;
  kind: string;
  proto: string;
  label: string;
  displayName?: string;
  role?: string;
  endpointSrc?: string;
  endpointDst?: string;
  interfaceId?: number;
  interfaceName?: string;
  scope?: NetworkScope;
  active: boolean;
  firstSeen: number;
  lastSeen: number;
  segments: TimelineSegment[];
};

export type TimelineViewResponse = {
  gaps: TimelineDataGap[];
  rows: TimelineRow[];
  window: TimelineWindow;
  available: TimelineWindow;
  source: "live" | "history";
};

export type ProtocolDetail = {
  label?: string;
  value: string;
};

export type StreamAlertCause = { alertId: string; metric?: string; category: "quality" | "other"; severity: "warning" | "error" | "critical"; value?: number; threshold?: number; operator?: string; };

export type StreamAlertSummary = {
  severity: "warning" | "error" | "critical";
  count: number;
  lastChangedAt: number;
  causes: StreamAlertCause[];
};

export type FlowListItem = {
  flowKey: string;
  role: string;
  label: string;
  scope: NetworkScope;
  active: boolean;
  interfaceId?: number;
  interfaceName?: string;
  endpointSrc?: string;
  endpointDst?: string;
  monitoringTargetIds?: string[];
  lastSeen: number;
  bitrate: NumericStat;
  protocolDetails?: ProtocolDetail[];
  alert?: StreamAlertSummary;
  recentAlert?: StreamAlertSummary;
  sparkline: number[];
  overview: OverviewStats;
};

export type StreamListItem = {
  streamKey: string;
  kind: string;
  proto: string;
  label: string;
  displayName?: string;
  scope: NetworkScope;
  endpointA?: string;
  endpointB?: string;
  sessionDst?: string;
  streamId?: string;
  protocolDetails?: ProtocolDetail[];
  interfaceId?: number;
  interfaceName?: string;
  active: boolean;
  lastSeen: number;
  flowCount: number;
  flowRoles: string[];
  bitrate: NumericStat;
  sparkline: number[];
  alert?: StreamAlertSummary;
  recentAlert?: StreamAlertSummary;
  overview: OverviewStats;
  flows: FlowListItem[];
};

export type OverviewStats = {
  gap: number;
  dup: number;
  reorder: number;
  events: number;
  /** False when the selected historical snapshot has no event-journal aggregation. */
  eventsAvailable?: boolean;
};

export type FlowState = {
  flowKey: string;
  role: string;
  label: string;
  active: boolean;
  interfaceId?: number;
  interfaceName?: string;
  endpointSrc?: string;
  endpointDst?: string;
  monitoringTargetIds?: string[];
  lastSeen: number;
  metrics: Record<string, NumericStat>;
  protocolDetails?: ProtocolDetail[];
};

export type StreamState = Omit<StreamListItem, "flows"> & {
  flows: FlowState[];
};

export type MetricDescriptor = {
  key: string;
  label: string;
