  category: "primary" | "secondary" | "stat";
  display: "range-line" | "line" | "bar" | "stat";
  priority: number;
};

export type InterfaceCounters = {
  bytes: NumericStat;
  packets: NumericStat;
  errors: NumericStat;
  dropped: NumericStat;
};

export type InterfaceLinkInfo = {
  speedMbps?: number;
  duplex?: string;
  operstate?: string;
  carrier?: boolean;
  mtu?: number;
  mac?: string;
};

