import { EventEmitter } from "node:events";
import { descriptorForMetric, type NormalizedInterfaceInput, type NormalizedMetricInput, type NormalizedTimelineInput } from "../normalizer";
import type {
  EventLogItem,
  FlowMetricPoint,
  FlowState,
  InterfaceListItem,
  InterfaceMetricsResponse,
  MetricDescriptor,
  MetricPoint,
  NumericStat,
  OverviewStats,
  StreamListItem,
  StreamMetricsResponse,
  StreamState,
  Summary,
  TimelineRow,
  TimeSeriesMetric,
  TopologySnapshot
} from "../types";
import { TopologyDisplay } from "./topologyDisplay";

export class StreamStore extends EventEmitter {
  private interfaces = new Map<string, InterfaceListItem>();
  private interfaceHistory = new Map<string, FlowMetricPoint[]>();
  private streams = new Map<string, StreamState>();
  private streamSortOrder = new Map<string, number>();
  private lostSinceWall = new Map<string, number>();
  private flowLostSinceWall = new Map<string, number>();
  private flowHistory = new Map<string, FlowMetricPoint[]>();
  private flowSparklines = new Map<string, number[]>();
  private latestUpdate?: number;
  private latestTimelineTime?: number;
  private events: EventLogItem[] = [];
  private eventIds = new Set<string>();
  private timeline = new Map<string, TimelineRow>();
  private eventCountsByStream = new Map<string, number>();
  private eventCountsByStreamOnly = new Map<string, number>();
  private eventCountsByFlow = new Map<string, number>();
  private streamsErrorCountMode = 0;
  private sparklineSamples = 60;
  private topology?: TopologySnapshot;
  private readonly topologyDisplay: TopologyDisplay;

  constructor(
    private historyWindowSec: number,
    private readonly timelineWindowSec: number,
    private lostRetentionSec: number,
    private readonly maxEvents = 1000,
    private readonly maxTimelineRows = 20000,
    topologyStaleRetentionSec = 600,
    topologyMaxStaleEdges = 2000,
    topologyMaxDetailFlowsPerRelation = 200,
    streamsErrorCountMode = 0,
    streamsSparklineSamples = 60
  ) {
    super();
    this.streamsErrorCountMode = streamsErrorCountMode;
    this.sparklineSamples = normalizeSparklineSamples(streamsSparklineSamples);
    this.topologyDisplay = new TopologyDisplay(Math.max(0, topologyStaleRetentionSec), Math.max(0, topologyMaxStaleEdges), Math.max(1, topologyMaxDetailFlowsPerRelation));
  }

  updateRuntimeConfig(values: { historyWindowSec: number; staleAfterSec: number; lostRetentionSec: number; streamsErrorCountMode: number; streamsSparklineSamples: number }) {
    this.historyWindowSec = values.historyWindowSec;
    const historyNow = this.latestUpdate ?? Date.now() / 1000;
    for (const history of this.flowHistory.values()) this.prune(history, historyNow);
    for (const history of this.interfaceHistory.values()) this.prune(history, historyNow);
    this.lostRetentionSec = values.lostRetentionSec;
    this.streamsErrorCountMode = values.streamsErrorCountMode;
    this.sparklineSamples = normalizeSparklineSamples(values.streamsSparklineSamples);
    this.trimLiveSparklines();
    this.tick();
    this.emit("streams:update");
  }

  applyStreamSnapshot(streams: StreamState[], observedAtWall: number) {
    this.tick(observedAtWall);
    const seen = new Set<string>();
    let changed = streams.length > 0;
    for (const stream of streams) {
      seen.add(stream.streamKey);
      this.lostSinceWall.delete(stream.streamKey);
      this.upsertStream(stream, observedAtWall);
    }

    for (const [streamKey, stream] of this.streams) {
      if (seen.has(streamKey)) continue;
      if (!this.lostSinceWall.has(streamKey)) {
        this.lostSinceWall.set(streamKey, observedAtWall);
        stream.active = false;
        for (const flow of stream.flows) {
          if (!this.flowLostSinceWall.has(flow.flowKey)) {
            this.flowLostSinceWall.set(flow.flowKey, observedAtWall);
          }
          flow.active = false;
        }
        changed = true;
      }
    }

    changed = this.pruneExpiredLostStreams(observedAtWall) || changed;
    if (changed) {
      this.emit("streams:update");
    }
  }

  upsertStream(stream: StreamState, observedAtWall?: number) {
    this.tick(observedAtWall ?? Date.now() / 1000);
    this.attachInterfaceName(stream);
    const existing = this.streams.get(stream.streamKey);
    const mergedFlows = mergeFlows(existing?.flows ?? [], stream.flows, this.flowLostSinceWall, observedAtWall);
    const next: StreamState = {
      ...existing,
      ...stream,
      flows: mergedFlows,
      lastSeen: Math.max(existing?.lastSeen ?? Number.NEGATIVE_INFINITY, stream.lastSeen),
      flowCount: mergedFlows.length,
      flowRoles: [...new Set(mergedFlows.map((flow) => flow.role))],
      bitrate: existing?.bitrate ?? {},
      sparkline: existing?.sparkline ?? []
    };
    this.streams.set(stream.streamKey, next);
    this.latestUpdate = Math.max(this.latestUpdate ?? 0, next.lastSeen);
    this.lostSinceWall.delete(stream.streamKey);
  }

  upsertInterfaces(items: NormalizedInterfaceInput[]) {
    if (items.length === 0) return;
    this.tick(Date.now() / 1000);
    for (const item of items) {
      const promotedNameKey = item.interfaceId !== undefined ? `name:${item.name}` : undefined;
      const promoted = promotedNameKey && promotedNameKey !== item.key ? this.interfaces.get(promotedNameKey) : undefined;
      const existing = this.interfaces.get(item.key) ?? promoted;
      const rxSparkline = [...(existing?.rxSparkline ?? [])];
      const txSparkline = [...(existing?.txSparkline ?? [])];
      if (item.hasMetrics) {
        rxSparkline.push(item.rxBitrate.value ?? item.rxBitrate.avg ?? 0);
        txSparkline.push(item.txBitrate.value ?? item.txBitrate.avg ?? 0);
        this.trimSparkline(rxSparkline);
        this.trimSparkline(txSparkline);
        const history = [
          ...(this.interfaceHistory.get(item.key) ?? []),
          ...(promotedNameKey && promotedNameKey !== item.key ? this.interfaceHistory.get(promotedNameKey) ?? [] : [])
        ];
        history.push({ time: item.lastSeen ?? Date.now() / 1000, metrics: interfaceMetricsForHistory(item) });
        this.prune(history, item.lastSeen ?? Date.now() / 1000);
        this.interfaceHistory.set(item.key, history);
      }
      if (promotedNameKey && promotedNameKey !== item.key) {
        this.interfaces.delete(promotedNameKey);
        this.interfaceHistory.delete(promotedNameKey);
      }
      this.interfaces.set(item.key, {
        ...existing,
        ...withoutInterfaceMarker(item),
        rx: item.hasMetrics ? item.rx : existing?.rx ?? item.rx,
        tx: item.hasMetrics ? item.tx : existing?.tx ?? item.tx,
        rxBitrate: item.hasMetrics ? item.rxBitrate : existing?.rxBitrate ?? item.rxBitrate,
        txBitrate: item.hasMetrics ? item.txBitrate : existing?.txBitrate ?? item.txBitrate,
        rxSparkline,
        txSparkline,
        streamCount: existing?.streamCount ?? 0
      });
    }
    this.refreshInterfaceNames();
    this.refreshTimelineNames();
    this.emit("streams:update");
  }

  addTimelineEvent(input: NormalizedTimelineInput) {
    this.tick(input.time);
    this.latestTimelineTime = Math.max(this.latestTimelineTime ?? input.time, input.time);
    if (input.kind === "stream_reclassified" || input.kind === "flow_reclassified") {
      const timelineKey = input.subjectType === "flow" ? `${input.streamKey}::${input.flowKey ?? ""}` : input.streamKey;
      this.timeline.delete(timelineKey);
      this.emit("timeline:update");
      return;
    }
    const row = this.ensureTimelineRow(input);
    row.firstSeen = Math.min(row.firstSeen, input.time);
    row.lastSeen = Math.max(row.lastSeen, input.time);

    if (input.kind === "stream_detected" || input.kind === "stream_recovered" || input.kind === "flow_detected" || input.kind === "flow_recovered") {
      row.active = true;
      const current = row.segments[row.segments.length - 1];
      if (!current || current.end !== null) {
        row.segments.push({ start: input.time, end: null });
      }
    } else if (input.kind === "stream_lost" || input.kind === "flow_lost") {
      row.active = false;
      const current = row.segments[row.segments.length - 1];
      if (current && current.end === null) {
        current.end = input.time;
      } else if (!current) {
        row.segments.push({ start: input.time, end: input.time });
      }
    }

    this.pruneTimeline(this.latestTimelineTime);
    this.enforceTimelineBudget();
    this.emit("timeline:update");
  }

  addMetric(input: NormalizedMetricInput) {
    this.addMetrics([input]);
  }

  addMetrics(inputs: NormalizedMetricInput[]) {
    const updatedStreams = new Set<string>();
    let latestTime = Number.NEGATIVE_INFINITY;
    for (const input of inputs) {
      this.tick(input.time);
      // Lifecycle projection owns identity and active/lost state. A historical
      // metric sample must not recreate a stream or flow that has been lost.
      const stream = this.streams.get(input.streamKey);
      if (!stream) continue;
      const flow = stream.flows.find((item) => item.flowKey === input.flowKey);
      if (!flow) continue;
      if (input.interfaceId !== undefined) {
        stream.interfaceId ??= input.interfaceId;
        flow.interfaceId ??= input.interfaceId;
        const interfaceName = this.interfaceById(input.interfaceId)?.name;
        if (interfaceName) {
          stream.interfaceName ??= interfaceName;
          flow.interfaceName ??= interfaceName;
        }
      }
      flow.metrics = input.metrics;
      flow.lastSeen = input.time;
      // Lifecycle records establish the flow identity but do not include its
      // monitoring-target classification. Metric samples are authoritative
      // for that classification, which is also used by the Inspector to
      // resolve target-specific Alert policy overrides.
      if (input.monitoringTargetIds?.length) flow.monitoringTargetIds = input.monitoringTargetIds;

      const history = this.flowHistory.get(input.flowKey) ?? [];
      history.push({ time: input.time, metrics: input.metrics });
      const bitrate = input.metrics.bitrate?.value ?? input.metrics.bitrate?.avg ?? 0;
      const sparkline = this.flowSparklines.get(input.flowKey) ?? [];
      sparkline.push(bitrate);
      this.trimSparkline(sparkline);
      this.flowSparklines.set(input.flowKey, sparkline);
      this.prune(history, input.time);
      this.flowHistory.set(input.flowKey, history);
      this.recomputeStreamBitrate(stream, input.time);
      updatedStreams.add(input.streamKey);
      latestTime = Math.max(latestTime, input.time);
    }
    if (updatedStreams.size === 0) return;
    this.latestUpdate = Math.max(this.latestUpdate ?? 0, latestTime);
    this.emit("streams:update");
    for (const streamKey of updatedStreams) this.emit("metrics:update", streamKey);
  }


  applyTopologySnapshot(snapshot: TopologySnapshot) {
    this.topology = this.topologyDisplay.apply(snapshot);
    this.emit("topology:update");
  }

import { createReadStream, existsSync, readdirSync } from "node:fs";
import path from "node:path";
import readline from "node:readline";
import { normalizeStreamsLine, type NormalizedInterfaceInput, type NormalizedMetricInput } from "../normalizer";
import type { InterfaceListItem, NumericStat, OverviewStats, StreamListItem } from "../types";
import type { OverviewEventCounts } from "./events_query";

export type JsonRecord = Record<string, any>;
type StreamsSnapshot = { time: number; streams: StreamListItem[]; interfaces: InterfaceListItem[] };

export type ProjectedStreamState = {
  streams: JsonRecord;
  checkpointTime: number;
  hasRecords: boolean;
  latestDeltaRecordIds: Set<string>;
};

export async function queryProjectedStreamsAt(root: string, time: number): Promise<StreamsSnapshot | undefined> {
  const state = await loadProjectedStreamState(root, time);
  if (!state.hasRecords) return undefined;
  return materializeProjectedStreams(state.streams, time);
}

export async function loadProjectedStreamState(root: string, time: number): Promise<ProjectedStreamState> {
  const checkpoint = await findLatestCheckpoint(path.join(root, "checkpoint"), time);
  const streams: JsonRecord = checkpoint?.streams && isRecord(checkpoint.streams) ? structuredClone(checkpoint.streams) : {};
  const checkpointTime = Number(checkpoint?.time ?? Number.NEGATIVE_INFINITY);
  const deltaFiles = listNdjsonFiles(path.join(root, "delta"), checkpointTime, time);
  const latestDeltaRecordIds = new Set<string>();
  let hasRecords = Boolean(checkpoint);

  for (const [index, file] of deltaFiles.entries()) {
    const lines = readline.createInterface({ input: createReadStream(file), crlfDelay: Infinity });
    for await (const line of lines) {
      const delta = parseRecord(line);
      const eventTime = Number(delta?.time ?? 0);
      if (!delta || eventTime < checkpointTime || eventTime > time) continue;
      if (index === deltaFiles.length - 1) {
        const sourceRecordId = stringValue(delta.source_record_id);
        if (sourceRecordId) latestDeltaRecordIds.add(sourceRecordId);
      }
      applyProjectedLifecycleEvent(streams, delta.event);
      hasRecords = true;
    }
  }
  return { streams, checkpointTime, hasRecords, latestDeltaRecordIds };
}

export function applyProjectedLifecycleEvent(streams: JsonRecord, event: unknown) {
  if (!isRecord(event) || !isRecord(event.source)) return;
  const source = event.source;
  const detail = isRecord(event.detail) ? event.detail : {};
  const type = String(event.type ?? "");
  const time = Number(event.event_time ?? event.time ?? 0);
  if (type === "transport_reclassified") {
    applyProjectedReclassification(streams, detail, time);
    return;
  }
  const streamKey = stringValue(source.stream_key);
  if (!streamKey || !Number.isFinite(time)) return;
  const stream = streams[streamKey] ??= { stream_key: streamKey, flows: {}, first_seen: time };
  if (isAlertStateUpdate(type)) {
    const flowKey = stringValue(source.flow_key);
    if (flowKey) {
      stream.flows ??= {};
      const flow = stream.flows[flowKey] ??= { flow_key: flowKey, first_seen: time };
      copyIdentity(flow, source);
      updateProjectedAlertState(flow, source, detail, type, time);
    } else {
      updateProjectedAlertState(stream, source, detail, type, time);
    }
    return;
  }
  copyIdentity(stream, source);
  stream.last_seen = time;
  if (detail.endpoint !== undefined) stream.endpoint = detail.endpoint;

  if (isLifecycle(type, "stream")) {
    stream.active = isDetect(type);
    if (type === "stream_lost" && isRecord(stream.flows)) {
      for (const flow of Object.values(stream.flows)) {
        if (!isRecord(flow)) continue;
        flow.active = false;
        flow.last_seen = time;
      }
    }
    return;
  }

  const flowLifecycle = isLifecycle(type, "flow");
  if (!flowLifecycle && !isFlowStateUpdate(type)) return;
  const flowKey = stringValue(source.flow_key);
  if (!flowKey) return;
  stream.flows ??= {};
  const flow = stream.flows[flowKey] ??= { flow_key: flowKey, first_seen: time };
  copyIdentity(flow, source);
  flow.last_seen = time;
  if (detail.endpoint !== undefined) flow.endpoint = detail.endpoint;
  if (detail.role !== undefined) flow.role = detail.role;
  if (flowLifecycle) {
    flow.active = isDetect(type);
    if (isDetect(type)) stream.active = true;
  }
}

function applyProjectedReclassification(streams: JsonRecord, detail: JsonRecord, time: number) {
  const from = isRecord(detail.from) ? detail.from : {};
  for (const entry of Array.isArray(from.flows) ? from.flows : []) {
    if (!isRecord(entry) || !isRecord(entry.source)) continue;
    const streamKey = stringValue(entry.source.stream_key);
    const flowKey = stringValue(entry.source.flow_key);
    const stream = streamKey ? streams[streamKey] : undefined;
    if (!flowKey || !isRecord(stream) || !isRecord(stream.flows) || !isRecord(stream.flows[flowKey])) continue;
    stream.flows[flowKey].active = false;
    stream.flows[flowKey].last_seen = time;
  }
  for (const entry of Array.isArray(from.streams) ? from.streams : []) {
    if (!isRecord(entry) || !isRecord(entry.source)) continue;
    const streamKey = stringValue(entry.source.stream_key);
    const stream = streamKey ? streams[streamKey] : undefined;
    if (!isRecord(stream)) continue;
    stream.active = false;
    stream.last_seen = time;
    if (!isRecord(stream.flows)) continue;
    for (const flow of Object.values(stream.flows)) {
      if (!isRecord(flow)) continue;
      flow.active = false;
      flow.last_seen = time;
    }
  }
}

function isAlertStateUpdate(type: string) { return type === "alert_detected" || type === "alert_recovered"; }

function updateProjectedAlertState(subject: JsonRecord, source: JsonRecord, detail: JsonRecord, type: string, time: number) {
  const stateKey = stringValue(detail.state_key) || stringValue(source.state_key) || stringValue(detail.alert_id) || stringValue(source.alert_id);
  if (!stateKey) return;
  const alert = { ...source, ...detail, state_key: stateKey };
  const active = isRecord(subject.alerts) ? subject.alerts : subject.alerts = {};
  const recent = isRecord(subject.recent_alerts) ? subject.recent_alerts : subject.recent_alerts = {};
  const previous = isRecord(active[stateKey]) ? active[stateKey] : undefined;
  if (type === "alert_detected") {
    active[stateKey] = { ...alert, state: "active", started_at: previous?.started_at ?? time, updated_at: time };
    delete recent[stateKey];
  } else {
    recent[stateKey] = { ...alert, state: "recovered", started_at: previous?.started_at ?? time, recovered_at: time, updated_at: time };
    delete active[stateKey];
  }
}

export function materializeProjectedStreamStates(streams: JsonRecord, time: number) {
  return normalizeStreamsLine(JSON.stringify({ time, streams: activeProjectedStreams(streams) })).map((item) => item.stream);
}

export function materializeProjectedStreams(streams: JsonRecord, time: number): StreamsSnapshot {
  const normalized = materializeProjectedStreamStates(streams, time).map((stream) => ({ stream }));
  const items = normalized.map((item) => ({
    ...item.stream,
    overview: { gap: 0, dup: 0, reorder: 0, events: 0, eventsAvailable: false },
    flows: item.stream.flows.map((flow) => ({
      flowKey: flow.flowKey,
      role: flow.role,
      label: flow.label,
      active: flow.active,
      interfaceId: flow.interfaceId,
      interfaceName: flow.interfaceName,
      endpointSrc: flow.endpointSrc,
      endpointDst: flow.endpointDst,
      protocolDetails: flow.protocolDetails,
      lastSeen: flow.lastSeen,
      ...(flow.alert ? { alert: flow.alert } : {}),
      ...(flow.recentAlert ? { recentAlert: flow.recentAlert } : {}),
      bitrate: flow.metrics.bitrate ?? {},
      sparkline: [],
      overview: { gap: 0, dup: 0, reorder: 0, events: 0, eventsAvailable: false }
    }))
  } satisfies StreamListItem));
  return { time, streams: items, interfaces: [] };
}

export function enrichProjectedStreamSnapshot(
  snapshot: StreamsSnapshot,
  interfaces: NormalizedInterfaceInput[],
  metrics: NormalizedMetricInput[],
  streamsErrorCountMode = 0
): StreamsSnapshot {
  const interfaceItems: InterfaceListItem[] = interfaces.map(({ hasMetrics: _hasMetrics, ...item }) => ({ ...item, streamCount: 0 }));
  const interfaceNames = new Map(interfaceItems.filter((item) => item.interfaceId !== undefined).map((item) => [item.interfaceId!, item.name]));
  const metricsByFlow = new Map(metrics.map((metric) => [metric.flowKey, metric]));
  const streams = snapshot.streams.map((stream) => {
    const flows = stream.flows.map((flow) => {
      const metric = metricsByFlow.get(flow.flowKey);
      const interfaceName = flow.interfaceName ?? (flow.interfaceId !== undefined ? interfaceNames.get(flow.interfaceId) : undefined);
      return {
        ...flow,
        interfaceName,
        // Lifecycle records identify the flow but do not carry the target
        // classification.  The co-timed metric record is authoritative for
        // that classification and is needed by the client to resolve target
        // specific alert-policy overrides when drawing threshold lines.
        monitoringTargetIds: metric?.monitoringTargetIds ?? flow.monitoringTargetIds,
        bitrate: metric?.metrics.bitrate ?? flow.bitrate,
        overview: overviewFromMetric(metric, streamsErrorCountMode)
      };
    });
    const interfaceName = stream.interfaceName ?? (stream.interfaceId !== undefined ? interfaceNames.get(stream.interfaceId) : undefined);
    return {
      ...stream,
      interfaceName,
      flows,
      flowCount: flows.length,
      bitrate: sumBitrate(flows.map((flow) => flow.bitrate)),
      overview: sumOverview(flows.map((flow) => flow.overview))
    };
  });
  const streamCounts = new Map<number, number>();
  for (const stream of streams) {
    if (stream.interfaceId !== undefined) {
      streamCounts.set(stream.interfaceId, (streamCounts.get(stream.interfaceId) ?? 0) + 1);
    }
  }
  return {
    ...snapshot,
    interfaces: interfaceItems.map((item) => ({ ...item, streamCount: item.interfaceId !== undefined ? streamCounts.get(item.interfaceId) ?? 0 : 0 })),
    streams
  };
}

export function enrichProjectedStreamEventOverview(
  snapshot: StreamsSnapshot,
  counts: OverviewEventCounts,
  eventsAvailable: boolean
): StreamsSnapshot {
  return {
    ...snapshot,
    streams: snapshot.streams.map((stream) => {
      const streamOnlyEvents = counts.streamOnly.get(stream.streamKey) ?? 0;
      const flows = stream.flows.map((flow) => ({
        ...flow,
        overview: {
          ...flow.overview,
          events: eventsAvailable ? (counts.flows.get(flow.flowKey) ?? 0) + streamOnlyEvents : 0,
          eventsAvailable
        }
      }));
      return {
        ...stream,
        flows,
        overview: {
          ...stream.overview,
          events: eventsAvailable ? counts.streams.get(stream.streamKey) ?? 0 : 0,
          eventsAvailable
        }
      };
    })
  };
}

function overviewFromMetric(metric: NormalizedMetricInput | undefined, streamsErrorCountMode: number): OverviewStats {
  return {
    gap: counterValue(metric?.metrics["seq_stats.gap"], streamsErrorCountMode),
    dup: counterValue(metric?.metrics["seq_stats.dup"], streamsErrorCountMode),
    reorder: counterValue(metric?.metrics["seq_stats.reorder"], streamsErrorCountMode),
    events: 0,
    eventsAvailable: false
  };
}

function sumOverview(stats: OverviewStats[]): OverviewStats {
  return {
    gap: stats.reduce((sum, item) => sum + item.gap, 0),
    dup: stats.reduce((sum, item) => sum + item.dup, 0),
    reorder: stats.reduce((sum, item) => sum + item.reorder, 0),
    events: 0,
    eventsAvailable: false
  };
}

function counterValue(stat: NumericStat | undefined, mode: number) {
  const value = mode === 1 ? stat?.count : stat?.value ?? stat?.avg ?? stat?.count;
  return Math.max(0, Math.round(value ?? 0));
}

function sumBitrate(stats: NumericStat[]): NumericStat {
  const total = (field: keyof NumericStat) => stats
    .map((stat) => stat[field])
    .filter((value): value is number => typeof value === "number" && Number.isFinite(value))
    .reduce((sum, value) => sum + value, 0);
  return { value: total("value"), avg: total("avg"), min: total("min"), max: total("max"), count: total("count") };
}

export function activeProjectedStreams(streams: JsonRecord) {
  return Object.entries(streams)
    .filter(([, stream]) => isRecord(stream) && stream.active === true)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([, source]) => {
      const stream: JsonRecord = {};
      for (const field of ["stream_key", "name", "interface_id", "scope", "vlan", "endpoint", "first_seen", "last_seen", "alerts", "recent_alerts"]) {
        if (source[field] !== undefined) stream[field] = source[field];
      }
      stream.flows = Object.entries(isRecord(source.flows) ? source.flows : {})
        .filter(([, flow]) => isRecord(flow) && flow.active === true)
        .sort(([a], [b]) => a.localeCompare(b))
        .map(([, sourceFlow]) => {
          const activeFlow = isRecord(sourceFlow) ? sourceFlow : {};
          const flow: JsonRecord = {};
          for (const field of ["flow_key", "interface_id", "scope", "vlan", "endpoint", "role", "first_seen", "last_seen", "alerts", "recent_alerts"]) {
            if (activeFlow[field] !== undefined) flow[field] = activeFlow[field];
          }
          return flow;
        });
      return { proto: stringValue(source.proto), stream };
    });
}

async function findLatestCheckpoint(root: string, time: number): Promise<JsonRecord | undefined> {
  let latest: JsonRecord | undefined;
  let latestTime = Number.NEGATIVE_INFINITY;
  for (const file of listFiles(root, (name) => name.endsWith(".json"))) {
    try {
      const entry = JSON.parse(await import("node:fs/promises").then(({ readFile }) => readFile(file, "utf8"))) as JsonRecord;
      const entryTime = Number(entry.time ?? 0);
      if (Number.isFinite(entryTime) && entryTime <= time && entryTime >= latestTime) {
        latest = entry;
        latestTime = entryTime;
      }
    } catch {
      // A partially written checkpoint is ignored.
    }
  }
import { createReadStream, existsSync, readdirSync, readFileSync } from "node:fs";
import path from "node:path";
import readline from "node:readline";
import { config } from "../config";
import { normalizeTimelineLine, type NormalizedTimelineInput } from "../normalizer";
import type { TimelineRow, TimelineViewResponse, TimelineWindow } from "../types";
import { queryLatestTimelineAvailabilityAtOrBefore, queryTimelineDataGaps } from "./timeline_availability_query";

type QueryOptions = {
  from: number;
  to: number;
  includeFlows?: boolean;
};

type TimelineCheckpoint = {
  time: number;
  rows: Map<string, TimelineRow>;
};

export async function queryTimelineHistory(options: QueryOptions): Promise<TimelineViewResponse> {
  const eventAvailable = getTimelineAvailableWindow();
  const latestAvailability = await queryLatestTimelineAvailabilityAtOrBefore(options.to);
  const available = eventAvailable
    ? { ...eventAvailable, to: Math.max(eventAvailable.to, latestAvailability ?? Number.NEGATIVE_INFINITY) }
    : { from: options.from, to: options.to };
  const gaps = await queryTimelineDataGaps({ from: options.from, to: options.to });
  const checkpoint = loadLatestTimelineCheckpoint(options.from, options.includeFlows ?? true);
  const seedFrom = Math.max(0, checkpoint?.time ?? available.from);
  const files = listTimelineFiles(seedFrom, options.to);
  const rows = checkpoint?.rows ?? new Map<string, TimelineRow>();

  for (const file of files) {
    await readTimelineFile(file, (item) => {
      if (item.time < seedFrom) return;
      if (item.time > options.to) return;
      if (!options.includeFlows && item.subjectType === "flow") return;
      applyTimelineEvent(rows, item);
    });
  }

  const clipped = [...rows.values()]
    .map((row) => clipTimelineRow(row, options.from, options.to))
    .filter((row): row is TimelineRow => row !== undefined);

  const streamByKey = new Map<string, TimelineRow>();
  for (const row of clipped) {
    if (row.rowType === "stream") streamByKey.set(row.streamKey, row);
  }

  for (const row of clipped) {
    if (row.rowType !== "flow" || !row.parentStreamKey) continue;
    if (streamByKey.has(row.parentStreamKey)) continue;
    const originalParent = rows.get(row.parentStreamKey);
    if (!originalParent) continue;
    const fallback: TimelineRow = {
      ...originalParent,
      rowType: "stream",
      flowKey: undefined,
      parentStreamKey: undefined,
      active: row.active,
      firstSeen: row.firstSeen,
      lastSeen: row.lastSeen,
      // stream自体の帯が範囲外でも、flowが見えている間は親ラベル行を残す
      segments: []
    };
    clipped.push(fallback);
    streamByKey.set(fallback.streamKey, fallback);
  }

  const timelineRows = clipped.sort((a, b) => {
      if (a.interfaceId !== undefined || b.interfaceId !== undefined) {
        if (a.interfaceId === undefined) return 1;
        if (b.interfaceId === undefined) return -1;
        if (a.interfaceId !== b.interfaceId) return a.interfaceId - b.interfaceId;
      }
      const parentA = a.parentStreamKey ?? a.streamKey;
      const parentB = b.parentStreamKey ?? b.streamKey;
      if (parentA !== parentB) return parentA.localeCompare(parentB);
      if (a.rowType !== b.rowType) return a.rowType === "stream" ? -1 : 1;
      return (a.flowKey ?? a.streamKey).localeCompare(b.flowKey ?? b.streamKey);
    });

  return {
    rows: timelineRows,
    gaps,
    window: { from: options.from, to: options.to },
    available,
    source: "history"
  };
}

function loadLatestTimelineCheckpoint(from: number, includeFlows: boolean): TimelineCheckpoint | undefined {
  const checkpointRoot = config.timelineCheckpointDir;
  if (!existsSync(checkpointRoot)) return undefined;

  const dayDirs = readdirSync(checkpointRoot, { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && /^\d{8}$/.test(entry.name))
    .map((entry) => entry.name)
    .sort();
  if (dayDirs.length === 0) return undefined;

  const candidates: Array<{ ts: number; file: string }> = [];
  for (const dayDir of dayDirs) {
    const year = Number(dayDir.slice(0, 4));
    const month = Number(dayDir.slice(4, 6)) - 1;
    const day = Number(dayDir.slice(6, 8));
    const dirPath = path.join(checkpointRoot, dayDir);
    const files = readdirSync(dirPath, { withFileTypes: true })
      .filter((entry) => entry.isFile() && /^\d{4}\.json$/.test(entry.name))
      .map((entry) => entry.name);
    for (const fileName of files) {
      const hour = Number(fileName.slice(0, 2));
      const minute = Number(fileName.slice(2, 4));
      const ts = Date.UTC(year, month, day, hour, minute, 0) / 1000;
      if (ts <= from) {
        candidates.push({ ts, file: path.join(dirPath, fileName) });
      }
    }
  }

  if (candidates.length === 0) return undefined;
  candidates.sort((a, b) => b.ts - a.ts);
  const selected = candidates[0];

  try {
    const text = readFileSync(selected.file, "utf8").trim();
    if (!text) return undefined;
    const parsed = JSON.parse(text) as {
      time?: number;
      active_rows?: Array<{
        key?: string;
        type?: string;
        stream_key?: string;
        flow_key?: string;
        proto?: string;
        role?: string;
        label?: string;
        interface_id?: number | null;
        first_seen?: number;
        last_seen?: number;
        subject?: Record<string, unknown>;
      }>;
    };
    const rows = new Map<string, TimelineRow>();
    const snapshotTime = Number.isFinite(parsed.time) ? Number(parsed.time) : selected.ts;
    for (const item of parsed.active_rows ?? []) {
      const rowType = item.type === "flow" ? "flow" : "stream";
      if (!includeFlows && rowType === "flow") continue;
      const streamKey = item.stream_key ?? "";
      if (!streamKey) continue;
      const flowKey = item.flow_key ?? undefined;
      const key = item.key ?? (rowType === "flow" ? `${streamKey}::${flowKey ?? ""}` : streamKey);
      const subject = item.subject ?? {};
      const interfaceIdRaw = typeof item.interface_id === "number" ? item.interface_id : undefined;
      const normalized = normalizeTimelineLine(JSON.stringify({
        time: snapshotTime,
        kind: rowType === "flow" ? "flow_detected" : "stream_detected",
        subject
      }));

      const row: TimelineRow = {
        rowType,
        streamKey,
        flowKey,
        parentStreamKey: rowType === "flow" ? streamKey : undefined,
        kind: normalized?.proto ?? item.proto ?? "",
        proto: normalized?.proto ?? item.proto ?? "",
        label: normalized?.label ?? item.label ?? streamKey,
        role: normalized?.role ?? item.role ?? undefined,
        endpointSrc: normalized?.endpointSrc ?? readEndpoint(subject, "src"),
        endpointDst: normalized?.endpointDst ?? readEndpoint(subject, "dst"),
        interfaceId: normalized?.interfaceId ?? interfaceIdRaw,
        interfaceName: normalized?.interfaceName,
        scope: normalized?.scope,
        active: true,
        firstSeen: Number.isFinite(item.first_seen) ? Number(item.first_seen) : snapshotTime,
        lastSeen: Number.isFinite(item.last_seen) ? Number(item.last_seen) : snapshotTime,
        segments: [{ start: Math.min(from, snapshotTime), end: null }]
      };
      rows.set(key, row);
    }
    return { time: selected.ts, rows };
  } catch {
    return undefined;
  }
}

function readEndpoint(subject: Record<string, unknown>, field: "src" | "dst") {
  const endpoint = subject.endpoint;
  if (!endpoint || typeof endpoint !== "object") return undefined;
  const value = (endpoint as Record<string, unknown>)[field];
  return typeof value === "string" ? value : undefined;
}

function timelineKey(input: NormalizedTimelineInput) {
  return input.subjectType === "flow" ? `${input.streamKey}::${input.flowKey ?? ""}` : input.streamKey;
}

function ensureTimelineRow(rows: Map<string, TimelineRow>, input: NormalizedTimelineInput) {
  const key = timelineKey(input);
  const existing = rows.get(key);
  if (existing) {
    existing.interfaceId = input.interfaceId ?? existing.interfaceId;
    existing.interfaceName = input.interfaceName ?? existing.interfaceName;
    existing.kind = input.proto;
    existing.proto = input.proto;
    existing.label = input.label || existing.label;
    existing.role = input.role ?? existing.role;
    existing.endpointSrc = input.endpointSrc ?? existing.endpointSrc;
    existing.endpointDst = input.endpointDst ?? existing.endpointDst;
    existing.scope = input.scope.known ? input.scope : existing.scope;
    return existing;
  }

  const created: TimelineRow = {
    rowType: input.subjectType === "flow" ? "flow" : "stream",
    streamKey: input.streamKey,
    flowKey: input.flowKey,
    parentStreamKey: input.subjectType === "flow" ? input.streamKey : undefined,
    kind: input.proto,
    proto: input.proto,
    label: input.label,
    role: input.role,
    endpointSrc: input.endpointSrc,
    endpointDst: input.endpointDst,
    interfaceId: input.interfaceId,
    interfaceName: input.interfaceName,
    scope: input.scope,
    active: false,
    firstSeen: input.time,
    lastSeen: input.time,
    segments: []
  };
  rows.set(key, created);
  return created;
}

function applyTimelineEvent(rows: Map<string, TimelineRow>, input: NormalizedTimelineInput) {
  if (input.kind === "stream_reclassified" || input.kind === "flow_reclassified") {
    rows.delete(timelineKey(input));
    return;
  }
  const row = ensureTimelineRow(rows, input);
  row.firstSeen = Math.min(row.firstSeen, input.time);
  row.lastSeen = Math.max(row.lastSeen, input.time);

  if (input.kind === "stream_detected" || input.kind === "stream_recovered" || input.kind === "flow_detected" || input.kind === "flow_recovered") {
    row.active = true;
    const current = row.segments[row.segments.length - 1];
    if (!current || current.end !== null) {
      row.segments.push({ start: input.time, end: null });
    }
    return;
  }

  if (input.kind === "stream_lost" || input.kind === "flow_lost") {
    row.active = false;
    const current = row.segments[row.segments.length - 1];
    if (current && current.end === null) {
