export function materializeProjectedStreamStates(streams: JsonRecord, time: number) {
  return normalizeStreamsLine(JSON.stringify({ time, streams: activeProjectedStreams(streams) })).map((item) => item.stream);
}

export function materializeProjectedStreams(streams: JsonRecord, time: number): StreamsSnapshot {
  const normalized = materializeProjectedStreamStates(streams, time).map((stream) => ({ stream }));
  const items = normalized.map((item) => ({
    ...item.stream,
    overview: { gap: 0, dup: 0, reorder: 0, events: 0, eventsAvailable: false },
    flows: item.stream.flows.map((flow) => ({
      flowKey: flow.flowKey,
      role: flow.role,
      label: flow.label,
      active: flow.active,
      interfaceId: flow.interfaceId,
      interfaceName: flow.interfaceName,
      endpointSrc: flow.endpointSrc,
      endpointDst: flow.endpointDst,
      protocolDetails: flow.protocolDetails,
      lastSeen: flow.lastSeen,
      ...(flow.alert ? { alert: flow.alert } : {}),
      ...(flow.recentAlert ? { recentAlert: flow.recentAlert } : {}),
      bitrate: flow.metrics.bitrate ?? {},
      sparkline: [],
      overview: { gap: 0, dup: 0, reorder: 0, events: 0, eventsAvailable: false }
    }))
  } satisfies StreamListItem));
  return { time, streams: items, interfaces: [] };
}

export function enrichProjectedStreamSnapshot(
  snapshot: StreamsSnapshot,
  interfaces: NormalizedInterfaceInput[],
  metrics: NormalizedMetricInput[],
  streamsErrorCountMode = 0
): StreamsSnapshot {
  const interfaceItems: InterfaceListItem[] = interfaces.map(({ hasMetrics: _hasMetrics, ...item }) => ({ ...item, streamCount: 0 }));
  const interfaceNames = new Map(interfaceItems.filter((item) => item.interfaceId !== undefined).map((item) => [item.interfaceId!, item.name]));
  const metricsByFlow = new Map(metrics.map((metric) => [metric.flowKey, metric]));
  const streams = snapshot.streams.map((stream) => {
    const flows = stream.flows.map((flow) => {
      const metric = metricsByFlow.get(flow.flowKey);
      const interfaceName = flow.interfaceName ?? (flow.interfaceId !== undefined ? interfaceNames.get(flow.interfaceId) : undefined);
      return {
        ...flow,
        interfaceName,
        // Lifecycle records identify the flow but do not carry the target
        // classification.  The co-timed metric record is authoritative for
        // that classification and is needed by the client to resolve target
        // specific alert-policy overrides when drawing threshold lines.
        monitoringTargetIds: metric?.monitoringTargetIds ?? flow.monitoringTargetIds,
        bitrate: metric?.metrics.bitrate ?? flow.bitrate,
        overview: overviewFromMetric(metric, streamsErrorCountMode)
      };
    });
    const interfaceName = stream.interfaceName ?? (stream.interfaceId !== undefined ? interfaceNames.get(stream.interfaceId) : undefined);
    return {
      ...stream,
      interfaceName,
      flows,
      flowCount: flows.length,
      bitrate: sumBitrate(flows.map((flow) => flow.bitrate)),
      overview: sumOverview(flows.map((flow) => flow.overview))
    };
  });
  const streamCounts = new Map<number, number>();
  for (const stream of streams) {
    if (stream.interfaceId !== undefined) {
      streamCounts.set(stream.interfaceId, (streamCounts.get(stream.interfaceId) ?? 0) + 1);
    }
  }
  return {
    ...snapshot,
    interfaces: interfaceItems.map((item) => ({ ...item, streamCount: item.interfaceId !== undefined ? streamCounts.get(item.interfaceId) ?? 0 : 0 })),
    streams
  };
}

export function enrichProjectedStreamEventOverview(
  snapshot: StreamsSnapshot,
  counts: OverviewEventCounts,
  eventsAvailable: boolean
): StreamsSnapshot {
  return {
    ...snapshot,
    streams: snapshot.streams.map((stream) => {
      const streamOnlyEvents = counts.streamOnly.get(stream.streamKey) ?? 0;
      const flows = stream.flows.map((flow) => ({
        ...flow,
        overview: {
          ...flow.overview,
          events: eventsAvailable ? (counts.flows.get(flow.flowKey) ?? 0) + streamOnlyEvents : 0,
          eventsAvailable
        }
      }));
      return {
        ...stream,
        flows,
        overview: {
          ...stream.overview,
          events: eventsAvailable ? counts.streams.get(stream.streamKey) ?? 0 : 0,
          eventsAvailable
        }
      };
    })
  };
}

function overviewFromMetric(metric: NormalizedMetricInput | undefined, streamsErrorCountMode: number): OverviewStats {
  return {
    gap: counterValue(metric?.metrics["seq_stats.gap"], streamsErrorCountMode),
    dup: counterValue(metric?.metrics["seq_stats.dup"], streamsErrorCountMode),
    reorder: counterValue(metric?.metrics["seq_stats.reorder"], streamsErrorCountMode),
    events: 0,
    eventsAvailable: false
  };
}

function sumOverview(stats: OverviewStats[]): OverviewStats {
  return {
    gap: stats.reduce((sum, item) => sum + item.gap, 0),
    dup: stats.reduce((sum, item) => sum + item.dup, 0),
    reorder: stats.reduce((sum, item) => sum + item.reorder, 0),
    events: 0,
    eventsAvailable: false
  };
}

function counterValue(stat: NumericStat | undefined, mode: number) {
  const value = mode === 1 ? stat?.count : stat?.value ?? stat?.avg ?? stat?.count;
  return Math.max(0, Math.round(value ?? 0));
}

function sumBitrate(stats: NumericStat[]): NumericStat {
  const total = (field: keyof NumericStat) => stats
    .map((stat) => stat[field])
    .filter((value): value is number => typeof value === "number" && Number.isFinite(value))
    .reduce((sum, value) => sum + value, 0);
  return { value: total("value"), avg: total("avg"), min: total("min"), max: total("max"), count: total("count") };
}

export function activeProjectedStreams(streams: JsonRecord) {
  return Object.entries(streams)
    .filter(([, stream]) => isRecord(stream) && stream.active === true)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([, source]) => {
      const stream: JsonRecord = {};
      for (const field of ["stream_key", "name", "interface_id", "scope", "vlan", "endpoint", "first_seen", "last_seen", "alerts", "recent_alerts"]) {
        if (source[field] !== undefined) stream[field] = source[field];
      }
      stream.flows = Object.entries(isRecord(source.flows) ? source.flows : {})
        .filter(([, flow]) => isRecord(flow) && flow.active === true)
        .sort(([a], [b]) => a.localeCompare(b))
        .map(([, sourceFlow]) => {
          const activeFlow = isRecord(sourceFlow) ? sourceFlow : {};
          const flow: JsonRecord = {};
          for (const field of ["flow_key", "interface_id", "scope", "vlan", "endpoint", "role", "first_seen", "last_seen", "alerts", "recent_alerts"]) {
            if (activeFlow[field] !== undefined) flow[field] = activeFlow[field];
          }
          return flow;
        });
      return { proto: stringValue(source.proto), stream };
    });
}

async function findLatestCheckpoint(root: string, time: number): Promise<JsonRecord | undefined> {
  let latest: JsonRecord | undefined;
  let latestTime = Number.NEGATIVE_INFINITY;
  for (const file of listFiles(root, (name) => name.endsWith(".json"))) {
    try {
      const entry = JSON.parse(await import("node:fs/promises").then(({ readFile }) => readFile(file, "utf8"))) as JsonRecord;
      const entryTime = Number(entry.time ?? 0);
      if (Number.isFinite(entryTime) && entryTime <= time && entryTime >= latestTime) {
        latest = entry;
        latestTime = entryTime;
      }
    } catch {
      // A partially written checkpoint is ignored.
    }
  }
import { createReadStream, existsSync, readdirSync, readFileSync } from "node:fs";
import path from "node:path";
import readline from "node:readline";
import { config } from "../config";
import { normalizeTimelineLine, type NormalizedTimelineInput } from "../normalizer";
import type { TimelineRow, TimelineViewResponse, TimelineWindow } from "../types";
import { queryLatestTimelineAvailabilityAtOrBefore, queryTimelineDataGaps } from "./timeline_availability_query";

type QueryOptions = {
  from: number;
  to: number;
  includeFlows?: boolean;
};

type TimelineCheckpoint = {
  time: number;
  rows: Map<string, TimelineRow>;
};

export async function queryTimelineHistory(options: QueryOptions): Promise<TimelineViewResponse> {
  const eventAvailable = getTimelineAvailableWindow();
  const latestAvailability = await queryLatestTimelineAvailabilityAtOrBefore(options.to);
  const available = eventAvailable
    ? { ...eventAvailable, to: Math.max(eventAvailable.to, latestAvailability ?? Number.NEGATIVE_INFINITY) }
    : { from: options.from, to: options.to };
  const gaps = await queryTimelineDataGaps({ from: options.from, to: options.to });
  const checkpoint = loadLatestTimelineCheckpoint(options.from, options.includeFlows ?? true);
  const seedFrom = Math.max(0, checkpoint?.time ?? available.from);
  const files = listTimelineFiles(seedFrom, options.to);
  const rows = checkpoint?.rows ?? new Map<string, TimelineRow>();

  for (const file of files) {
    await readTimelineFile(file, (item) => {
      if (item.time < seedFrom) return;
      if (item.time > options.to) return;
      if (!options.includeFlows && item.subjectType === "flow") return;
      applyTimelineEvent(rows, item);
    });
  }

  const clipped = [...rows.values()]
    .map((row) => clipTimelineRow(row, options.from, options.to))
    .filter((row): row is TimelineRow => row !== undefined);

  const streamByKey = new Map<string, TimelineRow>();
  for (const row of clipped) {
    if (row.rowType === "stream") streamByKey.set(row.streamKey, row);
  }

  for (const row of clipped) {
    if (row.rowType !== "flow" || !row.parentStreamKey) continue;
    if (streamByKey.has(row.parentStreamKey)) continue;
    const originalParent = rows.get(row.parentStreamKey);
    if (!originalParent) continue;
    const fallback: TimelineRow = {
      ...originalParent,
      rowType: "stream",
      flowKey: undefined,
      parentStreamKey: undefined,
      active: row.active,
      firstSeen: row.firstSeen,
      lastSeen: row.lastSeen,
      // stream自体の帯が範囲外でも、flowが見えている間は親ラベル行を残す
      segments: []
    };
    clipped.push(fallback);
    streamByKey.set(fallback.streamKey, fallback);
  }

  const timelineRows = clipped.sort((a, b) => {
      if (a.interfaceId !== undefined || b.interfaceId !== undefined) {
        if (a.interfaceId === undefined) return 1;
        if (b.interfaceId === undefined) return -1;
        if (a.interfaceId !== b.interfaceId) return a.interfaceId - b.interfaceId;
      }
      const parentA = a.parentStreamKey ?? a.streamKey;
      const parentB = b.parentStreamKey ?? b.streamKey;
      if (parentA !== parentB) return parentA.localeCompare(parentB);
      if (a.rowType !== b.rowType) return a.rowType === "stream" ? -1 : 1;
      return (a.flowKey ?? a.streamKey).localeCompare(b.flowKey ?? b.streamKey);
    });

  return {
    rows: timelineRows,
    gaps,
    window: { from: options.from, to: options.to },
    available,
    source: "history"
  };
}

function loadLatestTimelineCheckpoint(from: number, includeFlows: boolean): TimelineCheckpoint | undefined {
  const checkpointRoot = config.timelineCheckpointDir;
  if (!existsSync(checkpointRoot)) return undefined;

  const dayDirs = readdirSync(checkpointRoot, { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && /^\d{8}$/.test(entry.name))
    .map((entry) => entry.name)
    .sort();
  if (dayDirs.length === 0) return undefined;

  const candidates: Array<{ ts: number; file: string }> = [];
  for (const dayDir of dayDirs) {
    const year = Number(dayDir.slice(0, 4));
    const month = Number(dayDir.slice(4, 6)) - 1;
    const day = Number(dayDir.slice(6, 8));
    const dirPath = path.join(checkpointRoot, dayDir);
    const files = readdirSync(dirPath, { withFileTypes: true })
      .filter((entry) => entry.isFile() && /^\d{4}\.json$/.test(entry.name))
      .map((entry) => entry.name);
    for (const fileName of files) {
      const hour = Number(fileName.slice(0, 2));
      const minute = Number(fileName.slice(2, 4));
      const ts = Date.UTC(year, month, day, hour, minute, 0) / 1000;
      if (ts <= from) {
        candidates.push({ ts, file: path.join(dirPath, fileName) });
      }
    }
  }

  if (candidates.length === 0) return undefined;
  candidates.sort((a, b) => b.ts - a.ts);
  const selected = candidates[0];

  try {
    const text = readFileSync(selected.file, "utf8").trim();
    if (!text) return undefined;
    const parsed = JSON.parse(text) as {
      time?: number;
      active_rows?: Array<{
        key?: string;
        type?: string;
        stream_key?: string;
        flow_key?: string;
        proto?: string;
        role?: string;
        label?: string;
        interface_id?: number | null;
        first_seen?: number;
        last_seen?: number;
        subject?: Record<string, unknown>;
      }>;
    };
    const rows = new Map<string, TimelineRow>();
    const snapshotTime = Number.isFinite(parsed.time) ? Number(parsed.time) : selected.ts;
    for (const item of parsed.active_rows ?? []) {
      const rowType = item.type === "flow" ? "flow" : "stream";
      if (!includeFlows && rowType === "flow") continue;
      const streamKey = item.stream_key ?? "";
      if (!streamKey) continue;
      const flowKey = item.flow_key ?? undefined;
      const key = item.key ?? (rowType === "flow" ? `${streamKey}::${flowKey ?? ""}` : streamKey);
      const subject = item.subject ?? {};
