			if(!state.response.payload_seen && state.response.status_code == 0) {
				state.response.status_code = 504;
				state.response.effective_status_code = 504;
				state.response.status_source = "timeout";
			}
			rc |= complete_deferred(conn_key, "tcp_fin");
		}
		else if(deferred_content_complete(state)) {
			rc |= complete_deferred(conn_key, "content_length");
		}
		rc |= flush_deferred(i.time_epoch);
		rc |= flush_pending_timeouts(i.time_epoch);
		return rc;
	}

	const auto hk = host_key(i.interface_id, i.host, i.port, i.vlan);
	const bool has_known_playlist = m_playlists_by_host.find(hk) != m_playlists_by_host.end();
	if(i.role == "other" && !has_known_playlist) {
		trace(4, "hls: ignore other request without playlist host=%s port=%u path=%s",
		      i.host.c_str(), static_cast<unsigned>(i.port), i.path.c_str());
		rc |= flush_deferred(i.time_epoch);
		rc |= flush_pending_timeouts(i.time_epoch);
		return rc;
	}
	const auto sid = resolve_stream_id(i);
	merge_monitoring_target_ids(m_monitoring_target_ids[sid], target_ids);
	if(!stream_name.empty()) {
		m_stream_display_names[sid] = stream_name;
		m_events.set_stream_display_name(sid.to_stream_key(), stream_name);
	}
	const auto fid = flow_id::from_request(i.interface_id, i.host, i.port, i.path, i.role, i.vlan);
	if(i.role == "playlist") {
		auto &playlists = m_playlists_by_host[hk];
		if(std::find(playlists.begin(), playlists.end(), i.path) == playlists.end()) {
			playlists.push_back(i.path);
			std::sort(playlists.begin(), playlists.end(), [](const auto &lhs, const auto &rhs) {
				return path_dir(lhs).size() > path_dir(rhs).size();
			});
		}
	}
	pending_request req{sid, fid, i.time_epoch};
	const std::string conn_key = connection_key(i);
	if(m_deferred_by_connection.find(conn_key) != m_deferred_by_connection.end()) {
		rc |= complete_deferred(conn_key, "next_request");
	}
	auto &queue = m_pending_by_connection[conn_key];
	queue.push_back(req);
	remember_connection_activity(conn_key, sid, fid);
	if(i.has_tcp_stream) {
		m_pending_by_tcp_stream[i.tcp_stream] = req;
	}
	trace(3, "hls: request registered method=%s role=%s path=%s conn=%s conn_pending=%zu has_tcp_stream=%d tcp_stream=%u stream=%s flow=%s",
	      i.method.c_str(),
	      i.role.c_str(),
	      i.path.c_str(),
	      conn_key.c_str(),
	      queue.size(),
	      i.has_tcp_stream ? 1 : 0,
	      static_cast<unsigned>(i.tcp_stream),
	      sid.to_stream_key().c_str(),
	      fid.to_flow_key(sid).c_str());

	rc |= process_resolved(sid, fid, i);
	rc |= flush_deferred(i.time_epoch);
	rc |= flush_pending_timeouts(i.time_epoch);
	return rc;
}

