std::string streams::connection_key(const info &i) const {
	std::string a = endpoint_key(i.src);
	std::string b = endpoint_key(i.dst);
	if(b < a) {
		std::swap(a, b);
	}
	std::ostringstream oss;
	oss << i.interface_id << tsv::key_suffix(i.vlan) << '|' << a << "<->" << b;
	return oss.str();
}

stream_id streams::resolve_stream_id(const info &i) const {
	std::string playlist = i.role == "playlist" ? i.path : std::string{};
	if(playlist.empty()) {
		const auto it = m_playlists_by_host.find(host_key(i.interface_id, i.host, i.port, i.vlan));
		std::size_t best_len = 0;
		if(it != m_playlists_by_host.end()) {
			for(const auto &candidate : it->second) {
				const auto dir = path_dir(candidate);
				if(!dir.empty() &&
				   i.path.rfind(dir, 0) == 0 &&
				   dir.size() > best_len) {
					playlist = candidate;
					best_len = dir.size();
				}
			}
			if(playlist.empty() && !it->second.empty()) {
				playlist = it->second.front();
			}
		}
		if(playlist.empty()) {
			playlist = unknown_playlist;
		}
	}
	return stream_id::from_playlist(i.interface_id, i.host, i.port, playlist, i.vlan);
}

bool streams::same_request(const pending_request &lhs, const pending_request &rhs) const {
	return lhs.sid == rhs.sid &&
	       lhs.fid == rhs.fid &&
	       lhs.request_time == rhs.request_time;
}

bool streams::pop_connection_pending(const std::string &conn_key, const pending_request &req) {
	auto conn = m_pending_by_connection.find(conn_key);
	if(conn == m_pending_by_connection.end() || conn->second.empty()) {
		return false;
	}
	if(!same_request(conn->second.front(), req)) {
		return false;
	}
	conn->second.pop_front();
	if(conn->second.empty()) {
		m_pending_by_connection.erase(conn);
	}
	return true;
}

void streams::erase_tcp_pending(const pending_request &req) {
	for(auto it = m_pending_by_tcp_stream.begin(); it != m_pending_by_tcp_stream.end(); ) {
		if(same_request(it->second, req)) {
			it = m_pending_by_tcp_stream.erase(it);
		}
		else {
			++it;
		}
	}
}

int streams::process_resolved(const stream_id &sid, const flow_id &fid, const info &i) {
	auto it = m_streams.find(sid);
	if(it == m_streams.end()) {
		it = m_streams.emplace(sid, std::make_unique<stream>(sid, i.interface_name, m_cfg, m_events)).first;
		it->second->emit_detected(i.time_epoch);
	}

	const int rc = it->second->process(i);
	expire_streams(i.time_epoch);
	return rc;
}

void streams::remember_connection_activity(const std::string &conn_key, const stream_id &sid, const flow_id &fid) {
	auto &targets = m_activity_by_connection[conn_key];
	const auto exists = std::find_if(targets.begin(), targets.end(), [&](const activity_target &target) {
		return target.sid == sid && target.fid == fid;
	});
	if(exists == targets.end()) {
		targets.push_back(activity_target{sid, fid});
	}
}

int streams::observe_connection_payload(const std::string &conn_key, const info &i) {
	const auto it = m_activity_by_connection.find(conn_key);
	if(it == m_activity_by_connection.end()) {
		return 0;
	}

	int rc = 0;
	for(const auto &target : it->second) {
		auto stream_it = m_streams.find(target.sid);
		if(stream_it == m_streams.end()) {
			stream_it = m_streams.emplace(target.sid, std::make_unique<stream>(target.sid, i.interface_name, m_cfg, m_events)).first;
			stream_it->second->emit_detected(i.time_epoch);
		}
		rc |= stream_it->second->observe_transport(target.fid, i);
	}
	expire_streams(i.time_epoch);
		append_monitoring_target_ids(out, first, m_monitoring_target_ids[sid]);
		append_stream_display_name(out, first, m_stream_display_names[sid]);
	}
	return 0;
}

int streams::update_events(double now) {
	flush_deferred(now);
	flush_pending_timeouts(now);
	expire_streams(now);
	for(auto& [sid, stream] : m_streams) {
		stream->update_events(now);
	}
	return 0;
}

int streams::append_list(double now, json::array_t &out) {
	flush_deferred(now);
	flush_pending_timeouts(now);
	for(auto& [sid, stream] : m_streams) {
		const auto first = out.size();
		stream->append_list(now, out);
		append_monitoring_target_ids(out, first, m_monitoring_target_ids[sid]);
		append_stream_display_name(out, first, m_stream_display_names[sid]);
	}
	return 0;
}

int streams::parse_row(tsv::ctx &c, const tsv::row_t &row, info &i) {
	tsv::to_number(row[c.i.com.time_epoch], i.time_epoch);
	tsv::to_number(row[c.i.com.interface_id], i.interface_id);
	tsv::to_string(row[c.i.com.interface_name], i.interface_name);
	i.frame_len = c.r.com.frame_len;
	tsv::to_number(row[c.i.com.frame_len], i.frame_len);
	i.vlan = tsv::vlan_info{
		.id = std::string(tsv::field_or_empty(row, c.i.com.vlan_id)),
		.priority = std::string(tsv::field_or_empty(row, c.i.com.vlan_priority)),
		.dei = std::string(tsv::field_or_empty(row, c.i.com.vlan_dei)),
	};

	parse_ip(tsv::field_or_empty(row, c.i.com.ip_src), tsv::field_or_empty(row, c.i.com.ipv6_src), i.src.addr);
	parse_ip(tsv::field_or_empty(row, c.i.com.ip_dst), tsv::field_or_empty(row, c.i.com.ipv6_dst), i.dst.addr);
	std::uint32_t port = 0;
	if(tsv::to_number(tsv::field_or_empty(row, c.i.com.tcp_srcport), port) && port <= 65535U) {
		i.src.port = static_cast<std::uint16_t>(port);
	}
	port = 0;
	if(tsv::to_number(tsv::field_or_empty(row, c.i.com.tcp_dstport), port) && port <= 65535U) {
		i.dst.port = static_cast<std::uint16_t>(port);
	}
	if(tsv::to_number(tsv::field_or_empty(row, c.i.com.tcp_stream), i.tcp_stream)) {
		i.has_tcp_stream = true;
	}
	if(tsv::to_number(tsv::field_or_empty(row, c.i.com.tcp_len), i.tcp_len) && i.tcp_len > 0) {
		i.has_tcp_payload = true;
		i.payload_seen = true;
	}
	std::uint32_t tcp_fin = 0;
	i.tcp_fin =
		tsv::to_number(tsv::field_or_empty(row, c.i.com.tcp_flags_fin), tcp_fin) &&
		tcp_fin != 0;

	i.method = std::string(tsv::field_or_empty(row, c.i.http.method));
	i.path = std::string(tsv::field_or_empty(row, c.i.http.uri));
	i.host = std::string(tsv::field_or_empty(row, c.i.http.host));
	i.is_request = !i.method.empty() && !i.path.empty();

	std::uint32_t status = 0;
	if(tsv::to_number(tsv::field_or_empty(row, c.i.http.status_code), status) && status <= 999U) {
		i.status_code = static_cast<std::uint16_t>(status);
		i.is_response = i.status_code > 0;
		if(i.is_response) {
			i.effective_status_code = i.status_code;
			i.status_source = "http_header";
		}
	}

	std::uint64_t len = 0;
	if(tsv::to_number(tsv::field_or_empty(row, c.i.http.content_length), len)) {
		i.http_content_length = len;
		i.has_http_content_length = true;
		if(i.is_response) {
			i.content_length = len;
			i.has_content_length = true;
		}
	}
	else if(i.has_tcp_payload) {
		i.content_length = i.tcp_len;
		i.has_content_length = true;
	}

	if(!i.is_request && !i.is_response && !i.has_tcp_payload && !i.tcp_fin) {
		return -1;
	}
	if(i.is_response || (!i.is_request && (i.has_tcp_payload || i.tcp_fin))) {
		return 0;
	}

	i.port = endpoint_port(i.dst, 80);
	parse_absolute_uri(i.host, i.port, i.path);
	if(i.host.empty()) {
		i.host = to_string(i.dst.addr);
	}
	split_host_port(i.host, i.port);
	i.role = classify_role(i.path);
	return 0;
}

void streams::expire_streams(double now) {
	for(auto it = m_streams.begin(); it != m_streams.end(); ) {
		it->second->expire_flows(now, m_cfg.timeout.flow_idle_sec);
		if(it->second->empty() && it->second->expired(now, m_cfg.timeout.stream_idle_sec)) {
			it->second->emit_lost(now);
			m_monitoring_target_ids.erase(it->first);
			m_stream_display_names.erase(it->first);
			it = m_streams.erase(it);
		}
		else {
			++it;
		}
	}
}

