void flow::update_observed_endpoints(const info &i) {
	if(i.is_request && i.src.port != 0 && i.dst.port != 0) {
		m_client_endpoint = endpoint_key(i.src);
		m_origin_endpoint = endpoint_key(i.dst);
	}
	else if(i.is_response && i.src.port != 0 && i.dst.port != 0) {
		m_client_endpoint = endpoint_key(i.dst);
		m_origin_endpoint = endpoint_key(i.src);
	}
}
	trace(3, "hls: segment_response emitted status=%u effective_status=%u source=%s inferred=%d path=%s response_time=%.6f bytes=%llu",
