std::string streams::host_key(std::uint32_t interface_id, std::string_view host, std::uint16_t port, const tsv::vlan_info &vlan) const {
	std::ostringstream oss;
	oss << interface_id << tsv::key_suffix(vlan) << '|' << host << ':' << port;
	return oss.str();
}

std::string streams::playback_key(const info &i) const {
	if(i.src.addr.empty() || i.host.empty()) return {};
	std::ostringstream oss;
	oss << i.interface_id << tsv::key_suffix(i.vlan)
	    << "|client=" << to_string(i.src.addr)
	    << "|origin=" << i.host << ":" << i.port;
	return oss.str();
}

json streams::resolve_stream_group(const info &i) {
	const std::string base = playback_key(i);
	if(base.empty()) return json::object();
	auto it = m_playbacks.find(base);
	const bool expired = it != m_playbacks.end() && (i.time_epoch - it->second.last_seen) >= m_cfg.timeout.stream_idle_sec;
	if(i.role == "playlist" && (it == m_playbacks.end() || expired)) {
		const std::string root = path_dir(i.path);
		if(root.empty()) return json::object();
		std::ostringstream key;
		key << "HLS-PLAYBACK|" << base << "|root=" << root
		    << "|generation=" << static_cast<long long>(i.time_epoch * 1000.0);
		playback_group group{};
		group.descriptor = json{{"key", key.str()}, {"type", "hls_playback"},
		                        {"label", i.host + " " + root}, {"confidence", "heuristic"}};
		group.last_seen = i.time_epoch;
		it = m_playbacks.insert_or_assign(base, std::move(group)).first;
	}
	if(it == m_playbacks.end()) return json::object();
	it->second.last_seen = i.time_epoch;
	return it->second.descriptor;
}

std::string streams::connection_key(const info &i) const {
	std::string a = endpoint_key(i.src);
	std::string b = endpoint_key(i.dst);
	if(b < a) {
		std::swap(a, b);
	}
	std::ostringstream oss;
	oss << i.interface_id << tsv::key_suffix(i.vlan) << '|' << a << "<->" << b;
	return oss.str();
}

stream_id streams::resolve_stream_id(const info &i) const {
	std::string playlist = i.role == "playlist" ? i.path : std::string{};
	if(playlist.empty()) {
		const auto it = m_playlists_by_host.find(host_key(i.interface_id, i.host, i.port, i.vlan));
		trace(4, "hls: ignore other request without playlist host=%s port=%u path=%s",
		      i.host.c_str(), static_cast<unsigned>(i.port), i.path.c_str());
		rc |= flush_deferred(i.time_epoch);
		rc |= flush_pending_timeouts(i.time_epoch);
		return rc;
	}
	const auto sid = resolve_stream_id(i);
	const json stream_group = resolve_stream_group(i);
	if(!stream_group.empty()) m_stream_groups[sid] = stream_group;
	merge_monitoring_target_ids(m_monitoring_target_ids[sid], target_ids);
	if(!stream_name.empty()) {
		m_stream_display_names[sid] = stream_name;
		m_events.set_stream_display_name(sid.to_stream_key(), stream_name);
	}
	return 0;
}

void streams::expire_streams(double now) {
	for(auto it = m_streams.begin(); it != m_streams.end(); ) {
		it->second->expire_flows(now, m_cfg.timeout.flow_idle_sec);
		if(it->second->empty() && it->second->expired(now, m_cfg.timeout.stream_idle_sec)) {
			it->second->emit_lost(now);
			m_monitoring_target_ids.erase(it->first);
			m_stream_display_names.erase(it->first);
			m_stream_groups.erase(it->first);
			it = m_streams.erase(it);
		}
		else {
			++it;
		}
	}
}
