#ifndef ENDPOINT_H
#define ENDPOINT_H

#include <array>
#include <cstdint>
#include <cstring>
#include <string>
#include <string_view>
#include <unordered_map>
#include <utility>
#include <arpa/inet.h>

inline void hash_combine(std::size_t& seed, std::size_t v) {
    seed ^= v + 0x9e3779b97f4a7c15ULL + (seed << 6) + (seed >> 2);
}

struct ip_addr {
    bool is_v6{false};
    std::array<std::uint8_t, 16> bytes{};

    bool operator==(const ip_addr&) const = default;
};

inline bool operator<(const ip_addr& a, const ip_addr& b) noexcept {
    if (a.is_v6 != b.is_v6) return a.is_v6 < b.is_v6;
    const std::size_t n = a.is_v6 ? 16 : 4;
    return std::memcmp(a.bytes.data(), b.bytes.data(), n) < 0;
}

struct ip_addr_hash {
    std::size_t operator()(const ip_addr& ip) const noexcept {
        std::size_t h = 0;
        hash_combine(h, std::hash<bool>{}(ip.is_v6));
        const std::size_t n = ip.is_v6 ? 16 : 4;
        for (std::size_t i = 0; i < n; ++i) {
            hash_combine(h, std::hash<std::uint8_t>{}(ip.bytes[i]));
        }
        return h;
    }
};

struct ip_endpoint {
	int append_list(double now, json::array_t &out);
	int update_events(double now);
	void expire_flows(double now, double flow_idle_sec);
	bool empty() const { return m_flows.empty(); }
	void emit_detected(double now);
	void emit_lost(double now);

private:
	stream_id m_sid;
	std::string m_stream_key;
	std::string m_interface_name;
	config m_cfg;
	hls_metrics m_metrics;
	std::unordered_map<flow_id, std::unique_ptr<flow>, flow_id_hash> m_flows;
	json m_event_source;
	json m_stream_group;
	event_sink &m_events;
	event_state m_playlist_stall_state;
	bool m_has_playlist{false};
	double m_playlist_last_seen{0.0};

	flow_id resolve_flow_id(const info &i) const;
	event_record make_event(double now, std::string type, json detail = json::object()) const;
};
	return oss.str();
}

std::string streams::playback_key(const info &i) const {
	if(to_string(i.src.addr).empty() || i.host.empty()) return {};
	std::ostringstream oss;
	oss << i.interface_id << tsv::key_suffix(i.vlan)
	    << "|client=" << to_string(i.src.addr)
	    << "|origin=" << i.host << ":" << i.port;

