  const grouped = new Map<string, StreamDisplayGroup>();
  const ungrouped: StreamDisplayGroup[] = [];
  for (const stream of streams) {
    const descriptor = stream.streamGroup;
    if (!descriptor) {
      ungrouped.push({ key: `${parentKey}|stream:${stream.streamKey}`, label: stream.label, streams: [stream], grouped: false });
