50:export type TimelineRow = {
  tx: InterfaceCounters;
  rxRate?: InterfaceRateInfo;
  txRate?: InterfaceRateInfo;
  rxBitrate: NumericStat;
  txBitrate: NumericStat;
  rxSparkline: number[];
  txSparkline: number[];
  streamCount: number;
};

export type InterfaceMetricsResponse = {
  key: string;
  interfaceId?: number;
  name: string;
  windowSec: number;
  metrics: Record<string, TimeSeriesMetric>;
};

export type TimeSeriesMetric = {
  key: string;
  label: string;
  unit?: string;
  points: MetricPoint[];
};

export type FlowMetricsResponse = {
  flowKey: string;
  role: string;
  label: string;
  endpointSrc?: string;
  endpointDst?: string;
  monitoringTargetIds?: string[];
  metrics: Record<string, TimeSeriesMetric>;
};

export type StreamMetricsResponse = {
  streamKey: string;
  windowSec: number;
  streamBitrate: TimeSeriesMetric;
  flows: FlowMetricsResponse[];
  descriptors: MetricDescriptor[];
};

export type EventLogItem = {
  id: string;
  time: number;
  type: string;
  level: "info" | "warn" | "error";
  scope: "system" | "stream" | "flow";
  proto?: string;
  interfaceId?: number;
  streamKey?: string;
  flowKey?: string;
  targetLabel?: string;
  message: string;
  detail?: unknown;
};

export type TopologyAlertSummary = {
  state?: string;
  severity?: string;
  count?: number;
  alerts?: unknown[];
};

export type TopologyNode = {
  id: string;
  type: string;
  label?: string;
  host?: string;
  port?: number;
  transport?: string;
  state?: "active" | "stale";
  first_seen?: number;
  last_seen?: number;
  alert?: TopologyAlertSummary;
              key={`${group.key}:${index}:${segment.start}`}
              className={`timeline-segment timeline-segment-interface${group.active && (segment.end ?? range.end) >= range.end ? " active" : ""}`}
              style={{
                left: `${start}%`,
                width: `${Math.max(0.6, end - start)}%`
              }}
