function TimelineLane({
  rowKey,
  row,
  range,
  gaps,
  cursorPercent,
  cursorSec,
  fadeSec,
  isHovered,
  onHoverChange,
  childCount = 0,
  expanded = true,
  onToggle,
  eventBuckets,
  selectedEventId,
  activeBucketEventIds,
  previewedEventId,
  onSelectEvent
}: {
  rowKey: string;
  row: TimelineRow;
  range: { start: number; end: number };
  cursorPercent: number;
  gaps: TimelineDataGap[];
  cursorSec: number;
  fadeSec: number;
  isHovered: boolean;
  onHoverChange: (key: string | null) => void;
  childCount?: number;
  expanded?: boolean;
  onToggle?: () => void;
  eventBuckets: EventMarkerBucket[];
  selectedEventId: string | null;
  activeBucketEventIds: ReadonlySet<string>;
  previewedEventId: string | null;
  onSelectEvent: (bucket: EventMarkerBucket) => void;
}) {
  const focused = row.segments.some((segment) => {
    const end = segment.end ?? range.end;
    return cursorSec >= segment.start && cursorSec <= end;
  });
  const focusClass = focused ? " timeline-row-cursor-focused" : isHovered ? " timeline-row-hovered" : "";

  return (
    <div
      className={`timeline-row ${row.rowType === "flow" ? "timeline-row-flow" : "timeline-row-stream"}${focusClass}`}
      onPointerEnter={() => onHoverChange(rowKey)}
      onPointerLeave={() => onHoverChange(null)}
    >
      <div className="timeline-row-label" title={row.flowKey ?? row.streamKey}>
        <strong>
          {onToggle ? (
            <button type="button" className={"timeline-toggle" + (expanded ? " open" : "")} onClick={(event) => { event.stopPropagation(); onToggle(); }} aria-label={expanded ? "Collapse flow rows" : "Expand flow rows"}>
              <Icon name="expand" size={15} />
            </button>
          ) : (
            <span className="timeline-leaf-marker" aria-hidden="true" />
          )}
          <span className="timeline-label-text">{timelineRowLabel(row)}</span>
          {childCount > 0 && row.rowType === "stream" ? <TimelineCountBadge count={childCount} /> : null}
        </strong>
      </div>
      <div className="timeline-row-track">
