import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import type { FlowListItem, InterfaceListItem, ProtocolDetail, StreamAlertSummary, StreamListItem } from "../types/api";
import { alertCountsForStreams, alertTargetsForStreams, visibleRecentAlert, type AlertCounts } from "./alertTargets";
import { Sparkline } from "./Sparkline";
import { Icon } from "./ui/Icon";
import { formatAbsoluteDateTime, formatBitrate, formatFlowEndpoints, formatRelativeTime } from "./format";

type StreamTableProps = {
  streams: StreamListItem[];
  interfaces: InterfaceListItem[];
  selectedStreamKey: string | null;
  selectedFlowKey: string | null;
  selectedInterfaceKey: string | null;
  overviewMode?: boolean;
  expandLevel?: "interface" | "proto" | "stream" | "flow";
  onSelectInterface: (interfaceKey: string) => void;
  onSelectStream: (streamKey: string) => void;
  onSelectFlow: (streamKey: string, flowKey: string) => void;
  onAddToDashboard?: (streamKey: string, flowKey?: string) => void;
  timeTravel?: boolean;
  pickerMode?: boolean;
  showAlerts?: boolean;
  recentAlertRetentionMin?: number;
  referenceTimeSec?: number;
  dismissedRecent?: ReadonlySet<string>;
  onClearRecent?: () => void;
};

const TOTAL_COLOR = "var(--chart-rx)";
const FLOW_ROLE_COLORS: Record<string, string> = {
  media: "var(--chart-flow-media)",
  fec_row: "var(--chart-flow-fec-row)",
  fec_col: "var(--chart-flow-fec-col)",
  control: "var(--chart-flow-control)",
  mixed: "var(--chart-flow-mixed)",
  default: "var(--chart-flow-default)"
};
const FLOW_ROLE_LINE_COLORS: Record<string, string> = {
  media: "var(--chart-flow-media-line)",
  fec_row: "var(--chart-flow-fec-row-line)",
  fec_col: "var(--chart-flow-fec-col-line)",
  control: "var(--chart-flow-control-line)",
  mixed: "var(--chart-flow-mixed-line)",
  default: "var(--chart-flow-default-line)"
};
const DONUT_COLORS = ["var(--chart-rx)", "var(--chart-flow-media)", "var(--chart-flow-fec-col)", "var(--chart-flow-fec-row)", "var(--chart-flow-mixed)", "var(--chart-flow-default)"];
const ENABLE_FLIP_ANIMATION = false;
const ENABLE_SPARKLINES = true;
const ENABLE_OVERVIEW_STATS = true;
const ENABLE_OVERVIEW_CHARTS = false;
const MAX_STREAM_ROWS_PER_GROUP = 200;
const MAX_FLOW_ROWS_PER_STREAM = 80;
const STREAM_TABLE_OVERSCAN_PX = 600;
const STREAM_TABLE_ROW_HEIGHT = { interface: 48, scope: 48, proto: 48, stream: 48, group: 48, flow: 48, truncated: 32 };

type InterfaceGroup = {
  key: string;
  name: string;
  interfaceItem?: InterfaceListItem;
  streams: StreamListItem[];
};

type ScopeGroup = { key: string; label: string; streams: StreamListItem[] };
type StreamDisplayGroup = { key: string; label: string; confidence?: "confirmed" | "heuristic"; streams: StreamListItem[]; grouped: boolean };

type FlatRow =
  | { key: string; type: "interface"; height: number; group: InterfaceGroup }
  | { key: string; type: "scope"; height: number; group: ScopeGroup }
  | { key: string; type: "proto"; height: number; group: { key: string; proto: string; streams: StreamListItem[] } }
  | { key: string; type: "group"; height: number; group: StreamDisplayGroup }
  | { key: string; type: "stream"; height: number; stream: StreamListItem }
  | { key: string; type: "flow"; height: number; stream: StreamListItem; flow: FlowListItem }
  | { key: string; type: "truncated"; height: number; label: string; depth: "stream" | "flow" };


type TreeGuideData = {
  depth: number;
  ancestorDepths: number[];
  hasPreviousSibling: boolean;
  hasNextSibling: boolean;
};

type StickyContextItem = {
  kind: "interface" | "scope" | "proto" | "group" | "stream";
  label: string;
  proto?: string;
  title?: string;
};

type GuidedFlatRow = FlatRow & { treeGuide: TreeGuideData };

function treeDepth(row: FlatRow) {
  switch (row.type) {
    case "interface": return 0;
    case "scope": return 1;
    case "proto": return 2;
    case "group": return 3;
    case "stream": return 4;
    case "flow": return 5;
    case "truncated": return row.depth === "stream" ? 4 : 5;
  }
}

function withTreeGuides(rows: FlatRow[]): GuidedFlatRow[] {
  const depths = rows.map(treeDepth);
  const nextSibling = rows.map((_, index) => {
    const depth = depths[index];
    for (let next = index + 1; next < rows.length; next += 1) {
      if (depths[next] < depth) return false;
      if (depths[next] === depth) return true;
    }
    return false;
  });
  const ancestry: Array<{ key: string; depth: number; hasNextSibling: boolean } | undefined> = [];
  const seenSiblings = new Set<string>();

  return rows.map((row, index) => {
    const depth = depths[index];
    ancestry.length = depth;
    const parentKey = ancestry.slice(0, depth).filter(Boolean).map((item) => item!.key).join("/") || "root";
    const siblingKey = `${parentKey}:${depth}`;
    const hasPreviousSibling = seenSiblings.has(siblingKey);
    seenSiblings.add(siblingKey);
    const guide = {
      depth,
      ancestorDepths: ancestry.slice(0, depth)
        .filter((item) => item?.hasNextSibling)
        .map((item) => item!.depth),
      hasPreviousSibling,
      hasNextSibling: nextSibling[index]
    };
    ancestry[depth] = { key: row.key, depth, hasNextSibling: nextSibling[index] };
    return { ...row, treeGuide: guide };
  });
}

function TreeGuideLines({ guide }: { guide: TreeGuideData }) {
  const ownSegments = [
    guide.hasPreviousSibling ? "incoming" : "",
    guide.hasNextSibling ? "outgoing" : ""
  ].filter(Boolean);
  return <span className="tree-guide-layer" aria-hidden="true">
    {guide.ancestorDepths.map((depth) => <span key={`ancestor-${depth}`} className={`tree-guide-line tree-guide-depth-${depth}`} />)}
    {ownSegments.map((segment) => <span key={segment} className={`tree-guide-line tree-guide-depth-${guide.depth} tree-guide-${segment}`} />)}
  </span>;
}

function AlertCountBadge({ counts }: { counts: AlertCounts }) {
  if (counts.active === 0 && counts.recent === 0) return null;
  return <span className={`stream-alert-count stream-alert-${counts.severity ?? "warning"}`} title={[counts.active ? `${counts.active} active alert target${counts.active === 1 ? "" : "s"}` : "", counts.recent ? `${counts.recent} recovered recently` : ""].filter(Boolean).join(" · ")}>{counts.active > 0 && <b>!{counts.active}</b>}{counts.recent > 0 && <small>{counts.recent}</small>}</span>;
}

function alertCauseTitle(summary: StreamAlertSummary | undefined, state: "Active" | "Recent") {
  if (!summary) return "";
  const details = (summary.causes ?? []).map((cause) => (cause.category === "quality" ? "Quality" : "Other") + ": " + (cause.metric ?? cause.alertId));
  return [state, ...details].filter(Boolean).join(" · ");
}

function FlowAlertBadge({ alert, recentAlert }: { alert?: StreamAlertSummary; recentAlert?: StreamAlertSummary }) {
  const summary = alert ?? recentAlert;
  if (!summary) return null;
  return <span className={"stream-alert-count stream-alert-" + summary.severity} title={alertCauseTitle(summary, alert ? "Active" : "Recent")}><b>!</b></span>;
}

type OtherAlert = { severity: StreamAlertSummary["severity"]; causes: StreamAlertSummary["causes"] };
function severityRank(value: StreamAlertSummary["severity"] | undefined) { return value === "critical" ? 3 : value === "error" ? 2 : value === "warning" ? 1 : 0; }
function activeOtherAlert(summaries: Array<StreamAlertSummary | undefined>): OtherAlert | undefined {
  const causes = summaries.flatMap((summary) => (summary?.causes ?? []).filter((cause) => cause.category === "other"));
  if (causes.length === 0) return undefined;
  const severity = causes.reduce<StreamAlertSummary["severity"]>((highest, cause) => severityRank(cause.severity) > severityRank(highest) ? cause.severity : highest, "warning");
  return { severity, causes };
}
function otherAlertTitle(alert: OtherAlert | undefined) {
  if (!alert) return "No active non-quality alert";
  return alert.causes.map((cause) => (cause.metric ?? cause.alertId) + (cause.value !== undefined && cause.threshold !== undefined ? ": " + cause.value + " / " + cause.threshold : "")).join(" · ");
}

export function StreamTable({ streams, interfaces, selectedStreamKey, selectedFlowKey, selectedInterfaceKey, overviewMode = false, expandLevel = "flow", onSelectInterface, onSelectStream, onSelectFlow, onAddToDashboard, pickerMode = false, timeTravel = false, showAlerts = true, recentAlertRetentionMin = 30, referenceTimeSec, dismissedRecent: dismissedRecentProp, onClearRecent }: StreamTableProps) {
  const tableRef = useRef<HTMLDivElement>(null);
  const scrollingRef = useRef(false);
  const scrollIdleTimerRef = useRef<number | null>(null);
  const scrollRafRef = useRef<number | null>(null);
  const focusRequestRef = useRef<string | null>(null);
  const previousFocusRowKeyRef = useRef<string | null>(null);
  const suppressLocalFocusScrollRef = useRef<string | null>(null);
  const [expanded, setExpanded] = useState<Set<string>>(() => new Set());
  const [expandedInterfaces, setExpandedInterfaces] = useState<Set<string>>(() => new Set());
  const [expandedProtoGroups, setExpandedProtoGroups] = useState<Set<string>>(() => new Set());
  const [expandedScopeGroups, setExpandedScopeGroups] = useState<Set<string>>(() => new Set());
  const [localDismissedRecent, setLocalDismissedRecent] = useState<Set<string>>(() => new Set());
  const dismissedRecent = dismissedRecentProp ?? localDismissedRecent;
  const [alertCursor, setAlertCursor] = useState(-1);
  const [viewport, setViewport] = useState({ top: 0, height: 640 });
  const hasAppliedExpandLevel = useRef(false);
  const previousExpandLevel = useRef<typeof expandLevel>(expandLevel);
  const previousRects = useRef(new Map<string, DOMRect>());
  const seenProtoGroupKeys = useRef<Set<string>>(new Set());
  const maxStreamBitrate = useMemo(() => Math.max(...streams.map(streamBitrateOf), 1), [streams]);
  const interfaceGroups = useMemo(() => buildInterfaceGroups(interfaces, streams), [interfaces, streams]);
  const groupedByInterface = interfaceGroups.length > 0;
  const focusedStream = useMemo(() => selectedStreamKey ? streams.find((stream) => stream.streamKey === selectedStreamKey) ?? null : null, [selectedStreamKey, streams]);
  const focusedFlowAvailable = Boolean(selectedFlowKey && focusedStream?.flows.some((flow) => flow.flowKey === selectedFlowKey));
  const focusRowKey = focusedStream ? focusedFlowAvailable ? `flow:${focusedStream.streamKey}:${selectedFlowKey}` : `stream:${focusedStream.streamKey}` : null;
  const alertReferenceTimeSec = referenceTimeSec ?? Date.now() / 1000;
  const alertTargets = useMemo(() => showAlerts ? alertTargetsForStreams(streams, { dismissedRecent, referenceTimeSec: alertReferenceTimeSec, recentRetentionMin: recentAlertRetentionMin }) : [], [streams, dismissedRecent, showAlerts, alertReferenceTimeSec, recentAlertRetentionMin]);
  const alertCounts = useMemo(() => showAlerts ? alertCountsForStreams(streams, { dismissedRecent, referenceTimeSec: alertReferenceTimeSec, recentRetentionMin: recentAlertRetentionMin }) : { active: 0, recent: 0, severity: null }, [streams, dismissedRecent, showAlerts, alertReferenceTimeSec, recentAlertRetentionMin]);
  const groupAlertCounts = (items: StreamListItem[]) => showAlerts ? alertCountsForStreams(items, { dismissedRecent, referenceTimeSec: alertReferenceTimeSec, recentRetentionMin: recentAlertRetentionMin }) : { active: 0, recent: 0, severity: null };

  useEffect(() => {
    if (hasAppliedExpandLevel.current && previousExpandLevel.current === expandLevel) {
      return;
    }
    previousExpandLevel.current = expandLevel;
    setExpandedInterfaces(expandedInterfaceKeys(interfaceGroups, expandLevel));
    setExpanded(expandedStreamKeys(streams, expandLevel));
    setExpandedScopeGroups(expandedScopeKeys(interfaceGroups, expandLevel));
    if (expandLevel === "stream" || expandLevel === "flow") {
      setExpandedScopeGroups((current) => addSetValues(current, streams.flatMap((stream) => stream.streamGroup ? ["stream-group:" + stream.streamGroup.key] : [])));
    }
    setExpandedProtoGroups(expandedProtoKeys(interfaceGroups, streams, expandLevel));
    if (interfaceGroups.length > 0 || streams.length > 0) {
      hasAppliedExpandLevel.current = true;
    }
  }, [expandLevel, interfaceGroups, streams]);

  useEffect(() => {
    if (expandLevel !== "stream" && expandLevel !== "flow") return;
    const keys = protoGroupKeys(interfaceGroups, streams);
    if (keys.length === 0) return;
    setExpandedProtoGroups((current) => {
      const next = new Set(current);
      for (const key of keys) {
        if (!seenProtoGroupKeys.current.has(key)) {
          next.add(key);
          seenProtoGroupKeys.current.add(key);
        }
      }
      return next;
