}

function mergeSegments(segments: Array<{ start: number; end: number }>) {
  if (segments.length === 0) return [];
  const sorted = [...segments].sort((a, b) => a.start - b.start || a.end - b.end);
  const merged = [{ ...sorted[0] }];
  for (let index = 1; index < sorted.length; index += 1) {
    const current = sorted[index];
    const last = merged[merged.length - 1];
    if (current.start <= last.end) {
      last.end = Math.max(last.end, current.end);
    } else {
      merged.push({ ...current });
    }
  }
  return merged;
}

function mergeSegmentsNullable(segments: Array<{ start: number; end: number | null }>) {
  if (segments.length === 0) return [];
  const normalized = segments.map((segment) => ({
    start: segment.start,
    end: segment.end ?? Number.POSITIVE_INFINITY
  }));
  const merged = mergeSegments(normalized);
  return merged.map((segment) => ({
    start: segment.start,
    end: Number.isFinite(segment.end) ? segment.end : null
  }));
}

function buildTimelineDisplayGroups(rows: TimelineStreamGroup[], parentKey: string): TimelineDisplayGroup[] {
  const grouped = new Map<string, TimelineDisplayGroup>();
  const ungrouped: TimelineDisplayGroup[] = [];
  for (const row of rows) {
    const descriptor = row.stream.streamGroup;
    if (!descriptor) {
      ungrouped.push({ key: parentKey + "|stream:" + row.stream.streamKey, label: row.stream.label, rows: [row], grouped: false });
      continue;
    }
    const key = parentKey + "|group:" + descriptor.key;
    const current = grouped.get(key) ?? { key: descriptor.key, label: descriptor.label, confidence: descriptor.confidence, rows: [], grouped: true };
    current.rows.push(row);
    grouped.set(key, current);
  }
  const groupedItems = [...grouped.values()].flatMap((group) => group.rows.length > 1 ? [group] : [{ ...group, grouped: false }]);
  return [...groupedItems, ...ungrouped].sort((a, b) => a.label.localeCompare(b.label));
}

function makeTimelineGroupRow(group: TimelineDisplayGroup, rangeEndSec: number): TimelineRow {
  const first = group.rows[0].stream;
  const segments = mergeSegmentsNullable(group.rows.flatMap(({ stream }) => stream.segments));
  return {
    rowType: "stream", streamKey: "stream-group:" + group.key, kind: first.kind, proto: first.proto, label: group.label,
    ...(first.streamGroup ? { streamGroup: first.streamGroup } : {}),
    interfaceId: first.interfaceId, interfaceName: first.interfaceName, scope: first.scope,
    active: group.rows.some(({ stream }) => stream.active),
    firstSeen: Math.min(...group.rows.map(({ stream }) => stream.firstSeen)),
    lastSeen: Math.max(...group.rows.map(({ stream }) => stream.lastSeen)),
    segments: segments.map((segment) => ({ start: segment.start, end: segment.end === null || segment.end >= rangeEndSec ? null : segment.end }))
  };
}

function buildTimelineScopeGroups(rows: TimelineStreamGroup[], interfaceKey: string, rangeEndSec: number): TimelineScopeGroup[] {
  const groups = new Map<string, TimelineStreamGroup[]>();
  for (const item of rows) {
    const key = timelineScopeKey(item.stream.scope);
    const bucket = groups.get(key) ?? [];
    bucket.push(item);
    groups.set(key, bucket);
  }
  return [...groups.entries()]
    .map(([scopeKey, grouped]) => ({
      key: `${interfaceKey}::${scopeKey}`,
      label: timelineScopeLabel(grouped[0]?.stream.scope),
      rows: grouped,
      segments: mergeSegments(grouped.flatMap(({ stream }) => stream.segments.map((segment) => ({ start: segment.start, end: segment.end ?? rangeEndSec })))),
      active: grouped.some(({ stream }) => stream.active)
    }))
    .sort((a, b) => a.label.localeCompare(b.label));
}

