function FlowRow({ streamKey, flow, selected, overviewMode, enableCharts, onSelect, onAddToDashboard, pickerMode = false, showAlerts = true, recentAlertRetentionMin = 30, referenceTimeSec }: { streamKey: string; flow: FlowListItem; selected: boolean; overviewMode: boolean; enableCharts: boolean; onSelect: () => void; onAddToDashboard?: (streamKey: string, flowKey?: string) => void; pickerMode?: boolean; showAlerts?: boolean; recentAlertRetentionMin?: number; referenceTimeSec?: number }) {
