        group,
        eventTargetKeys: timelineEventTargetKeys(group.rows)
      });

      if (!(interfaceExpanded[group.key] ?? expandLevel !== "interface")) continue;
      const scopeGroups = buildTimelineScopeGroups(group.rows, group.key, range.end);

      for (const scopeGroup of scopeGroups) {
        const scopeIsExpanded = scopeExpanded[scopeGroup.key] ?? expandLevel !== "interface";
        items.push({
          key: `scope:${scopeGroup.key}`,
          type: "scope",
          height: 32,
          group: scopeGroup,
          parentKey: "if:" + group.key,
          expanded: scopeIsExpanded,
          onToggle: () => toggleTimelineTree("scope:" + scopeGroup.key, scopeIsExpanded, () => setScopeExpanded((current) => ({ ...current, [scopeGroup.key]: !scopeIsExpanded }))),
          eventTargetKeys: timelineEventTargetKeys(scopeGroup.rows)
        });
        if (!scopeIsExpanded) continue;
        const protoGroups = buildTimelineProtoGroups(scopeGroup.rows, scopeGroup.key, range.end);

        for (const protoGroup of protoGroups) {
          const groupExpanded = protoExpanded[protoGroup.key] ?? (expandLevel === "stream" || expandLevel === "flow");
        items.push({
          key: `proto:${protoGroup.key}`,
          type: "proto",
          height: 32,
          group: protoGroup,
          parentKey: "scope:" + scopeGroup.key,
          expanded: groupExpanded,
          onToggle: () => toggleTimelineTree("proto:" + protoGroup.key, groupExpanded, () => setProtoExpanded((current) => ({ ...current, [protoGroup.key]: !groupExpanded }))),
          eventTargetKeys: timelineEventTargetKeys(protoGroup.rows)
        });

          if (!groupExpanded) continue;
          for (const streamGroup of buildTimelineDisplayGroups(protoGroup.rows, protoGroup.key)) {
            if (streamGroup.grouped) {
              const groupRow = makeTimelineGroupRow(streamGroup, range.end);
              const groupIsExpanded = expanded[streamGroup.key] ?? (expandLevel === "stream" || expandLevel === "flow");
              items.push({
                key: "group:" + streamGroup.key, type: "group", height: 32, row: groupRow, rowKey: streamGroup.key,
                parentKey: "proto:" + protoGroup.key, childCount: streamGroup.rows.length, expanded: groupIsExpanded,
                onToggle: () => toggleTimelineTree("group:" + streamGroup.key, groupIsExpanded, () => setExpanded((current) => ({ ...current, [streamGroup.key]: !groupIsExpanded }))),
                eventTargetKeys: timelineEventTargetKeys(streamGroup.rows)
              });
              if (!groupIsExpanded) continue;
            }
            for (const { stream, flows } of streamGroup.rows) {
          const isExpanded = expanded[stream.streamKey] ?? expandLevel === "flow";
          items.push({
            key: `stream:${stream.streamKey}`,
            type: "stream",
            height: 32,
            row: stream,
            rowKey: stream.streamKey,
            parentKey: "proto:" + protoGroup.key,
            childCount: flows.length,
            expanded: isExpanded,
            onToggle:
              flows.length > 0
                ? () => toggleTimelineTree("stream:" + stream.streamKey, isExpanded, () => setExpanded((current) => ({ ...current, [stream.streamKey]: !isExpanded })))
                : undefined,
            eventTargetKeys: timelineEventTargetKeys([{ stream, flows }])
          });

            if (!isExpanded) continue;
            for (const flow of flows) {
            const flowKey = `${stream.streamKey}::${flow.flowKey ?? flow.streamKey}`;
              items.push({
              key: `flow:${flowKey}`,
              type: "flow",
              height: 32,
              row: flow,
              rowKey: flowKey,
              parentKey: "stream:" + stream.streamKey,
              eventTargetKeys: [timelineRowEventTargetKey(flow)]
              });
            }
          }
        }
      }
    }
    }
    return items;
  }, [groupedByInterface, interfaceExpanded, scopeExpanded, expanded, protoExpanded, range.end, expandLevel, treeAnimation]);

  const visibleRowEventBuckets = useMemo(() => {
    const bucketsByRow = buildVisibleTimelineEventBuckets(markerEvents, range, baseRows);
    return new Map([...bucketsByRow.entries()].map(([rowKey, buckets]) => [
      rowKey,
      clusterEventMarkerBuckets(buckets, range, axisWidth)
    ]));
  }, [axisWidth, markerEvents, range, baseRows]);

  const guidedRows = useMemo(() => {
    const depthOf = (item: (typeof baseRows)[number]) => {
      switch (item.type) {
        case "interface": return 0;
        case "scope": return 1;
        case "proto": return 2;
        case "group": return 3;
        case "stream": return 4;
        case "flow": return 5;
      }
    };
    const depths = baseRows.map(depthOf);
    const nextSibling = baseRows.map((_, index) => {
      const depth = depths[index];
      for (let next = index + 1; next < baseRows.length; next += 1) {
        if (depths[next] < depth) return false;
        if (depths[next] === depth) return true;
      }
      return false;
    });
    const ancestry: Array<{ key: string; depth: number; hasNextSibling: boolean } | undefined> = [];
    const seenSiblings = new Set<string>();

    return baseRows.map((row, index) => {
      const depth = depths[index];
      ancestry.length = depth;
      const parentKey = ancestry.slice(0, depth).filter(Boolean).map((item) => item!.key).join("/") || "root";
      const siblingKey = `${parentKey}:${depth}`;
      const hasPreviousSibling = seenSiblings.has(siblingKey);
      seenSiblings.add(siblingKey);
      const guide = {
        depth,
        ancestorDepths: ancestry.slice(0, depth)
          .filter((item) => item?.hasNextSibling)
          .map((item) => item!.depth),
        hasPreviousSibling,
        hasNextSibling: nextSibling[index],
      };
      ancestry[depth] = { key: row.key, depth, hasNextSibling: nextSibling[index] };
      return { ...row, treeGuide: guide };
    });
  }, [baseRows]);

    return pieces.filter((piece) => piece.end > piece.start).map((piece) => ({
      start: piece.start,
      end: segment.end === null && piece.end >= range.end ? null : piece.end
    }));
  });
}

function renderSegment(row: TimelineRow, segment: { start: number; end: number | null }, index: number, range: { start: number; end: number }, fadeSec: number) {
  const fullEnd = segment.end ?? range.end;
  const start = percent(segment.start, range.start, range.end);
  const end = percent(fullEnd, range.start, range.end);
  const width = Math.max(0.6, end - start);
  const baseClass = row.rowType === "flow" ? "timeline-segment-flow" : row.rowType === "stream" ? "timeline-segment-stream" : "timeline-segment-interface";
  const key = `${row.flowKey ?? row.streamKey}:${index}:${segment.start}`;

  if (segment.end === null) {
    return (
      <div
        key={key}
        className={`timeline-segment ${baseClass} active`}
        style={{
          left: `${start}%`,
          width: `${width}%`
        }}
      />
    );
  }

  const fadeStart = Math.max(segment.start, fullEnd - fadeSec);
  if (fadeStart <= segment.start + 1e-6) {
    return (
      <div
        key={key}
        className={`timeline-segment ${baseClass} timeline-segment-fade active`}
        style={{
          left: `${start}%`,
          width: `${width}%`
        }}
      />
    );
  }

  const solidEnd = percent(fadeStart, range.start, range.end);
  const fadeBegin = percent(fadeStart, range.start, range.end);
  const fadeWidth = Math.max(0.6, end - fadeBegin);

  return (
    <Fragment key={key}>
      <div
        key={`${key}:solid`}
        className={`timeline-segment ${baseClass} timeline-segment-split-solid active`}
        style={{
          left: `${start}%`,
          width: `${Math.max(0.6, solidEnd - start)}%`
        }}
      />
      <div
        key={`${key}:fade`}
        className={`timeline-segment ${baseClass} timeline-segment-fade timeline-segment-split-fade active`}
        style={{
          left: `${fadeBegin}%`,
          width: `${fadeWidth}%`
        }}
      />
    </Fragment>
  );
}

function percent(value: number, start: number, end: number) {
  return ((value - start) / Math.max(1e-6, end - start)) * 100;
}

function clampPercent(value: number) {
  return Math.min(99.5, Math.max(0.5, value));
}

function formatTick(value: number, spanSec: number) {
  return new Date(value * 1000).toLocaleTimeString([], {
    hour12: false,
    hour: "2-digit",
    minute: "2-digit",
    second: spanSec <= 600 ? "2-digit" : undefined
  });
}

function formatCursor(value: number) {
  return new Date(value * 1000).toLocaleString([], {
    hour12: false,
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    year: "numeric",
    month: "2-digit",
    day: "2-digit"
  });
}

function formatEventTime(value: number) {
  return new Date(value * 1000).toLocaleString([], {
    hour12: false,
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    fractionalSecondDigits: 3,
    year: "numeric",
    month: "2-digit",
    day: "2-digit"
  });
}

function mergeSegments(segments: Array<{ start: number; end: number }>) {
  if (segments.length === 0) return [];
  const sorted = [...segments].sort((a, b) => a.start - b.start || a.end - b.end);
  const merged = [{ ...sorted[0] }];
  for (let index = 1; index < sorted.length; index += 1) {
    const current = sorted[index];
    const last = merged[merged.length - 1];
    if (current.start <= last.end) {
      last.end = Math.max(last.end, current.end);
    } else {
      merged.push({ ...current });
    }
  }
  return merged;
}

function mergeSegmentsNullable(segments: Array<{ start: number; end: number | null }>) {
  if (segments.length === 0) return [];
  const normalized = segments.map((segment) => ({
    start: segment.start,
    end: segment.end ?? Number.POSITIVE_INFINITY
  }));
  const merged = mergeSegments(normalized);
  return merged.map((segment) => ({
    start: segment.start,
    end: Number.isFinite(segment.end) ? segment.end : null
  }));
}

function buildTimelineDisplayGroups(rows: TimelineStreamGroup[], parentKey: string): TimelineDisplayGroup[] {
  const grouped = new Map<string, TimelineDisplayGroup>();
  const ungrouped: TimelineDisplayGroup[] = [];
  for (const row of rows) {
    const descriptor = row.stream.streamGroup;
    if (!descriptor) {
      ungrouped.push({ key: parentKey + "|stream:" + row.stream.streamKey, label: row.stream.label, rows: [row], grouped: false });
      continue;
    }
    const key = parentKey + "|group:" + descriptor.key;
    const current = grouped.get(key) ?? { key: descriptor.key, label: descriptor.label, confidence: descriptor.confidence, rows: [], grouped: true };
    current.rows.push(row);
    grouped.set(key, current);
  }
  const groupedItems = [...grouped.values()].flatMap((group) => group.rows.length > 1 ? [group] : [{ ...group, grouped: false }]);
  return [...groupedItems, ...ungrouped].sort((a, b) => a.label.localeCompare(b.label));
}

function makeTimelineGroupRow(group: TimelineDisplayGroup, rangeEndSec: number): TimelineRow {
  const first = group.rows[0].stream;
  const segments = mergeSegmentsNullable(group.rows.flatMap(({ stream }) => stream.segments));
  return {
    rowType: "stream", streamKey: "stream-group:" + group.key, kind: first.kind, proto: first.proto, label: group.label,
    ...(first.streamGroup ? { streamGroup: first.streamGroup } : {}),
    interfaceId: first.interfaceId, interfaceName: first.interfaceName, scope: first.scope,
    active: group.rows.some(({ stream }) => stream.active),
    firstSeen: Math.min(...group.rows.map(({ stream }) => stream.firstSeen)),
    lastSeen: Math.max(...group.rows.map(({ stream }) => stream.lastSeen)),
    segments: segments.map((segment) => ({ start: segment.start, end: segment.end === null || segment.end >= rangeEndSec ? null : segment.end }))
  };
}

function buildTimelineScopeGroups(rows: TimelineStreamGroup[], interfaceKey: string, rangeEndSec: number): TimelineScopeGroup[] {
  const groups = new Map<string, TimelineStreamGroup[]>();
  for (const item of rows) {
    const key = timelineScopeKey(item.stream.scope);
    const bucket = groups.get(key) ?? [];
    bucket.push(item);
    groups.set(key, bucket);
  }
  return [...groups.entries()]
    .map(([scopeKey, grouped]) => ({
      key: `${interfaceKey}::${scopeKey}`,
      label: timelineScopeLabel(grouped[0]?.stream.scope),
      rows: grouped,
      segments: mergeSegments(grouped.flatMap(({ stream }) => stream.segments.map((segment) => ({ start: segment.start, end: segment.end ?? rangeEndSec })))),
      active: grouped.some(({ stream }) => stream.active)
    }))
    .sort((a, b) => a.label.localeCompare(b.label));
}

function timelineScopeKey(scope: NetworkScope | undefined) {
  if (!scope?.known) return "unknown";
  if (scope.layers.length === 0) return "untagged";
  return scope.layers.map((layer) => layer.kind === "vlan"
    ? `vlan:${layer.id ?? "unknown"}:${layer.priority ?? ""}:${layer.dei ?? ""}`
    : `vxlan:${layer.vni ?? "unknown"}`).join("|");
