  const renderScopeRow = (scopeGroup: ScopeGroup) => {
    const opened = expandedScopeGroups.has(scopeGroup.key);
    const active = scopeGroup.streams.some((stream) => stream.active);
    const bitrate = scopeGroup.streams.reduce((sum, stream) => sum + streamBitrateOf(stream), 0);
    const sparkline = sumSparklines(scopeGroup.streams.map((stream) => stream.sparkline));
    return (
      <div className="scope-tree">
        <div className="scope-row">
          <button type="button" className={`tree-toggle expandable ${opened ? "open" : ""}`} aria-label={`${opened ? "Collapse" : "Expand"} ${scopeGroup.label}`} onClick={() => toggleScopeGroup(scopeGroup.key)}><Icon name="expand" size={15} /></button>
          <span className={`proto-status ${active ? "active" : "stale"}`} />
          <span className="proto-main"><span className="proto-title"><strong>{scopeGroup.label}</strong><DescendantCountBadge count={scopeGroup.streams.length} /><AlertCountBadge counts={groupAlertCounts(scopeGroup.streams)} /></span></span>
          <span className="stream-traffic-block"><span className="stream-rate">{formatBitrate(bitrate)}</span></span>
          {ENABLE_SPARKLINES && <span className="stream-trend-block"><Sparkline values={sparkline} width={150} height={24} color="var(--chart-sparkline)" strokeWidth={1.1} /></span>}
        </div>
      </div>
    );
  };

  const renderProtoRow = (protoGroup: { key: string; proto: string; streams: StreamListItem[] }) => {
    const opened = expandedProtoGroups.has(protoGroup.key);
    const active = protoGroup.streams.some((stream) => stream.active);
    const bitrate = protoGroup.streams.reduce((sum, stream) => sum + streamBitrateOf(stream), 0);
    const sparkline = sumSparklines(protoGroup.streams.map((stream) => stream.sparkline));
    return (
      <div className="proto-tree proto-tree-virtual" data-flip-key={`proto:${protoGroup.key}`}>
        <div className="proto-row">
          <button type="button" className={`tree-toggle expandable ${opened ? "open" : ""}`} aria-label={`${opened ? "Collapse" : "Expand"} ${protoGroup.proto}`} onClick={() => toggleProtoGroup(protoGroup.key)}><Icon name="expand" size={15} /></button>
          <span className={`proto-status ${active ? "active" : "stale"}`} />
          <span className="proto-main">
            <span className="proto-title">
              <strong>{protoGroup.proto}</strong>
              <DescendantCountBadge count={protoGroup.streams.length} /><AlertCountBadge counts={groupAlertCounts(protoGroup.streams)} />
            </span>
          </span>
          <span className="stream-traffic-block"><span className="stream-rate">{formatBitrate(bitrate)}</span></span>
          {ENABLE_SPARKLINES && <span className="stream-trend-block"><Sparkline values={sparkline} width={150} height={24} color="var(--chart-sparkline)" strokeWidth={1.1} /></span>}
        </div>
      </div>
    );
  };

  const renderInterfaceRow = (group: InterfaceGroup) => {
    const opened = expandedInterfaces.has(group.key);
    return (
      <div className="interface-tree interface-tree-virtual" data-flip-key={`interface:${group.key}`}>
        <div
          className={`interface-row ${group.interfaceItem?.key === selectedInterfaceKey ? "selected" : ""}`}
          role={group.interfaceItem ? "button" : undefined}
          tabIndex={group.interfaceItem ? 0 : undefined}
          onClick={() => { if (group.interfaceItem) onSelectInterface(group.interfaceItem.key); }}
          onKeyDown={(event) => {
            if (!group.interfaceItem || event.target !== event.currentTarget || (event.key !== "Enter" && event.key !== " ")) return;
            event.preventDefault();
            onSelectInterface(group.interfaceItem.key);
          }}
        >
          <button type="button" className={`tree-toggle expandable ${opened ? "open" : ""}`} aria-label={`${opened ? "Collapse" : "Expand"} ${group.name}`} onClick={(event) => { event.stopPropagation(); toggleInterface(group.key); }}><Icon name="expand" size={15} /></button>
          <span className={`interface-status ${group.interfaceItem?.available !== false ? "active" : "stale"}`} />
          <span className="interface-main">
            <span className="interface-title"><strong>{group.name}</strong><span className="interface-link-summary">{formatLinkSummary(group.interfaceItem)}</span><DescendantCountBadge count={group.streams.length} /><AlertCountBadge counts={groupAlertCounts(group.streams)} /></span>
          </span>
          {ENABLE_OVERVIEW_CHARTS && <InterfaceHeadroomGauge item={group.interfaceItem} />}
          <span className="interface-sparklines">
            <span className="interface-rate-row">
              <span className="interface-rate-label">RX</span>
              <span className="interface-rate-value">{formatBitrate(interfaceBitrateOf(group.interfaceItem, "rx"))}</span>
              {ENABLE_SPARKLINES && <Sparkline values={group.interfaceItem?.rxSparkline ?? []} width={150} height={18} color="var(--chart-rx)" strokeWidth={1.1} />}
            </span>
            <span className="interface-rate-row">
              <span className="interface-rate-label">TX</span>
              <span className="interface-rate-value">{formatBitrate(interfaceBitrateOf(group.interfaceItem, "tx"))}</span>
              {ENABLE_SPARKLINES && <Sparkline values={group.interfaceItem?.txSparkline ?? []} width={150} height={18} color="var(--chart-tx)" strokeWidth={1.1} />}
            </span>
          </span>
        </div>
      </div>
    );
  };

  const renderTruncatedRow = (row: Extract<FlatRow, { type: "truncated" }>) => {
    const className = row.depth === "flow" ? "flow-list-row flow-list-row-truncated stream-table-virtual-flow" : "stream-row stream-row-truncated stream-table-virtual-stream";
    return (
      <div className={className}>
        <span className="flow-main stream-main">
          <span className="flow-subtitle stream-subtitle">{row.label}</span>
        </span>
      </div>
    );
  };

  return (
    <div
      ref={tableRef}
      className={`stream-table ${overviewMode ? "overview-mode" : ""} ${pickerMode ? "picker-mode" : ""}`}
      onScroll={() => {
        scrollingRef.current = true;
        if (scrollRafRef.current === null) {
          scrollRafRef.current = window.requestAnimationFrame(() => {
            scrollRafRef.current = null;
            const root = tableRef.current;
            if (!root) return;
            setViewport((current) => {
              const next = { top: root.scrollTop, height: root.clientHeight || 640 };
              return current.top === next.top && current.height === next.height ? current : next;
            });
          });
        }
        if (scrollIdleTimerRef.current !== null) {
          window.clearTimeout(scrollIdleTimerRef.current);
        }
        scrollIdleTimerRef.current = window.setTimeout(() => {
          scrollingRef.current = false;
        }, 140);
      }}
    >
      {overviewMode && ENABLE_OVERVIEW_CHARTS && <StreamOverviewSummary streams={streams} />}
      <div className="stream-sticky-context-anchor">
        <div className={`stream-sticky-context ${stickyContext.length > 0 ? "is-visible" : ""}`} aria-label="Current stream hierarchy" aria-hidden={stickyContext.length === 0}>{stickyContext.map((item, index) => <span className="stream-context-segment" key={`${item.kind}:${item.label}:${index}`}>
          {index > 0 && <span className="stream-context-separator" aria-hidden="true">›</span>}
          <span className={`stream-context-chip stream-context-${item.kind}${item.kind === "proto" ? " stream-context-proto-" + streamContextProtoClass(item.proto) : ""}`} title={item.title ?? item.label}>{item.label}</span>
        </span>)}</div>
      </div>
      {showAlerts && <div className="stream-alert-summary-anchor">
        <div className={`stream-alert-summary is-visible`} aria-live="polite">
          <span className="stream-alert-summary-label">{alertCounts.active > 0 && <strong className={`stream-alert-${alertCounts.severity ?? "warning"}`}>{alertCounts.severity === "warning" ? "Warnings" : "Errors"} {alertCounts.active}</strong>}{alertCounts.recent > 0 && <span>Recent {alertCounts.recent}</span>}</span>
          <span className="stream-alert-summary-actions">
            <button type="button" onClick={() => navigateAlert(-1)} disabled={alertTargets.length === 0} aria-label="Previous alert">‹</button>
            <button type="button" onClick={() => navigateAlert(1)} disabled={alertTargets.length === 0} aria-label="Next alert">›</button>
            <button type="button" onClick={clearRecentAlerts} disabled={timeTravel || alertCounts.recent === 0} title={timeTravel ? "Unavailable in Time travel" : alertCounts.recent === 0 ? "No recent alerts" : undefined}>Clear recent</button>
          </span>
        </div>
      </div>}
      {virtualRows.topPad > 0 ? <div style={{ height: virtualRows.topPad }} /> : null}
      {virtualRows.visible.map((row) => (
        <div key={row.key} className={`stream-table-virtual-item stream-table-virtual-item-${row.type}`} style={{ height: row.height }}>
          <TreeGuideLines guide={row.treeGuide} />
          {row.type === "interface" ? renderInterfaceRow(row.group)
            : row.type === "scope" ? renderScopeRow(row.group)
            : row.type === "proto" ? renderProtoRow(row.group)
              : row.type === "group" ? renderScopeRow(row.group)
              : row.type === "stream" ? renderStreamRow(row.stream)
                : row.type === "flow" ? (
                  <div className="stream-table-virtual-flow">
                    <FlowRow
                      streamKey={row.stream.streamKey}
                      flow={row.flow}
                      selected={row.flow.flowKey === selectedFlowKey}
                  isHovered={hoveredRowKey === item.group.key}
                  onHoverChange={setHoveredRowKey}
                  onToggle={item.onToggle}
                  eventBuckets={visibleRowEventBuckets.get(item.key) ?? []}
                  selectedEventId={selectedEventId}
                  activeBucketEventIds={activeBucketEventIds}
                  previewedEventId={previewedEventId}
                  onSelectEvent={activateTimelineEventBucket}
                />
              </div>
            );
          }

          if (item.type === "scope") {
            return (
              <div key={item.key} className={"timeline-virtual-item" + animationClass} style={{ height: item.height }}>
                <TimelineTreeGuideLines guide={item.treeGuide} />
                <TimelineScopeLane
                  group={item.group}
                  range={range}
                  gaps={gaps}
                  cursorPercent={clampPercent(cursorPercent)}
                  cursorSec={cursorSec}
                  expanded={item.expanded}
                  isHovered={hoveredRowKey === item.group.key}
                  onHoverChange={setHoveredRowKey}
                  onToggle={item.onToggle}
                  eventBuckets={visibleRowEventBuckets.get(item.key) ?? []}
                  selectedEventId={selectedEventId}
                  activeBucketEventIds={activeBucketEventIds}
                  previewedEventId={previewedEventId}
                  onSelectEvent={activateTimelineEventBucket}
                />
              </div>
            );
          }

          return (
            <div key={item.key} className={"timeline-virtual-item" + animationClass} style={{ height: item.height }}>
              <TimelineTreeGuideLines guide={item.treeGuide} />
              <TimelineLane
                rowKey={item.rowKey}
                row={item.row}
                range={range}
                gaps={gaps}
                cursorPercent={clampPercent(cursorPercent)}
                cursorSec={cursorSec}
                fadeSec={fadeSec}
                isHovered={hoveredRowKey === item.rowKey}
                onHoverChange={setHoveredRowKey}
                childCount={item.childCount ?? 0}
                expanded={item.expanded ?? false}
                onToggle={item.onToggle}
                eventBuckets={visibleRowEventBuckets.get(item.key) ?? []}
                selectedEventId={selectedEventId}
                activeBucketEventIds={activeBucketEventIds}
                previewedEventId={previewedEventId}
                onSelectEvent={activateTimelineEventBucket}
              />
            </div>
          );
        })}
        {virtualized.bottomPad > 0 ? <div style={{ height: virtualized.bottomPad }} /> : null}
      </div>
    </div>
  );
}

type EventMarkerBucket = { key: string; time: number; level: "warn" | "error"; events: EventLogItem[]; primary: EventLogItem };

const MAX_EVENT_MARKERS = 240;
const EVENT_MARKER_MIN_DISTANCE_PX = 18;
const TIME_TICK_STEPS_SEC = [
  0.1, 0.2, 0.5,
  1, 2, 5, 10, 15, 30,
  60, 120, 300, 600, 900, 1800,
  3600, 7200, 10800, 21600, 43200, 86400
];
const EVENT_BUCKET_STEPS_SEC = [
  0.1, 0.2, 0.5,
  1, 2, 5, 10, 15, 30,
  60, 120, 300, 600, 900, 1800,
  3600, 7200, 14400, 28800, 43200, 86400
];

function TimelineTimeGrid({ ticks, range }: { ticks: number[]; range: { start: number; end: number } }) {
  return <div className="timeline-time-grid" aria-hidden="true">
    {ticks.map((tick) => <span key={tick} className="timeline-time-grid-line" style={{ left: String(percent(tick, range.start, range.end)) + "%" }} />)}
  </div>;
}

function TimelineEventRail({ buckets, gaps, range, cursorPercent, selectedEventId, activeBucketEventIds, previewedEventId, onActivateBucket }: {
  buckets: EventMarkerBucket[];
  gaps: TimelineDataGap[];
  range: { start: number; end: number };
  cursorPercent: number;
  selectedEventId: string | null;
  activeBucketEventIds: ReadonlySet<string>;
  previewedEventId: string | null;
  onActivateBucket: (bucket: EventMarkerBucket) => void;
}) {
  return (
    <div className="timeline-event-rail" aria-label="Warning and error events">
      <TimelineGapBands gaps={gaps} range={range} />
      <div className="timeline-cursor-line" style={{ left: String(cursorPercent) + "%" }} aria-hidden="true" />
      {buckets.map((bucket) => {
        const selected = bucket.events.some((event) => event.id === selectedEventId);
        const inActiveBucket = bucket.events.some((event) => activeBucketEventIds.has(event.id));
        const previewed = bucket.events.some((event) => event.id === previewedEventId);
        const label = eventMarkerLabel(bucket);
        return <button
          key={bucket.key}
          type="button"
          className={"timeline-event-marker " + bucket.level + (selected ? " selected" : "") + (inActiveBucket ? " in-event-bucket" : "") + (previewed ? " previewed" : "")}
          style={{ left: String(percent(bucket.time, range.start, range.end)) + "%" }}
          title={label}
          aria-label={label}
          onClick={(event) => { event.stopPropagation(); onActivateBucket(bucket); }}
        >
          <span aria-hidden="true">{bucket.events.length > 1 ? bucket.events.length : "!"}</span>
        </button>;
      })}
    </div>
  );
}

const TimelineEventBucketPopover = forwardRef<HTMLDivElement, {
  bucket: EventMarkerBucket;
  onClose: () => void;
  onSelectEvent: (event: EventLogItem) => void;
  onPreviewEvent: (eventId: string | null) => void;
  canRevealEvent: (event: EventLogItem) => boolean;
