  position: relative;
  z-index: 1;
}

/* Allow endpoint labels to remain readable over the chart area. */
.timeline-row-label {
  position: relative;
  z-index: 3;
  overflow: visible;
}

.timeline-row-track,
.timeline-interface-track,
.timeline-proto-track {
  position: relative;
