  gaps,
  cursorPercent,
  cursorSec,
  fadeSec,
  isHovered,
  onHoverChange,
  childCount = 0,
  expanded = true,
  onToggle,
  eventBuckets,
  selectedEventId,
  activeBucketEventIds,
  previewedEventId,
  onSelectEvent
}: {
  rowKey: string;
  row: TimelineRow;
  range: { start: number; end: number };
  cursorPercent: number;
  gaps: TimelineDataGap[];
