  const baseRows = useMemo(() => {
    const rows: FlatRow[] = [];

    const appendStreamCollection = (collection: StreamListItem[], groupKey: string) => {
      for (const scopeGroup of buildScopeGroups(collection, groupKey)) {
        rows.push({ key: "scope:" + scopeGroup.key, type: "scope", height: STREAM_TABLE_ROW_HEIGHT.scope, group: scopeGroup, treeLevel: 1 });
        if (!expandedScopeGroups.has(scopeGroup.key)) continue;
        for (const protoGroup of buildProtoGroups(scopeGroup.streams, scopeGroup.key)) {
          rows.push({ key: "proto:" + protoGroup.key, type: "proto", height: STREAM_TABLE_ROW_HEIGHT.proto, group: protoGroup, treeLevel: 2 });
          if (!expandedProtoGroups.has(protoGroup.key)) continue;
          for (const streamGroup of buildStreamDisplayGroups(protoGroup.streams, protoGroup.key)) {
            if (streamGroup.grouped) {
              rows.push({ key: "group:stream-group:" + streamGroup.key, type: "group", height: STREAM_TABLE_ROW_HEIGHT.group, group: { ...streamGroup, key: "stream-group:" + streamGroup.key }, treeLevel: 3 });
              if (!expandedScopeGroups.has("stream-group:" + streamGroup.key)) continue;
            }
            for (const stream of streamGroup.streams.slice(0, MAX_STREAM_ROWS_PER_GROUP)) {
              rows.push({ key: "stream:" + stream.streamKey, type: "stream", height: STREAM_TABLE_ROW_HEIGHT.stream, stream, treeLevel: streamGroup.grouped ? 4 : 3 });
              if (!isExpandable(stream) || !expanded.has(stream.streamKey)) continue;
              for (const flow of stream.flows.slice(0, MAX_FLOW_ROWS_PER_STREAM)) {
                rows.push({ key: "flow:" + stream.streamKey + ":" + flow.flowKey, type: "flow", height: STREAM_TABLE_ROW_HEIGHT.flow, stream, flow, treeLevel: streamGroup.grouped ? 5 : 4 });
              }
            }
          }
        }
      }
    };

    if (groupedByInterface) {
      for (const group of interfaceGroups) {
        rows.push({
          key: `interface:${group.key}`,
          type: "interface",
          height: STREAM_TABLE_ROW_HEIGHT.interface,
          group,
          treeLevel: 0
        });
        if (expandedInterfaces.has(group.key)) {
          appendStreamCollection(group.streams, group.key);
        }
      }
    } else {
      appendStreamCollection(streams, "root");
    }

    return rows;
  }, [expanded, expandedInterfaces, expandedScopeGroups, expandedProtoGroups, groupedByInterface, interfaceGroups, streams]);
